css:
/* LIFE Asset Management Dashboard — Complete CSS V88
   Base stylesheet plus all current JavaScript-injected enhancements. */

/* =========================================================
   HIDE ERPNEXT WEBSITE HEADER
   Removes: Contact · Blog · Products · user initial
   ========================================================= */
body > header.navbar,
body > nav.navbar,
header.web-header,
nav.web-header,
.web-header,
.website-header,
.navbar.navbar-expand-lg,
.navbar.navbar-expand-md {
  display: none !important;
}

/* Remove the space reserved for the standard website header */
html,
body {
  margin-top: 0 !important;
  padding-top: 0 !important;
}

body .page-container,
body .web-page-content,
body .main-section,
body main.container,
body .page-content-wrapper {
  margin-top: 0 !important;
  padding-top: 0 !important;
}

.life-asset-app {
  --la-forest: #1e5631;
  --la-forest-dark: #143c22;
  --la-forest-light: #2e7d4f;
  --la-leaf: #8cc63f;
  --la-leaf-soft: #eaf4dc;
  --la-leaf-mid: #cfe7a8;
  --la-gold: #b8860b;
  --la-gold-light: #e4c466;
  --la-gold-soft: #fbf3dc;
  --la-ink: #1b2a22;
  --la-ink-2: #33473b;
  --la-muted: #5e7266;
  --la-faint: #8a9a90;
  --la-line: #dde7da;
  --la-line-2: #edf2ea;
  --la-paper: #f5f8f3;
  --la-white: #ffffff;
  --la-ok: #2e7d32;
  --la-ok-bg: #e8f4e9;
  --la-warn: #b37400;
  --la-warn-bg: #fdf3df;
  --la-bad: #b3261e;
  --la-bad-bg: #fbe9e7;
  --la-info: #1b5e8a;
  --la-info-bg: #e6f0f7;
  --la-grey: #6b7a72;
  --la-grey-bg: #eff2f0;
  --la-purple: #6b4d9c;
  --la-purple-bg: #f1ecf8;
  --la-shadow: 0 1px 2px rgba(20, 60, 34, 0.06), 0 6px 18px rgba(20, 60, 34, 0.06);
  --la-radius: 10px;
  min-height: 100vh;
  margin: 0;
  color: var(--la-ink);
  background: var(--la-paper);
  font-family: "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

.life-asset-app,
.life-asset-app * {
  box-sizing: border-box;
}

.life-asset-app button,
.life-asset-app input,
.life-asset-app select,
.life-asset-app textarea {
  font: inherit;
  color: inherit;
}

.life-asset-app button {
  cursor: pointer;
}

.life-asset-app h1,
.life-asset-app h2,
.life-asset-app h3,
.life-asset-app h4,
.life-asset-app .la-display {
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 600;
  letter-spacing: 0.1px;
}

.life-asset-app a {
  color: var(--la-forest);
}

.life-asset-app ::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

.life-asset-app ::-webkit-scrollbar-thumb {
  background: #c6d4c6;
  border-radius: 6px;
}

.life-asset-app ::-webkit-scrollbar-track {
  background: transparent;
}

/* Top bar */
.life-asset-app .la-topbar {
  position: sticky;
  top: 0;
  z-index: 80;
  color: #fff;
  background: linear-gradient(100deg, var(--la-forest-dark), var(--la-forest) 55%, var(--la-forest-light));
  border-bottom: 3px solid var(--la-gold);
}

.life-asset-app .la-topbar-main {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 58px;
  padding: 8px 16px;
}

.life-asset-app .la-brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.life-asset-app .la-logo {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 39px;
  height: 39px;
  border-radius: 9px;
  color: #123a1d;
  background: linear-gradient(150deg, var(--la-leaf), #5fa02a);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
  font-family: Georgia, serif;
  font-size: 20px;
  font-weight: 700;
}

.life-asset-app .la-brand-copy {
  min-width: 0;
}

.life-asset-app .la-brand-title {
  font-family: Georgia, serif;
  font-size: 17px;
  line-height: 1.15;
  letter-spacing: 0.3px;
}

.life-asset-app .la-brand-subtitle {
  max-width: 720px;
  margin-top: 2px;
  overflow: hidden;
  color: #cfe3cb;
  font-size: 10.5px;
  letter-spacing: 1.1px;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.life-asset-app .la-topbar-spacer {
  flex: 1;
}

.life-asset-app .la-top-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  color: #fff;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 7px;
  font-size: 12px;
}

.life-asset-app .la-top-button:hover {
  background: rgba(255, 255, 255, 0.2);
}

.life-asset-app .la-amount-toggle {
  display: flex;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 7px;
}

.life-asset-app .la-amount-toggle button {
  padding: 6px 9px;
  color: #dcebd8;
  background: transparent;
  border: 0;
  border-right: 1px solid rgba(255, 255, 255, 0.16);
  font-size: 12px;
}

.life-asset-app .la-amount-toggle button:last-child {
  border-right: 0;
}

.life-asset-app .la-amount-toggle button.is-active {
  color: #2a1f00;
  background: var(--la-gold);
  font-weight: 700;
}

.life-asset-app .la-user-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 9px 4px 4px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 22px;
}

.life-asset-app .la-user-avatar {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  color: #3a2a00;
  background: linear-gradient(140deg, var(--la-gold-light), var(--la-gold));
  border-radius: 50%;
  font-family: Georgia, serif;
  font-size: 12px;
  font-weight: 700;
}

.life-asset-app .la-user-name {
  max-width: 150px;
  overflow: hidden;
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.life-asset-app .la-user-role {
  color: #cfe3cb;
  font-size: 10.5px;
}

.life-asset-app .la-live-strip {
  display: flex;
  align-items: center;
  min-height: 27px;
  background: rgba(0, 0, 0, 0.2);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 12px;
}

.life-asset-app .la-live-label {
  display: flex;
  align-items: center;
  gap: 6px;
  align-self: stretch;
  padding: 5px 12px;
  color: #2a1f00;
  background: var(--la-gold);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 1.2px;
}

.life-asset-app .la-live-dot {
  width: 7px;
  height: 7px;
  background: var(--la-ok);
  border-radius: 50%;
  box-shadow: 0 0 0 0 rgba(46, 125, 50, 0.65);
  animation: la-ping 2.2s infinite;
}

@keyframes la-ping {
  70% { box-shadow: 0 0 0 8px rgba(46, 125, 50, 0); }
  100% { box-shadow: 0 0 0 0 rgba(46, 125, 50, 0); }
}

.life-asset-app .la-live-message {
  flex: 1;
  min-width: 0;
  padding: 4px 12px;
  overflow: hidden;
  color: #e6f1e3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.life-asset-app .la-last-refresh {
  padding: 4px 14px;
  color: #cfe3cb;
  font-size: 11px;
  white-space: nowrap;
}

/* Shell and navigation */
.life-asset-app .la-shell {
  display: flex;
  align-items: flex-start;
  min-height: calc(100vh - 88px);
}

.life-asset-app .la-sidebar {
  position: sticky;
  top: 88px;
  z-index: 45;
  flex: 0 0 auto;
  width: 224px;
  height: calc(100vh - 88px);
  background: #fff;
  border-right: 3px solid var(--la-gold-light);
  transition: width 0.25s ease;
}

.life-asset-app .la-sidebar.is-collapsed {
  width: 58px;
}

.life-asset-app .la-sidebar-inner {
  height: 100%;
  padding: 8px 0 24px;
  overflow-x: hidden;
  overflow-y: auto;
}

.life-asset-app .la-sidebar-toggle {
  position: absolute;
  top: 60px;
  right: -13px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 26px;
  height: 52px;
  color: var(--la-gold);
  background: linear-gradient(90deg, var(--la-gold-soft), #fff);
  border: 1.5px solid var(--la-gold);
  border-left: 0;
  border-radius: 0 13px 13px 0;
  box-shadow: 2px 1px 5px rgba(184, 134, 11, 0.18);
  transition: transform 0.25s ease, background 0.15s ease;
}

.life-asset-app .la-sidebar.is-collapsed .la-sidebar-toggle {
  transform: rotate(180deg);
}

.life-asset-app .la-sidebar-toggle:hover {
  color: #2a1f00;
  background: var(--la-gold);
}

.life-asset-app .la-nav-heading {
  padding: 11px 14px 5px;
  color: var(--la-faint);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  white-space: nowrap;
}

.life-asset-app .la-nav-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: calc(100% - 14px);
  margin: 1px 7px;
  padding: 8px 10px;
  color: var(--la-ink-2);
  background: transparent;
  border: 0;
  border-left: 3px solid transparent;
  border-radius: 8px;
  text-align: left;
}

.life-asset-app .la-nav-item:hover {
  background: var(--la-leaf-soft);
}

.life-asset-app .la-nav-item.is-active {
  color: var(--la-forest-dark);
  background: var(--la-leaf-soft);
  border-left-color: var(--la-forest);
  font-weight: 600;
}

.life-asset-app .la-nav-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 27px;
  height: 27px;
  background: var(--la-grey-bg);
  border-radius: 7px;
  font-size: 14px;
}

.life-asset-app .la-nav-text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.life-asset-app .la-nav-count {
  flex: 0 0 auto;
  min-width: 22px;
  padding: 1px 6px;
  color: var(--la-muted);
  background: var(--la-grey-bg);
  border-radius: 12px;
  font-size: 10.5px;
  text-align: center;
}

.life-asset-app .la-sidebar.is-collapsed .la-nav-heading,
.life-asset-app .la-sidebar.is-collapsed .la-nav-text,
.life-asset-app .la-sidebar.is-collapsed .la-nav-count {
  display: none;
}

.life-asset-app .la-sidebar.is-collapsed .la-nav-item {
  justify-content: center;
  padding: 8px 4px;
}

.life-asset-app .la-main {
  flex: 1;
  min-width: 0;
  padding: 16px 18px 60px;
}

/* Filters */
.life-asset-app .la-filter-card {
  margin-bottom: 14px;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--la-line);
  border-radius: var(--la-radius);
  box-shadow: var(--la-shadow);
}

.life-asset-app .la-filter-head {
  display: flex;
  align-items: center;
  gap: 12px;
  justify-content: space-between;
  padding: 8px 13px;
  background: linear-gradient(90deg, var(--la-leaf-soft), #fff);
  border-bottom: 1px solid var(--la-line-2);
}

.life-asset-app .la-filter-title {
  color: var(--la-forest-dark);
  font-family: Georgia, serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.life-asset-app .la-filter-note {
  max-width: 920px;
  margin-top: 2px;
  color: var(--la-muted);
  font-size: 11.5px;
}

.life-asset-app .la-filter-head-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 7px;
}

.life-asset-app .la-filter-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(130px, 1fr));
  gap: 10px;
  padding: 12px 13px 10px;
}

.life-asset-app .la-field {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.life-asset-app .la-field > span {
  color: var(--la-muted);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.55px;
  text-transform: uppercase;
}

.life-asset-app .la-field input,
.life-asset-app .la-field select {
  width: 100%;
  min-height: 34px;
  padding: 6px 8px;
  background: #fff;
  border: 1px solid var(--la-line);
  border-radius: 7px;
  font-size: 12.5px;
}

.life-asset-app .la-field input:focus,
.life-asset-app .la-field select:focus {
  outline: 2px solid var(--la-leaf);
  outline-offset: 0;
  border-color: var(--la-leaf);
}

.life-asset-app .la-field-wide {
  grid-column: span 2;
}

.life-asset-app .la-field-search,
.life-asset-app .la-field-department {
  grid-column: span 2;
}

.life-asset-app .la-active-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 3px;
  padding: 0 13px 11px;
}

.life-asset-app .la-filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  color: var(--la-forest-dark);
  background: var(--la-leaf-soft);
  border: 1px solid var(--la-leaf-mid);
  border-radius: 18px;
  font-size: 11px;
}

/* Page and reusable cards */
.life-asset-app .la-page {
  display: none;
  animation: la-fade 0.2s ease;
}

.life-asset-app .la-page.is-active {
  display: block;
}

@keyframes la-fade {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: none; }
}

.life-asset-app .la-page-title {
  margin: 2px 0 14px;
}

.life-asset-app .la-title-rule {
  width: 52px;
  height: 3px;
  margin-bottom: 8px;
  background: var(--la-gold);
  border-radius: 2px;
}

.life-asset-app .la-page-title h1 {
  margin: 0;
  color: var(--la-forest-dark);
  font-size: 25px;
}

.life-asset-app .la-page-title p {
  max-width: 1000px;
  margin: 4px 0 0;
  color: var(--la-muted);
  font-size: 12.5px;
}

.life-asset-app .la-grid {
  display: grid;
  gap: 11px;
}

.life-asset-app .la-grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.life-asset-app .la-grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.life-asset-app .la-grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.life-asset-app .la-grid-5 { grid-template-columns: repeat(5, minmax(0, 1fr)); }
.life-asset-app .la-grid-6 { grid-template-columns: repeat(6, minmax(0, 1fr)); }

.life-asset-app .la-card {
  margin-bottom: 13px;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--la-line);
  border-radius: var(--la-radius);
  box-shadow: var(--la-shadow);
}

.life-asset-app .la-card-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 43px;
  padding: 9px 13px;
  background: linear-gradient(90deg, #fafcf8, #fff);
  border-bottom: 1px solid var(--la-line-2);
}

.life-asset-app .la-card-head h3 {
  flex: 0 0 auto;
  margin: 0;
  color: var(--la-forest-dark);
  font-size: 15px;
}

.life-asset-app .la-card-head-note {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  color: var(--la-faint);
  font-size: 11.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.life-asset-app .la-card-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 7px;
}

.life-asset-app .la-card-body {
  padding: 12px 13px;
}

.life-asset-app .la-card-body.is-flush {
  padding: 0;
}

.life-asset-app .la-kpi {
  position: relative;
  min-height: 106px;
  padding: 11px 13px;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--la-line);
  border-left: 4px solid var(--la-forest);
  border-radius: var(--la-radius);
  box-shadow: var(--la-shadow);
  transition: transform 0.15s ease;
}

.life-asset-app button.la-kpi {
  width: 100%;
  text-align: left;
}

.life-asset-app .la-kpi:hover {
  transform: translateY(-2px);
}

.life-asset-app .la-kpi-label {
  color: var(--la-muted);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.75px;
  text-transform: uppercase;
}

.life-asset-app .la-kpi-value {
  margin-top: 3px;
  color: var(--la-forest-dark);
  font-family: Georgia, serif;
  font-size: 27px;
  line-height: 1.2;
}

.life-asset-app .la-kpi-subtitle {
  margin-top: 2px;
  color: var(--la-faint);
  font-size: 11.5px;
}

.life-asset-app .la-kpi-icon {
  position: absolute;
  right: 10px;
  bottom: 4px;
  color: rgba(30, 86, 49, 0.09);
  font-family: Georgia, serif;
  font-size: 48px;
  line-height: 1;
}

.life-asset-app .la-kpi.is-ok { border-left-color: var(--la-ok); }
.life-asset-app .la-kpi.is-warn { border-left-color: var(--la-warn); }
.life-asset-app .la-kpi.is-bad { border-left-color: var(--la-bad); }
.life-asset-app .la-kpi.is-gold { border-left-color: var(--la-gold); }
.life-asset-app .la-kpi.is-info { border-left-color: var(--la-info); }
.life-asset-app .la-kpi.is-purple { border-left-color: var(--la-purple); }

.life-asset-app .la-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 34px;
  padding: 7px 12px;
  color: var(--la-ink-2);
  background: #fff;
  border: 1px solid var(--la-line);
  border-radius: 7px;
  font-size: 12.5px;
  text-decoration: none;
}

.life-asset-app .la-button:hover {
  background: var(--la-leaf-soft);
  border-color: var(--la-leaf-mid);
}

.life-asset-app .la-button-primary {
  color: #fff;
  background: var(--la-forest);
  border-color: var(--la-forest);
  font-weight: 600;
}

.life-asset-app .la-button-primary:hover {
  background: var(--la-forest-dark);
}

.life-asset-app .la-button-gold {
  color: #2a1f00;
  background: var(--la-gold);
  border-color: var(--la-gold);
  font-weight: 600;
}

.life-asset-app .la-button-danger {
  color: var(--la-bad);
  border-color: #efcbc7;
}

.life-asset-app .la-button-light {
  background: #fff;
}

.life-asset-app .la-button-small {
  min-height: 29px;
  padding: 4px 9px;
  font-size: 11.5px;
}

.life-asset-app .la-action-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 13px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid var(--la-line);
  border-left: 4px solid var(--la-gold);
  border-radius: var(--la-radius);
  box-shadow: var(--la-shadow);
}

.life-asset-app .la-action-bar-spacer {
  flex: 1;
}

.life-asset-app .la-record-note {
  color: var(--la-muted);
  font-size: 12px;
}

/* Tables */
.life-asset-app .la-table-shell {
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--la-line);
  border-radius: var(--la-radius);
  box-shadow: var(--la-shadow);
}

.life-asset-app .la-table-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: space-between;
  min-height: 42px;
  padding: 7px 11px;
  background: #fafcf8;
  border-bottom: 1px solid var(--la-line-2);
}

.life-asset-app .la-table-title {
  color: var(--la-forest-dark);
  font-family: Georgia, serif;
  font-size: 14px;
  font-weight: 600;
}

.life-asset-app .la-table-count {
  margin-left: 6px;
  color: var(--la-faint);
  font-family: "Segoe UI", sans-serif;
  font-size: 11.5px;
  font-weight: 400;
}

.life-asset-app .la-table-wrap {
  width: 100%;
  overflow: auto;
}

.life-asset-app table.la-table {
  width: 100%;
  min-width: 880px;
  border-collapse: collapse;
  font-size: 12.5px;
}

.life-asset-app table.la-table th {
  position: sticky;
  top: 0;
  z-index: 2;
  padding: 8px 9px;
  color: #fff;
  background: var(--la-forest);
  border-right: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.45px;
  line-height: 1.3;
  text-align: left;
  text-transform: uppercase;
  white-space: normal;
}

.life-asset-app table.la-table th[data-sort-key] {
  cursor: pointer;
}

.life-asset-app table.la-table th[data-sort-key]:hover {
  background: var(--la-forest-dark);
}

.life-asset-app .la-sort-indicator {
  margin-left: 3px;
  opacity: 0.65;
  font-size: 9px;
}

.life-asset-app table.la-table td {
  max-width: 280px;
  padding: 8px 9px;
  vertical-align: middle;
  border-bottom: 1px solid var(--la-line-2);
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.life-asset-app table.la-table tbody tr:nth-child(even) {
  background: #fafcf8;
}

.life-asset-app table.la-table tbody tr:hover {
  background: var(--la-leaf-soft);
}

.life-asset-app table.la-table th.is-number,
.life-asset-app table.la-table td.is-number {
  text-align: right;
  white-space: nowrap;
}

.life-asset-app table.la-table th.is-center,
.life-asset-app table.la-table td.is-center {
  text-align: center;
  white-space: nowrap;
}

/* Complaints register: one complaint occupies one clean horizontal row. */
.life-asset-app table.la-complaint-table {
  width: 2110px;
  min-width: 2110px;
  table-layout: fixed;
}

.life-asset-app table.la-complaint-table th,
.life-asset-app table.la-complaint-table td,
.life-asset-app table.la-complaint-table td * {
  white-space: nowrap !important;
  word-break: normal !important;
  overflow-wrap: normal !important;
  hyphens: none !important;
}

.life-asset-app table.la-complaint-table th,
.life-asset-app table.la-complaint-table td {
  overflow: hidden;
}

.life-asset-app table.la-complaint-table .la-cell-clamp {
  display: inline-block;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: middle;
}

.life-asset-app table.la-complaint-table th:first-child,
.life-asset-app table.la-complaint-table td:first-child {
  width: 150px;
}

.life-asset-app table.la-complaint-table th:nth-child(2),
.life-asset-app table.la-complaint-table td:nth-child(2) {
  width: 360px;
}

.life-asset-app table.la-complaint-table th:nth-child(3),
.life-asset-app table.la-complaint-table td:nth-child(3) { width: 120px; }

.life-asset-app table.la-complaint-table th:nth-child(4),
.life-asset-app table.la-complaint-table td:nth-child(4) { width: 300px; }

.life-asset-app table.la-complaint-table th:nth-child(5),
.life-asset-app table.la-complaint-table td:nth-child(5) { width: 150px; }

.life-asset-app table.la-complaint-table th:nth-child(6),
.life-asset-app table.la-complaint-table td:nth-child(6) { width: 230px; }

.life-asset-app table.la-complaint-table th:nth-child(7),
.life-asset-app table.la-complaint-table td:nth-child(7) { width: 150px; }

.life-asset-app table.la-complaint-table th:nth-child(8),
.life-asset-app table.la-complaint-table td:nth-child(8) { width: 100px; }

.life-asset-app table.la-complaint-table th:nth-child(9),
.life-asset-app table.la-complaint-table td:nth-child(9) { width: 100px; }

.life-asset-app table.la-complaint-table th:nth-child(10),
.life-asset-app table.la-complaint-table td:nth-child(10) {
  width: 360px;
}

.life-asset-app table.la-complaint-table th:nth-child(11),
.life-asset-app table.la-complaint-table td:nth-child(11) { width: 90px; }

.life-asset-app .la-cell-main {
  display: block;
  color: var(--la-ink);
  font-weight: 600;
}

/* Keep branch/location names on one proper line in Asset tables. */
.life-asset-app table.la-table th.la-location-column,
.life-asset-app table.la-table td.la-location-column {
  width: 150px;
  min-width: 150px;
  max-width: none;
  white-space: nowrap !important;
  word-break: keep-all !important;
  overflow-wrap: normal !important;
  hyphens: none !important;
}

.life-asset-app .la-location-one-line {
  display: block;
  width: max-content;
  min-width: max-content;
  white-space: nowrap !important;
  word-break: keep-all !important;
  overflow-wrap: normal !important;
  hyphens: none !important;
}

.life-asset-app td.la-location-column .la-cell-sub {
  white-space: nowrap;
  word-break: keep-all;
  overflow-wrap: normal;
}

.life-asset-app .la-cell-sub {
  display: block;
  margin-top: 1px;
  color: var(--la-faint);
  font-size: 10.8px;
}

.life-asset-app .la-cell-clamp {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.life-asset-app .la-pagination {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  padding: 8px 10px;
  background: #fafcf8;
  border-top: 1px solid var(--la-line-2);
}

.life-asset-app .la-pagination-note {
  margin-right: auto;
  color: var(--la-faint);
  font-size: 11.5px;
}

.life-asset-app .la-page-button {
  min-width: 30px;
  min-height: 29px;
  padding: 4px 8px;
  color: var(--la-ink-2);
  background: #fff;
  border: 1px solid var(--la-line);
  border-radius: 6px;
  font-size: 11.5px;
}

.life-asset-app .la-page-button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

/* Badges and status */
.life-asset-app .la-badge {
  display: inline-block;
  max-width: 100%;
  padding: 2px 8px;
  overflow: hidden;
  border-radius: 20px;
  font-size: 10.8px;
  font-weight: 600;
  line-height: 1.55;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.life-asset-app .la-badge-ok { color: var(--la-ok); background: var(--la-ok-bg); }
.life-asset-app .la-badge-warn { color: var(--la-warn); background: var(--la-warn-bg); }
.life-asset-app .la-badge-bad { color: var(--la-bad); background: var(--la-bad-bg); }
.life-asset-app .la-badge-info { color: var(--la-info); background: var(--la-info-bg); }
.life-asset-app .la-badge-grey { color: var(--la-grey); background: var(--la-grey-bg); }
.life-asset-app .la-badge-gold { color: #8a6508; background: var(--la-gold-soft); }
.life-asset-app .la-badge-purple { color: var(--la-purple); background: var(--la-purple-bg); }

.life-asset-app .la-empty-state {
  display: grid;
  place-items: center;
  min-height: 180px;
  padding: 24px;
  color: var(--la-muted);
  text-align: center;
}

.life-asset-app .la-empty-icon {
  margin-bottom: 7px;
  color: var(--la-line);
  font-family: Georgia, serif;
  font-size: 48px;
  line-height: 1;
}

.life-asset-app .la-empty-title {
  color: var(--la-ink-2);
  font-family: Georgia, serif;
  font-size: 15px;
  font-weight: 600;
}

.life-asset-app .la-empty-note {
  max-width: 620px;
  margin-top: 4px;
  font-size: 12px;
}

/* Charts */
.life-asset-app .la-chart-grid {
  display: grid;
  grid-template-columns: minmax(260px, 0.9fr) minmax(360px, 1.5fr);
  gap: 12px;
}

.life-asset-app .la-donut-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-height: 230px;
}

.life-asset-app .la-donut {
  position: relative;
  flex: 0 0 auto;
  width: 164px;
  height: 164px;
  border-radius: 50%;
  background: conic-gradient(
    var(--la-ok) 0 var(--la-p1, 0%),
    var(--la-warn) var(--la-p1, 0%) var(--la-p2, 0%),
    var(--la-bad) var(--la-p2, 0%) var(--la-p3, 0%),
    var(--la-grey) var(--la-p3, 0%) 100%
  );
}

.life-asset-app .la-donut::after {
  content: "";
  position: absolute;
  inset: 28px;
  background: #fff;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--la-line-2);
}

.life-asset-app .la-donut-centre {
  position: absolute;
  inset: 0;
  z-index: 1;
  display: grid;
  place-content: center;
  text-align: center;
}

.life-asset-app .la-donut-number {
  color: var(--la-forest-dark);
  font-family: Georgia, serif;
  font-size: 27px;
  line-height: 1;
}

.life-asset-app .la-donut-label {
  margin-top: 4px;
  color: var(--la-faint);
  font-size: 10px;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.life-asset-app .la-legend {
  display: grid;
  gap: 8px;
}

.life-asset-app .la-legend-row {
  display: grid;
  grid-template-columns: 10px minmax(90px, 1fr) auto;
  align-items: center;
  gap: 7px;
  font-size: 12px;
}

.life-asset-app .la-legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.life-asset-app .la-bar-list {
  display: grid;
  gap: 9px;
}

.life-asset-app .la-bar-row {
  display: grid;
  grid-template-columns: minmax(110px, 0.9fr) minmax(150px, 2fr) auto;
  align-items: center;
  gap: 9px;
}

.life-asset-app .la-bar-label {
  min-width: 0;
  overflow: hidden;
  color: var(--la-ink-2);
  font-size: 11.8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.life-asset-app .la-bar-track {
  height: 9px;
  overflow: hidden;
  background: var(--la-line-2);
  border-radius: 6px;
}

.life-asset-app .la-bar-fill {
  display: block;
  min-width: 2px;
  height: 100%;
  background: linear-gradient(90deg, var(--la-forest), var(--la-leaf));
  border-radius: 6px;
}

.life-asset-app .la-bar-value {
  min-width: 38px;
  color: var(--la-muted);
  font-size: 11.5px;
  text-align: right;
}

/* Detail views */
.life-asset-app .la-detail-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 9px;
}

.life-asset-app .la-detail-item {
  min-height: 64px;
  padding: 9px 10px;
  background: #fafcf8;
  border: 1px solid var(--la-line-2);
  border-radius: 8px;
}

.life-asset-app .la-detail-label {
  color: var(--la-faint);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.55px;
  text-transform: uppercase;
}

.life-asset-app .la-detail-value {
  margin-top: 3px;
  color: var(--la-ink-2);
  font-size: 12.5px;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.life-asset-app .la-search-hero {
  margin-bottom: 13px;
  padding: 20px;
  color: #fff;
  background: linear-gradient(120deg, var(--la-forest-dark), var(--la-forest) 60%, var(--la-forest-light));
  border-bottom: 3px solid var(--la-gold);
  border-radius: 14px;
  box-shadow: var(--la-shadow);
}

.life-asset-app .la-search-hero h2 {
  margin: 0 0 4px;
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  font-size: 21px;
}

.life-asset-app .la-search-hero p {
  margin: 0 0 13px;
  color: #cfe3cb;
  font-size: 12px;
}

.life-asset-app .la-search-row {
  display: flex;
  gap: 8px;
}

.life-asset-app .la-search-row input,
.life-asset-app .la-search-row select {
  flex: 1;
  min-width: 0;
  min-height: 42px;
  padding: 9px 12px;
  background: #fff;
  border: 0;
  border-radius: 8px;
}

/* Machine 360 native Asset selector: the search hero uses white text, so the
   select and its browser-rendered options need an explicit dark text colour. */
.life-asset-app .la-search-row select,
.life-asset-app select[data-asset360-select] {
  color: var(--la-ink) !important;
  -webkit-text-fill-color: var(--la-ink) !important;
  background-color: #ffffff !important;
}

.life-asset-app .la-search-row select option,
.life-asset-app select[data-asset360-select] option {
  color: #1b2a22 !important;
  -webkit-text-fill-color: #1b2a22 !important;
  background: #ffffff !important;
}

.life-asset-app .la-timeline {
  position: relative;
  margin: 0;
  padding: 0 0 0 24px;
}

.life-asset-app .la-timeline::before {
  content: "";
  position: absolute;
  top: 7px;
  bottom: 7px;
  left: 7px;
  width: 2px;
  background: var(--la-line);
}

.life-asset-app .la-timeline-item {
  position: relative;
  list-style: none;
  padding: 0 0 14px;
}

.life-asset-app .la-timeline-item::before {
  content: "";
  position: absolute;
  top: 5px;
  left: -22px;
  width: 12px;
  height: 12px;
  background: #fff;
  border: 2.5px solid var(--la-leaf);
  border-radius: 50%;
}

.life-asset-app .la-timeline-item.is-bad::before { border-color: var(--la-bad); }
.life-asset-app .la-timeline-item.is-warn::before { border-color: var(--la-warn); }
.life-asset-app .la-timeline-item.is-info::before { border-color: var(--la-info); }
.life-asset-app .la-timeline-item.is-gold::before { border-color: var(--la-gold); }

.life-asset-app .la-timeline-title {
  color: var(--la-ink);
  font-size: 12.8px;
  font-weight: 600;
}

.life-asset-app .la-timeline-meta {
  color: var(--la-faint);
  font-size: 10.8px;
}

.life-asset-app .la-timeline-body {
  margin-top: 2px;
  color: var(--la-ink-2);
  font-size: 12px;
}

.life-asset-app .la-report-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 12px;
}

.life-asset-app .la-report-tab {
  padding: 7px 11px;
  color: var(--la-muted);
  background: #fff;
  border: 1px solid var(--la-line);
  border-radius: 7px;
  font-size: 11.8px;
}

.life-asset-app .la-report-tab.is-active {
  color: #fff;
  background: var(--la-forest);
  border-color: var(--la-forest);
  font-weight: 600;
}

.life-asset-app .la-notice {
  margin-bottom: 12px;
  padding: 10px 12px;
  color: var(--la-ink-2);
  background: var(--la-info-bg);
  border: 1px solid #c5ddeb;
  border-left: 4px solid var(--la-info);
  border-radius: 8px;
  font-size: 12px;
}

.life-asset-app .la-notice.is-warn {
  background: var(--la-warn-bg);
  border-color: #efd7a6;
  border-left-color: var(--la-warn);
}

.life-asset-app .la-notice.is-bad {
  background: var(--la-bad-bg);
  border-color: #efcbc7;
  border-left-color: var(--la-bad);
}

.life-asset-app .la-source-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.life-asset-app .la-source-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  background: #fafcf8;
  border: 1px solid var(--la-line-2);
  border-radius: 8px;
}

.life-asset-app .la-source-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 700;
}

.life-asset-app .la-source-icon.is-ok { color: var(--la-ok); background: var(--la-ok-bg); }
.life-asset-app .la-source-icon.is-bad { color: var(--la-bad); background: var(--la-bad-bg); }

.life-asset-app .la-source-name {
  color: var(--la-ink-2);
  font-size: 11.8px;
  font-weight: 600;
}

.life-asset-app .la-source-status {
  color: var(--la-faint);
  font-size: 10.5px;
}

/* Loading, modal, toast */
.life-asset-app .la-loading {
  position: fixed;
  inset: 0;
  z-index: 400;
  display: none;
  place-content: center;
  color: var(--la-forest-dark);
  background: rgba(245, 248, 243, 0.93);
  text-align: center;
}

.life-asset-app .la-loading.is-visible {
  display: grid;
}

.life-asset-app .la-loader {
  width: 44px;
  height: 44px;
  margin: 0 auto 12px;
  border: 4px solid var(--la-line);
  border-top-color: var(--la-forest);
  border-radius: 50%;
  animation: la-spin 0.75s linear infinite;
}

@keyframes la-spin {
  to { transform: rotate(360deg); }
}

.life-asset-app .la-loading-title {
  font-family: Georgia, serif;
  font-size: 18px;
  font-weight: 600;
}

.life-asset-app .la-loading-note {
  margin-top: 4px;
  color: var(--la-muted);
  font-size: 12px;
}

.life-asset-app .la-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 350;
  display: none;
  align-items: flex-start;
  justify-content: center;
  padding: 34px 14px;
  overflow: auto;
  background: rgba(15, 35, 22, 0.55);
}

.life-asset-app .la-modal-overlay.is-visible {
  display: flex;
}

.life-asset-app .la-modal {
  width: 100%;
  max-width: 980px;
  overflow: hidden;
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.32);
  animation: la-pop 0.2s ease;
}

@keyframes la-pop {
  from { opacity: 0; transform: scale(0.97) translateY(9px); }
  to { opacity: 1; transform: none; }
}

.life-asset-app .la-modal-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  color: #fff;
  background: linear-gradient(100deg, var(--la-forest-dark), var(--la-forest));
  border-bottom: 3px solid var(--la-gold);
}

.life-asset-app .la-modal-head h3 {
  flex: 1;
  margin: 0;
  font-size: 17px;
}

.life-asset-app .la-modal-head button {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  color: #fff;
  background: rgba(255, 255, 255, 0.15);
  border: 0;
  border-radius: 7px;
}

.life-asset-app .la-modal-body {
  max-height: 74vh;
  padding: 14px 16px;
  overflow: auto;
}

.life-asset-app .la-modal-foot {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  min-height: 50px;
  padding: 9px 16px;
  background: #fafcf8;
  border-top: 1px solid var(--la-line);
}

.life-asset-app .la-toast {
  position: fixed;
  right: 20px;
  bottom: 22px;
  z-index: 500;
  max-width: 360px;
  padding: 10px 14px;
  color: #fff;
  background: var(--la-forest-dark);
  border-left: 4px solid var(--la-gold);
  border-radius: 8px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.22);
  opacity: 0;
  pointer-events: none;
  transform: translateY(12px);
  transition: opacity 0.18s ease, transform 0.18s ease;
}

.life-asset-app .la-toast.is-visible {
  opacity: 1;
  transform: none;
}

.life-asset-app .la-toast.is-error {
  background: #7d1f18;
  border-left-color: #f2b4ae;
}

@media (max-width: 1320px) {
  .life-asset-app .la-filter-grid { grid-template-columns: repeat(4, minmax(130px, 1fr)); }
  .life-asset-app .la-grid-6 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .life-asset-app .la-grid-5 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .life-asset-app .la-detail-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (max-width: 1080px) {
  .life-asset-app .la-user-chip { display: none; }
  .life-asset-app .la-grid-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .life-asset-app .la-source-list { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .life-asset-app .la-chart-grid { grid-template-columns: 1fr; }
}

@media (max-width: 820px) {
  .life-asset-app .la-topbar { position: relative; }
  .life-asset-app .la-topbar-main { flex-wrap: wrap; }
  .life-asset-app .la-brand { width: 100%; }
  .life-asset-app .la-topbar-spacer { display: none; }
  .life-asset-app .la-brand-subtitle { max-width: calc(100vw - 90px); }
  .life-asset-app .la-sidebar {
    position: fixed;
    top: 0;
    left: 0;
    z-index: 250;
    width: 228px;
    height: 100vh;
    transform: translateX(-100%);
    transition: transform 0.25s ease;
  }
  .life-asset-app .la-sidebar.is-mobile-open { transform: translateX(0); }
  .life-asset-app .la-sidebar.is-collapsed { width: 228px; }
  .life-asset-app .la-sidebar.is-collapsed .la-nav-heading,
  .life-asset-app .la-sidebar.is-collapsed .la-nav-text,
  .life-asset-app .la-sidebar.is-collapsed .la-nav-count { display: block; }
