  function locateRoot() {
    let host = null;

    try {
      if (typeof root_element !== "undefined" && root_element) {
        host = root_element;
      }
    } catch (error) {
      host = null;
    }

    if (host && host.matches && host.matches(APP_SELECTOR)) {
      return host;
    }

    if (host && host.querySelector) {
      const inside = host.querySelector(APP_SELECTOR);
      if (inside) return inside;
    }

    return document.querySelector(APP_SELECTOR);
  }

  function start() {
    const root = locateRoot();
    if (!root) {
      void 0;
      return;
    }

    if (root.dataset.assetDashboardInitialized === "1") return;
    root.dataset.assetDashboardInitialized = "1";

    STATE.root = root;
    STATE.root.classList.add("la-pdf-light-theme");
    ensureDynamicDashboardUi();
    enhanceMasterDateControls();
    bindEvents();
    initAmountToggle();
    setUserIdentity();
    loadMenuPreferences();
    loadFavoritePreferences();
    applyMenuVisibility();
    renderFavoriteMenus();
    syncPeriodInputs(true);

    // Honour approval links from email immediately, before the asynchronous
    // dashboard sources finish loading. The request popup is opened after the
    // data refresh by applyDashboardDeepLink().
    const startupDeepLink = getDashboardDeepLink();
    const startupPage = startupDeepLink.page === "approvals"
      ? "approvals"
      : (isMenuVisible("dashboard") ? "dashboard" : getFirstVisibleMenuPage());
    openPage(
      startupPage
    );
    loadAllData();
  }

  function bindEvents() {
    const root = STATE.root;

    // Sidebar navigation must always win over generated card, table and popup
    // click handlers. Capture the menu click first so Complaints and every
    // other module reliably opens its own dashboard panel.
    root.addEventListener("click", function (event) {
      const menuButton = event.target.closest(
        '.la-nav-item[data-page]'
      );

      if (!menuButton || !root.contains(menuButton)) return;

      // The star is an independent favourite control, not a page link.
      if (event.target.closest('[data-action="toggle-favorite"]')) return;

      event.preventDefault();
      event.stopPropagation();
      openPage(menuButton.dataset.page || "dashboard");
    }, true);

    // Branch links live inside a generated/paginated table. Handle them in
    // capture phase so no table or ERPNext listener can stop the click before
    // the Asset Register action runs.
    root.addEventListener("click", function (event) {
      const branchLink = event.target.closest(
        '[data-action="open-branch-assets"]'
      );

      if (!branchLink || !root.contains(branchLink)) return;

      event.preventDefault();
      event.stopPropagation();

      const branchName =
        branchLink.getAttribute("data-branch-name") ||
        branchLink.textContent ||
        "";

      openBranchAssets(branchName);
    }, true);

    root.addEventListener("keydown", function (event) {
      if (event.key !== "Enter" && event.key !== " ") return;

      const branchRow = event.target.closest(
        '[data-action="open-branch-assets"]'
      );

      if (!branchRow || !root.contains(branchRow)) return;

      event.preventDefault();
      event.stopPropagation();

      openBranchAssets(
        branchRow.getAttribute("data-branch-name") ||
        branchRow.textContent ||
        ""
      );
    }, true);

    root.addEventListener("click", function (event) {
      const card = event.target.closest(
        ".la-kpi,.la-card,.la-command-strip-item,.la-command-category,.la-command-status,.la-department-command-card,.la-master-category-card,.la-check-list,.la-check-work"
      );
      const nestedControl = event.target.closest(
        "a,input,select,textarea,[contenteditable=true],button,[data-action],[data-page],[data-report-type],[data-docname]"
      );
      if (
        card &&
        root.contains(card) &&
        (!nestedControl || nestedControl === card) &&
        !card.closest("[data-modal-overlay]")
      ) {
        event.preventDefault();
        event.stopPropagation();
        openDashboardCardPdf(card);
        return;
      }

      const target = event.target.closest("button, [data-action], [data-page], [data-report-type], [data-docname]");
      if (!target || !root.contains(target)) return;

      const page = target.dataset.page;
      if (page) {
        if (page === "asset360") {
          STATE.asset360Name = "";
          STATE.asset360SearchName = "";
        }
        openPage(page);
        return;
      }

      const action = target.dataset.action;
      if (action) {
        handleAction(action, target, event);
        return;
      }

      const reportType = target.dataset.reportType;
      if (reportType) {
        STATE.reportType = reportType;
        STATE.tablePage.report = 1;
        renderReports();
        return;
      }

      const docname = target.dataset.docname;
      const doctype = target.dataset.doctype;
      if (docname && doctype) {
        openDocument(doctype, docname);
      }
    });

    root.addEventListener("change", function (event) {
      const menuPage = event.target.dataset.menuToggle;

      if (menuPage) {
        updateMenuPreference(
          menuPage,
          Boolean(event.target.checked),
          event.target
        );
        return;
      }

      const filterName = event.target.dataset.filter;
      if (filterName) {
        STATE.filters[filterName] = event.target.value || "";

        if (filterName === "from" || filterName === "to") {
          updateMasterDateDisplay(event.target);
        }

        if (["location", "category", "machinery_category"].indexOf(filterName) !== -1) {
          refreshAssetSearchOptionsForFilters();
        }

        // A manual Branch / Location selection replaces any temporary
        // Command Centre branch-row drill-down.
        if (filterName === "location") {
          STATE.branchDrilldownActive = false;
        }

        if (filterName === "period") {
          syncPeriodInputs(false);
        }

        if (filterName === "from" || filterName === "to") {
          STATE.filters.period = "custom";
          setFilterControl("period", "custom");
        }

        scheduleFilterApply(20);
        return;
      }

      if (event.target.matches("[data-asset360-select]")) {
        STATE.asset360SearchName = event.target.value || "";
        renderAsset360();
      }
    });

    root.addEventListener("input", function (event) {
      const filterName = event.target.dataset.filter;
      if (filterName === "search") {
        STATE.filters.search = event.target.value || "";
        scheduleFilterApply(220);
      }
    });

    root.addEventListener("keydown", function (event) {
      const favoriteStar = event.target.closest('[data-action="toggle-favorite"]');
      if (favoriteStar && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        event.stopPropagation();
        toggleFavorite(favoriteStar.dataset.favoritePage || "");
        return;
      }

      const reportHead = event.target.closest(".la-report-catalog-head");
      if (reportHead && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        if (reportHead.dataset.action === "close-report") {
          STATE.reportType = "";
        } else if (reportHead.dataset.reportType) {
          STATE.reportType = reportHead.dataset.reportType;
        }
        STATE.tablePage.report = 1;
        renderReports();
        return;
      }

      if (event.key === "Escape") closeModal();
    });

    const overlay = root.querySelector("[data-modal-overlay]");
    if (overlay) {
      overlay.addEventListener("click", function (event) {
        if (event.target === overlay) closeModal();
      });
    }
  }

  function openDashboardCardPdf(card) {
    if (!card) return;
    const titleNode = card.querySelector(
      ".la-kpi-label,.la-card-head h3,.la-command-category-top b,.la-command-strip-item>span,.la-command-status>span,.la-department-command-card>div b,.la-master-category-top h3,.la-check-head h3,h2,h3"
    );
    const title = String(titleNode ? titleNode.textContent : "Dashboard Card").trim() || "Dashboard Card";

    // Operational Command Centre cards open their matching live register.
    // Remaining management cards continue to use the generic drill-down.
    if (STATE.currentPage === "dashboard") {
      const commandCardTitle = normalize(title);

      if (commandCardTitle.indexOf("open complaints") !== -1) {
        openPage("repairs");
        return;
      }

      if (commandCardTitle.indexOf("transfers in cycle") !== -1) {
        openPage("movements");
        return;
      }
    }

    const report = getDashboardCardRelatedData(STATE.currentPage, title);
    const page = MENU_DEFINITIONS.find(function (item) { return item.page === STATE.currentPage; });
    const section = page ? page.label : "Asset Dashboard";
    const html = [
      '<div data-related-card-report style="background:#fffdf7;border:1px solid #c9b77f;border-radius:6px;padding:16px;box-shadow:inset 0 0 0 4px #f3ecd8">',
