  function getDashboardCardRelatedData(page, title) {
    const key = normalize(title);
    let kind = "assets";
    let rows = (STATE.filtered.assets || []).slice();

    if (page === "checks") {
      kind = "checks";
      rows = (STATE.filtered.checks || []).slice();
    } else if (page === "repairs") {
      kind = "issues";
      rows = (STATE.filtered.issues || []).slice();
    } else if (page === "maintenance") {
      kind = "visits";
      rows = (STATE.filtered.maintenance || []).slice();
    } else if (page === "movements") {
      kind = "transfers";
      rows = sourceAvailable("machineryTransfers")
        ? (STATE.filtered.machineryTransfers || []).slice()
        : (STATE.filtered.movements || []).slice();
    } else if (page === "approvals") {
      kind = "approvals";
      rows = (STATE.filtered.machineryRequests || []).map(function (row) {
        return Object.assign({ dashboard_record_type: "Machinery Request" }, row);
      }).concat((STATE.filtered.machineryTransfers || []).map(function (row) {
        return Object.assign({ dashboard_record_type: "Machinery Transfer" }, row);
      }));
    }

    if (kind === "assets") {
      if (["machinery", "electronics", "vehicles", "furniture"].indexOf(key) !== -1) {
        rows = rows.filter(function (row) { return normalize(assetCommandBucket(row)) === key; });
      } else if (/not working|out of order|machine.*down/.test(key)) {
        rows = rows.filter(function (row) { return row.status === "Out of Order"; });
      } else if (/in maintenance|maintenance now/.test(key)) {
        rows = rows.filter(function (row) { return row.status === "In Maintenance"; });
      } else if (/^working$|working now/.test(key)) {
        rows = rows.filter(isOperationalAsset);
      } else if (/sold|scrapped|retired/.test(key)) {
        rows = rows.filter(isRetiredAsset);
      } else if (/depreciation due/.test(key)) {
        rows = getDepreciationDueAssets();
      } else if (/insurance/.test(key)) {
        rows = getInsuranceAlerts(rows, 60);
      } else if (/past useful life/.test(key)) {
        rows = rows.filter(function (row) { return !isRetiredAsset(row) && (row.status === "Fully Depreciated" || (getAssetCost(row) > 0 && getAssetBookValue(row) <= 0)); });
      }
    } else if (kind === "checks") {
      if (/fail|attention/.test(key)) rows = rows.filter(function (row) { return /fail|attention/i.test(row.overall_result || ""); });
      else if (/pass/.test(key)) rows = rows.filter(function (row) { return row.overall_result === "Pass"; });
      else if (/overdue/.test(key)) rows = rows.filter(function (row) { return row.next_check_date && isDatePast(row.next_check_date); });
    } else if (kind === "issues") {
      if (/open/.test(key)) rows = rows.filter(function (row) { return ["Resolved", "Closed"].indexOf(row.status || "") === -1; });
      else if (/closed|resolved|completed/.test(key)) rows = rows.filter(function (row) { return ["Resolved", "Closed"].indexOf(row.status || "") !== -1; });
      if (/high/.test(key)) rows = rows.filter(function (row) { return normalize(row.priority) === "high"; });
    } else if (kind === "visits") {
      if (/completed/.test(key)) rows = rows.filter(function (row) { return normalize(row.status).indexOf("completed") !== -1; });
      else if (/planned|scheduled|pending/.test(key)) rows = rows.filter(function (row) { return /planned|scheduled|assigned|pending/i.test(row.status || row.maintenance_status || ""); });
      else if (/cancelled/.test(key)) rows = rows.filter(function (row) { return normalize(row.status).indexOf("cancel") !== -1; });
      if (/preventive/.test(key)) rows = rows.filter(function (row) { return normalize(row.visit_type).indexOf("preventive") !== -1; });
      if (/complaint/.test(key)) rows = rows.filter(function (row) { return Boolean(row.linked_complaint) || normalize(row.visit_type).indexOf("complaint") !== -1; });
    } else if (kind === "transfers" || kind === "approvals") {
      if (/pending/.test(key)) rows = rows.filter(function (row) { return /pending|draft|approval/i.test(row.status || ""); });
      else if (/approved|completed/.test(key)) rows = rows.filter(function (row) { return /approved|completed|received/i.test(row.status || ""); });
      else if (/rejected/.test(key)) rows = rows.filter(function (row) { return /rejected/i.test(row.status || ""); });
    }

    const definitions = {
      assets: {
        note: "All Asset records related to this card and the active dashboard filters.",
        columns: [
          ["Asset ID", function (r) { return r.name; }], ["Asset Name", function (r) { return r.asset_name || r.item_name; }],
          ["Category", function (r) { return r.asset_category || assetCommandBucket(r); }], ["Branch / Location", function (r) { return getLifeBranchName(r.location) || r.location; }],
          ["Status", function (r) { return r.status; }], ["Book Value", function (r) { return formatAmount(getAssetBookValue(r)); }]
        ]
      },
      checks: {
        note: "LIFE Asset Check records related to this card and the active period/branch filters.",
        columns: [
          ["Check ID", function (r) { return r.name; }], ["Asset", function (r) { return r.asset_name || r.asset; }],
          ["Location", function (r) { return getLifeBranchName(r.location) || r.location; }], ["Check Date", function (r) { return formatDate(r.check_date); }],
          ["Check Type", function (r) { return r.check_type; }], ["Result", function (r) { return r.overall_result; }]
        ]
      },
      issues: {
        note: "ERPNext Issue records related to this complaint card.",
        columns: [
          ["Complaint", function (r) { return r.name; }], ["Subject", function (r) { return r.subject; }],
          ["Status", function (r) { return r.status; }], ["Priority", function (r) { return r.priority; }],
          ["Raised By", function (r) { return r.raised_by || r.owner; }], ["Created", function (r) { return formatDate(r.creation); }]
        ]
      },
      visits: {
        note: "Technicians And Visits records related to this card.",
        columns: [
          ["Visit", function (r) { return r.name; }], ["Asset", function (r) { return r.asset_name || r.asset; }],
          ["Visit Type", function (r) { return r.visit_type || r.maintenance_type; }], ["Technician", function (r) { return r.technician_name || r.assign_to_name; }],
          ["Scheduled", function (r) { return formatDate(r.scheduled_date || r.due_date); }], ["Status", function (r) { return r.status || r.maintenance_status; }]
        ]
      },
      transfers: {
        note: "Machinery Transfer or Asset Movement records related to this card.",
        columns: [
          ["Document", function (r) { return r.name; }], ["Asset", function (r) { return r.asset_name || r.asset || r.machinery; }],
          ["Source", function (r) { return r.source_branch || r.from_location || r.source_location; }], ["Target", function (r) { return r.target_branch || r.to_location || r.target_location; }],
          ["Required / Date", function (r) { return formatDate(r.required_by || r.transaction_date || r.creation); }], ["Status", function (r) { return r.status || docstatusLabel(r.docstatus); }]
        ]
      },
      approvals: {
        note: "Machinery Request and Machinery Transfer approval records related to this card.",
        columns: [
          ["Type", function (r) { return r.dashboard_record_type; }], ["Document", function (r) { return r.name; }],
          ["Asset / Machinery", function (r) { return r.asset_name || r.asset || r.machinery_name || r.machinery; }], ["Source", function (r) { return r.source_branch || r.allocated_source_branch; }],
          ["Target", function (r) { return r.target_branch || r.requesting_branch; }], ["Status", function (r) { return r.status || docstatusLabel(r.docstatus); }]
        ]
      }
    };
    return { kind: kind, rows: rows, columns: definitions[kind].columns, note: definitions[kind].note };
  }

  function dashboardCardRelatedTable(columns, rows, kind) {
    if (!rows.length) return '<div class="la-check-note">No related records match this card and the current dashboard filters.</div>';
    return '<div class="la-table-wrap" style="max-height:58vh;overflow:auto"><table class="la-table"><thead><tr>' + columns.map(function (column) {
      return '<th>' + escapeHtml(column[0]) + '</th>';
    }).join("") + '<th>Open</th></tr></thead><tbody>' + rows.map(function (row) {
      return '<tr>' + columns.map(function (column) {
        const value = column[1](row);
        return '<td>' + escapeHtml(value == null || value === "" ? "—" : value) + '</td>';
      }).join("") + '<td>' + dashboardCardOpenButton(kind, row) + '</td></tr>';
    }).join("") + '</tbody></table></div>';
  }

  function dashboardCardOpenButton(kind, row) {
    if (!row || !row.name) return "—";
    let doctype = "";
    if (kind === "assets") doctype = "Asset";
    else if (kind === "checks") doctype = "LIFE Asset Check";
    else if (kind === "issues") doctype = "Issue";
    else if (kind === "visits") doctype = "Technicians And Visits";
    else if (kind === "transfers") doctype = sourceAvailable("machineryTransfers") ? "Machinery Transfer" : "Asset Movement";
    else if (kind === "approvals") doctype = row.dashboard_record_type || "Machinery Request";
    if (!doctype) return "—";
    return '<button type="button" class="la-button la-button-small la-button-primary" data-doctype="' + escapeAttribute(doctype) + '" data-docname="' + escapeAttribute(row.name) + '">Open</button>';
  }

