  function openBranchAssets(branchName) {
    const requestedBranch = canonicalBranchDisplayName(branchName);
    const requestedKey = normalizeBranchText(requestedBranch);

    if (isTestingBranchName(requestedBranch)) {
      showToast("Testing Branch is excluded from this dashboard.", true);
      return;
    }

    if (!isBranchAllowedForUser(requestedBranch)) {
      showToast("You can view only your permitted branch data.", true);
      return;
    }

    if (!requestedKey) {
      showToast("Branch name could not be identified.", true);
      return;
    }

    // Resolve the exact display name produced by the current Asset records.
    const matchingAssets = getProductionAssets().filter(function (asset) {
      return normalizeBranchText(getLifeBranchName(asset.location)) ===
        requestedKey;
    });

    const resolvedBranch = matchingAssets.length
      ? getLifeBranchName(matchingAssets[0].location)
      : requestedBranch;

    // Clear every unrelated Asset filter so the selected branch opens with
    // all of its Assets, not only the subset from a previous filter.
    STATE.filters.company = "";
    STATE.filters.location = resolvedBranch;
    STATE.filters.category = "";
    STATE.filters.machinery_category = "";
    STATE.filters.department = "";
    STATE.filters.supplier = "";
    STATE.filters.status = "";
    STATE.filters.search = "";
    STATE.branchDrilldownActive = true;

    setFilterControl("company", "");
    setFilterControl("location", resolvedBranch);
    setFilterControl("category", "");
    setFilterControl("machinery_category", "");
    setFilterControl("department", "");
    setFilterControl("supplier", "");
    setFilterControl("status", "");
    setFilterControl("search", "");

    STATE.tablePage.register = 1;

    // Set the destination before applying filters so the filtered Asset
    // Register is rendered immediately.
    STATE.currentPage = "register";

    STATE.root.querySelectorAll("[data-page-panel]").forEach(function (panel) {
      panel.classList.toggle(
        "is-active",
        panel.dataset.pagePanel === "register"
      );
    });

    STATE.root.querySelectorAll("[data-page]").forEach(function (button) {
      button.classList.toggle(
        "is-active",
        button.dataset.page === "register"
      );
    });

    applyFiltersAndRender();
    renderRegister();

    const registerPanel = STATE.root.querySelector(
      '[data-page-panel="register"]'
    );

    if (registerPanel) {
      const top =
        registerPanel.getBoundingClientRect().top +
        window.scrollY -
        12;

      window.scrollTo({
        top: Math.max(0, top),
        behavior: "smooth"
      });
    }

    showToast(
      resolvedBranch +
        " · " +
        formatNumber(STATE.filtered.assets.length) +
        " Asset record(s) · " +
        formatNumber(sumAssetUnits(STATE.filtered.assets)) +
        " unit(s)",
      false
    );
  }


  function openCategoryAssets(categoryName) {
    const category = String(categoryName || "").trim();
    if (!category) {
      showToast("Asset category could not be identified.", true);
      return;
    }

    STATE.filters.location = lockedBranchValue();
    STATE.filters.category = category;
    STATE.filters.machinery_category = "";
    STATE.filters.department = "";
    STATE.filters.supplier = "";
    STATE.filters.status = "";
    STATE.filters.search = "";

    setFilterControl("location", STATE.filters.location);
    setFilterControl("category", category);
    setFilterControl("machinery_category", "");
    setFilterControl("department", "");
    setFilterControl("supplier", "");
    setFilterControl("status", "");
    setFilterControl("search", "");

    STATE.tablePage.register = 1;
    openPage("register");
    applyFiltersAndRender();
    renderRegister();

    showToast(
      category + " · " +
      formatNumber(STATE.filtered.assets.length) + " Asset record(s) · " +
      formatNumber(sumAssetUnits(STATE.filtered.assets)) + " unit(s)",
      false
    );
  }

