        else sidebarInner.insertBefore(favourites, sidebarInner.firstChild);
      }

      if (!sidebarInner.querySelector('[data-page="checks"]')) {
        const branchHeading = sidebarInner.querySelector('[data-menu-group-heading="branch-operations"]');
        if (branchHeading) {
          const button = document.createElement("button");
          button.type = "button";
          button.className = "la-nav-item";
          button.setAttribute("data-page", "checks");
          button.setAttribute("data-menu-group", "branch-operations");
          button.setAttribute("data-nav-tone", "checks");
          button.innerHTML = '<span class="la-nav-icon">✅</span><span class="la-nav-text">Check Desk</span><span class="la-nav-count" data-count="checks">0</span><span class="la-nav-star">★</span>';
