  function wireFavoriteStars() {
    if (!STATE.root) return;
    STATE.root.querySelectorAll('.la-nav-item[data-page] .la-nav-star').forEach(function (star) {
      const button = star.closest('.la-nav-item[data-page]');
      if (!button) return;
      star.dataset.action = "toggle-favorite";
      star.dataset.favoritePage = button.dataset.page || "";
      star.setAttribute("role", "button");
      star.setAttribute("tabindex", "0");
    });
  }

  function getFavoriteStorageKey() {
    return "life_asset_dashboard_favourites::" + getCurrentUserId();
  }

  function loadFavoritePreferences() {
    let saved = [];
    try {
      const raw = window.localStorage
        ? window.localStorage.getItem(getFavoriteStorageKey())
        : "";
      const parsed = raw ? JSON.parse(raw) : [];
      if (Array.isArray(parsed)) saved = parsed;
    } catch (error) {
      saved = [];
    }

    const allowed = new Set(MENU_DEFINITIONS.map(function (menu) { return menu.page; }));
    STATE.favoritePages = saved.filter(function (page, index) {
      return allowed.has(page) && saved.indexOf(page) === index;
    });
  }

  function saveFavoritePreferences() {
    try {
      if (!window.localStorage) return;
      window.localStorage.setItem(
        getFavoriteStorageKey(),
        JSON.stringify(STATE.favoritePages || [])
      );
    } catch (error) {
      void 0;
    }
  }

  function isFavoritePage(page) {
    return (STATE.favoritePages || []).indexOf(page) !== -1;
  }

  function toggleFavorite(page) {
    const definition = MENU_DEFINITIONS.find(function (menu) { return menu.page === page; });
    if (!definition) return;

    const index = STATE.favoritePages.indexOf(page);
    if (index >= 0) STATE.favoritePages.splice(index, 1);
    else STATE.favoritePages.push(page);

    saveFavoritePreferences();
    renderFavoriteMenus();
    applyMenuVisibility();

    showToast(
