  function loadMenuPreferences() {
    const defaults = getDefaultMenuVisibility();
    let saved = {};

    try {
      const raw = window.localStorage
        ? window.localStorage.getItem(getMenuStorageKey())
        : "";

      saved = raw ? JSON.parse(raw) : {};
    } catch (error) {
      saved = {};
    }

    STATE.menuVisibility = MENU_DEFINITIONS.reduce(function (
      result,
      menu
    ) {
      result[menu.page] =
        typeof saved[menu.page] === "boolean"
          ? saved[menu.page]
          : defaults[menu.page];

      return result;
    }, {});
