      if (!buttons.length) return;

      const visible = isMenuVisible(menu.page);

      buttons.forEach(function (button) {
        button.hidden = !visible;
        button.classList.toggle("is-menu-hidden", !visible);
        button.setAttribute(
          "aria-hidden",
          visible ? "false" : "true"
