    ["overview", "branch-operations", "movement-control", "analyse", "setup"].forEach(function (group) {
      const heading = STATE.root.querySelector(
        '[data-menu-group-heading="' + group + '"]'
      );

      if (!heading) return;

      const hasVisibleItem = MENU_DEFINITIONS.some(function (menu) {
        return menu.group === group && isMenuVisible(menu.page);
      });

      heading.hidden = !hasVisibleItem;
