        return;
      }
    }

    STATE.menuVisibility[page] = visible;
    saveMenuPreferences();
    applyMenuVisibility();
    renderFavoriteMenus();

    const definition = MENU_DEFINITIONS.find(function (menu) {
      return menu.page === page;
    });

    showToast(
      (definition ? definition.label : page) +
