  function frappeCall(method, args) {
    return new Promise(function (resolve, reject) {
      if (!window.frappe || typeof frappe.call !== "function") {
        reject(new Error("Frappe JavaScript API is not available on this page."));
        return;
      }

      frappe.call({
        method: method,
        args: args || {},
        freeze: false,
        silent: true,
        error_handlers: {
          PermissionError: function () {
            // Permission errors are handled inside the dashboard without a popup.
          }
        },
        callback: function (response) {
          if (response && response.exc) {
            reject(new Error(extractFrappeError(response)));
            return;
          }

          if (response && Object.prototype.hasOwnProperty.call(response, "message")) {
            resolve(response.message);
          } else if (response && response.docs) {
            resolve(response.docs);
          } else {
            resolve(response);
          }
        },
        error: function (xhr) {
          reject(new Error(extractXhrError(xhr)));
        }
      });
    });
  }

  function getReadPermissionState(doctype) {
    if (!doctype || !window.frappe) return null;

    const user = frappe.session && frappe.session.user
      ? frappe.session.user
      : "Guest";

    // Website pages can omit System Manager from frappe.user_roles. The
    // dashboard resolves the complete User.roles table before loading sources,
    // so combine both lists when deciding whether a safe-mode request may run.
    const roles = [];
    const addRole = function (role) {
      role = String(role || "").trim();
      if (role && roles.indexOf(role) === -1) roles.push(role);
    };
    if (Array.isArray(frappe.user_roles)) frappe.user_roles.forEach(addRole);
    if (STATE && Array.isArray(STATE.userRoles)) STATE.userRoles.forEach(addRole);

    if (
      user === "Administrator" ||
      roles.indexOf("Administrator") !== -1 ||
      roles.indexOf("System Manager") !== -1
    ) {
      return true;
    }

    // Website routes do not always receive the complete Desk permission boot
    // object. Read only permission metadata that is definitely present.
    const possibleReadLists = [
      frappe.boot &&
        frappe.boot.user &&
        Array.isArray(frappe.boot.user.can_read)
        ? frappe.boot.user.can_read
        : null,

      frappe.boot && Array.isArray(frappe.boot.can_read)
        ? frappe.boot.can_read
        : null
    ].filter(function (value) {
      return Array.isArray(value);
    });

    if (possibleReadLists.length) {
      return possibleReadLists.some(function (list) {
        return list.indexOf(doctype) !== -1;
      });
    }

    // Do not call frappe.perm.has_perm() here. On Website routes its internal
    // boot roles can be undefined and it throws:
    // "Cannot read properties of undefined (reading 'includes')".
    //
    // null means permission metadata is unavailable. Optional sources are
    // then tested through a direct API request that does not invoke Frappe's
    // automatic permission-popup handler.
    return null;
  }

  async function getListWithoutPermissionPopup(definition) {
    const params = new URLSearchParams();

    params.set("doctype", definition.doctype);
    params.set("fields", JSON.stringify(definition.fields || ["name"]));
    params.set("filters", JSON.stringify(definition.filters || []));
    params.set("order_by", definition.orderBy || "modified desc");
    params.set("limit_start", "0");
    params.set("limit_page_length", String(definition.limit || MAX_RECORDS));

    if (definition.parent) {
      params.set("parent", definition.parent);
    }

    const endpoint =
      "/api/method/frappe.client.get_list?" + params.toString();

    const response = await fetch(endpoint, {
      method: "GET",
      credentials: "same-origin",
      headers: {
        Accept: "application/json"
      }
    });

    let payload = null;

    try {
      payload = await response.json();
    } catch (error) {
      payload = null;
    }

    if (!response.ok) {
      const requestError = new Error(
        payload
          ? extractFrappeError(payload)
          : "ERPNext request failed with HTTP " + response.status + "."
      );

      requestError.status = response.status;
      requestError.isPermissionError =
        response.status === 401 ||
        response.status === 403 ||
        Boolean(
          payload &&
          (
            payload.exc_type === "PermissionError" ||
            String(payload.exception || "").indexOf("PermissionError") !== -1 ||
            String(payload.exc || "").indexOf("PermissionError") !== -1
          )
        );

      throw requestError;
    }

    if (payload && Array.isArray(payload.message)) {
      return payload.message;
    }

    return [];
  }

  function isPermissionRequestError(error) {
    if (!error) return false;

    return Boolean(
      error.isPermissionError ||
      error.status === 401 ||
      error.status === 403 ||
      /permission|not permitted|not allowed/i.test(String(error.message || ""))
    );
  }

  function extractFrappeError(response) {
    if (!response) return "Unknown ERPNext error.";
    if (response._server_messages) {
      try {
        const messages = JSON.parse(response._server_messages);
        return messages
          .map(function (message) {
            try {
              const parsed = JSON.parse(message);
              return stripHtml(parsed.message || message);
            } catch (error) {
              return stripHtml(message);
            }
          })
          .join(" | ");
      } catch (error) {
        return stripHtml(response._server_messages);
      }
    }
    return stripHtml(response.exc || response.exception || "ERPNext request failed.");
  }

  function extractXhrError(xhr) {
    if (!xhr) return "ERPNext request failed.";
    if (xhr.responseJSON) return extractFrappeError(xhr.responseJSON);
    if (xhr.responseText) return stripHtml(xhr.responseText).slice(0, 500);
    return xhr.statusText || "ERPNext request failed.";
  }

  function stripHtml(value) {
    const temp = document.createElement("div");
    temp.innerHTML = String(value || "");
    return temp.textContent || temp.innerText || "";
  }

  async function getList(definition) {
    const args = {
      doctype: definition.doctype,
      fields: definition.fields,
      filters: definition.filters || [],
      order_by: definition.orderBy || "modified desc",
      limit_start: 0,
      limit_page_length: definition.limit || MAX_RECORDS
    };

    if (definition.parent) {
      args.parent = definition.parent;
    }

    const message = await frappeCall("frappe.client.get_list", args);
    return Array.isArray(message) ? message : [];
  }

  async function loadSource(key) {
    const definition = SOURCE_DEFINITIONS[key];
    const sourceState = {
      doctype: definition.doctype,
      ok: false,
      count: 0,
      skipped: false,
      error: ""
    };

    /* Never probe a disabled source. This is the important difference from
       the earlier build: no frappe.client.get_list request is sent at all. */
    if (SOURCE_REQUEST_ENABLED[key] !== true) {
      STATE.data[key] = [];
      sourceState.skipped = true;
      sourceState.error = definition.doctype +
        " is disabled in strict safe mode because the current role does not have confirmed Read permission.";
      STATE.sources[key] = sourceState;
      return;
    }

    const permissionState = definition.permissionSource
      ? sourceAvailable(definition.permissionSource)
      : getReadPermissionState(definition.doctype);

    if (
      permissionState === null &&
      SKIP_WHEN_PERMISSION_UNKNOWN[key] === true
    ) {
      STATE.data[key] = [];
      sourceState.skipped = true;
      sourceState.error =
        "Read permission is not confirmed for " +
        definition.doctype +
        ". The dashboard skipped this request to avoid an ERPNext HTTP 403 response.";
      STATE.sources[key] = sourceState;
      return;
    }

    if (permissionState === false && definition.required) {
      STATE.data[key] = [];
      sourceState.skipped = true;
      sourceState.error = definition.permissionSource
        ? "Read permission for " +
          SOURCE_DEFINITIONS[definition.permissionSource].doctype +
          " is required."
        : "Read permission is not assigned for " +
          definition.doctype +
          ".";

      STATE.sources[key] = sourceState;

      throw new Error(sourceState.error);
    }

    try {
      // Asset is required and already known to work, so keep the normal
      // Frappe call. Optional DocTypes with unknown boot metadata use fetch()
      // directly, preventing request.js from showing an automatic 403 dialog.
      let rows;
      if (key === "machineryRequests") {
        try {
          rows = await frappeCall("life_get_machinery_requests", {});
        } catch (apiError) {
          void 0;
          rows = !definition.required
            ? await getListWithoutPermissionPopup(definition)
            : await getList(definition);
        }
      } else if (key === "machineryTransfers") {
        try {
          rows = await frappeCall("life_get_machinery_transfers", {});
        } catch (apiError) {
          void 0;
          rows = !definition.required
            ? await getListWithoutPermissionPopup(definition)
            : await getList(definition);
        }
      } else {
        rows = !definition.required
          ? await getListWithoutPermissionPopup(definition)
          : await getList(definition);
      }

      STATE.data[key] = rows;
      sourceState.ok = true;
      sourceState.count = rows.length;
    } catch (error) {
      STATE.data[key] = [];
      sourceState.error =
        error && error.message
          ? error.message
          : String(error);

      if (isPermissionRequestError(error)) {
        sourceState.skipped = true;
        sourceState.error =
          "Read permission is not assigned for " +
          definition.doctype +
          ".";
      }

      if (definition.required) {
        throw error;
      }
    } finally {
      STATE.sources[key] = sourceState;
    }
  }

  async function loadMachineryRequestEmployeeNames() {
    const employeeIds = Array.from(new Set(
      (STATE.data.machineryRequests || []).concat(STATE.data.machineryTransfers || []).map(function (row) {
        return String(row.requested_by || "").trim();
      }).concat((STATE.data.assets || []).map(function (row) {
        // Asset.custodian is a Link to Employee. Enrich it with employee_name
        // so dashboard popups show the person's name instead of HR-EMP ID.
        return String(row.custodian || "").trim();
      })).filter(Boolean)
    ));
    STATE.machineryRequestEmployeeNames = {};
    if (!employeeIds.length) return;
    try {
      const rows = await frappeCall("frappe.client.get_list", {
        doctype: "Employee",
        fields: ["name", "employee_name"],
        filters: [["name", "in", employeeIds]],
        limit_start: 0,
        limit_page_length: Math.max(employeeIds.length, 20)
      });
      (Array.isArray(rows) ? rows : []).forEach(function (row) {
        if (row && row.name) {
          STATE.machineryRequestEmployeeNames[row.name] = row.employee_name || row.name;
        }
      });
    } catch (error) {
      // Employee-name enrichment is optional. Assets and Machinery Requests
      // must remain visible even when Employee Read permission is unavailable.
      STATE.machineryRequestEmployeeNames = {};
    }
  }

  async function loadLinkedMachineryTransfers() {
    const existingNames = new Set((STATE.data.machineryTransfers || []).map(function (row) { return row.name; }).filter(Boolean));
    const linkedNames = Array.from(new Set((STATE.data.machineryRequests || []).map(function (row) {
      return String(row.machinery_transfer || "").trim();
    }).filter(function (name) { return name && !existingNames.has(name); })));
    if (!linkedNames.length) return;
    const results = await Promise.all(linkedNames.map(async function (name) {
      try {
        return await frappeCall("life_get_machinery_transfers", { transfer_name: name });
      } catch (error) {
        void 0;
        return null;
      }
    }));
    results.filter(Boolean).forEach(function (row) {
      if (row && row.name && !existingNames.has(row.name)) {
        STATE.data.machineryTransfers.push(row);
        existingNames.add(row.name);
      }
    });
    if (STATE.sources.machineryTransfers && results.some(Boolean)) {
      STATE.sources.machineryTransfers.ok = true;
      STATE.sources.machineryTransfers.skipped = false;
      STATE.sources.machineryTransfers.count = STATE.data.machineryTransfers.length;
    }
  }

  function currentDashboardUser() {
    return window.frappe && frappe.session && frappe.session.user
      ? String(frappe.session.user)
      : "Guest";
  }

  function dashboardUserRoles() {
    const roles = [];
    const add = function (role) {
      role = String(role || "").trim();
      if (role && roles.indexOf(role) === -1) roles.push(role);
    };
    if (window.frappe && Array.isArray(frappe.user_roles)) {
      frappe.user_roles.forEach(add);
    }
    if (window.frappe && frappe.boot && frappe.boot.user) {
      const bootRoles = frappe.boot.user.roles;
      if (Array.isArray(bootRoles)) bootRoles.forEach(function (row) { add(row.role || row); });
    }
    (STATE.userRoles || []).forEach(add);
    if (currentDashboardUser() === "Administrator") add("System Manager");
    return roles;
  }

  async function resolveDashboardUserRoles() {
    const user = currentDashboardUser();
    STATE.userRoles = dashboardUserRoles();
    if (!user || user === "Guest" || user === "Administrator") return;
    try {
      const userDoc = await frappeCall("frappe.client.get", { doctype: "User", name: user });
      const roleRows = userDoc && Array.isArray(userDoc.roles) ? userDoc.roles : [];
      roleRows.forEach(function (row) {
        const role = String((row && row.role) || "").trim();
        if (role && STATE.userRoles.indexOf(role) === -1) STATE.userRoles.push(role);
      });
    } catch (error) {
      // Keep Website boot roles when the User document is not readable.
    }
  }

  function isGlobalAssetDashboardUser() {
    const user = currentDashboardUser();
    const roles = dashboardUserRoles();

    return user === "Administrator" ||
      roles.indexOf("Administrator") !== -1 ||
      roles.indexOf("System Manager") !== -1 ||
      roles.indexOf("Sales Manager") !== -1 ||
      roles.indexOf("Stock Manager") !== -1;
  }

  async function safeDirectList(doctype, fields, filters, orderBy, limit) {
    try {
      return await getListWithoutPermissionPopup({
        doctype: doctype,
        fields: fields || ["name"],
        filters: filters || [],
        orderBy: orderBy || "modified desc",
        limit: limit || 100
      });
    } catch (error) {
      return [];
    }
  }

  function addBranchCandidate(target, value, source) {
    const rawBranch = String(value == null ? "" : value).trim();
    const branch = canonicalBranchDisplayName(rawBranch);
    if (!branch || isTestingBranchName(branch)) return;

    const key = normalizeBranchText(branch);
    if (!key) return;

    // Link fields and User Permissions use the exact Branch document ID.
    // Keep the friendly canonical name only for display/comparison. This is
    // important for IDs such as "Chandanagar", whose display label is
    // "Chanda Nagar" but which are not interchangeable in ERPNext links.
    const exactBranch = (LIFE_TRANSFER_BRANCH_IDS || []).find(function (name) {
      return normalizeBranchText(canonicalBranchDisplayName(name)) === key;
    }) || rawBranch || branch;

    if (!target.some(function (row) { return row.key === key; })) {
      target.push({ name: exactBranch, display: branch, key: key, source: source || "" });
    }
  }

  async function resolveLoggedInBranchAccess() {
    const user = currentDashboardUser();

    STATE.access = {
      restricted: false,
      allowedBranches: [],
      activeBranch: "",
      resolvedBy: "",
      user: user
    };

    // Administrator/System Manager keep management-wide access.
    if (!user || user === "Guest" || isGlobalAssetDashboardUser()) return;

    const candidates = [];

    // 1. User Default Branch (fastest and normally available on Website pages).
    try {
      if (
        window.frappe &&
        frappe.defaults &&
        typeof frappe.defaults.get_user_default === "function"
      ) {
        addBranchCandidate(
          candidates,
          frappe.defaults.get_user_default("Branch") || "",
          "User Default"
        );
      }
    } catch (error) {
      // Continue with Employee/User Permission resolution.
    }

    // 2. Active Employee record linked to the logged-in user.
    // Employee and User Permission are independent lookups. Resolve them in
    // parallel so branch users do not pay two sequential network round trips.
    const accessRows = await Promise.all([
      safeDirectList(
        "Employee",
        ["name", "branch", "user_id", "status"],
        [["user_id", "=", user], ["status", "=", "Active"]],
        "modified desc",
        5
      ),
      safeDirectList(
        "User Permission",
        ["name", "allow", "for_value", "user", "is_default"],
        [["user", "=", user], ["allow", "=", "Branch"]],
        "is_default desc, modified desc",
        50
      )
    ]);
    const employees = accessRows[0];
    const permissions = accessRows[1];

    employees.forEach(function (row) {
      addBranchCandidate(candidates, row.branch, "Employee.branch");
    });

    // 3. Branch User Permission. On sites where normal users cannot read
    // User Permission directly, the two methods above still keep branch
    // resolution working without an ERPNext permission popup.

    permissions.forEach(function (row) {
      addBranchCandidate(candidates, row.for_value, "User Permission");
    });

    if (!candidates.length) return;

    STATE.access.restricted = true;
    STATE.access.allowedBranches = candidates.map(function (row) { return row.name; });
    STATE.access.activeBranch = candidates.length === 1 ? candidates[0].name : "";
    STATE.access.resolvedBy = candidates.map(function (row) { return row.source; })
      .filter(Boolean)
      .filter(function (value, index, array) { return array.indexOf(value) === index; })
      .join(" + ");
  }

  function isBranchAllowedForUser(value) {
    if (!STATE.access || !STATE.access.restricted) return true;

    const key = normalizeBranchText(canonicalBranchDisplayName(value));
    if (!key) return false;

    return (STATE.access.allowedBranches || []).some(function (branch) {
      return normalizeBranchText(canonicalBranchDisplayName(branch)) === key;
    });
  }

  function lockedBranchValue() {
    return STATE.access && STATE.access.restricted && STATE.access.allowedBranches.length === 1
      ? STATE.access.allowedBranches[0]
      : "";
  }

  function enforceBranchFilter() {
    if (!STATE.access || !STATE.access.restricted) return;

    const locked = lockedBranchValue();
    if (locked) {
      STATE.filters.location = locked;
      setFilterControl("location", locked);
    } else if (
      STATE.filters.location &&
      !isBranchAllowedForUser(STATE.filters.location)
    ) {
      STATE.filters.location = "";
      setFilterControl("location", "");
    }
  }

  function applyBranchScopeToLoadedData() {
    if (!STATE.access || !STATE.access.restricted) return;

    const assetRows = (STATE.data.assets || []).filter(function (asset) {
      return isBranchAllowedForUser(getLifeBranchName(asset.location));
    });
    const assetNames = new Set(assetRows.map(function (asset) { return asset.name; }));

    STATE.data.assets = assetRows;

    STATE.data.branches = (STATE.data.branches || []).filter(function (row) {
      return isBranchAllowedForUser(row.branch || row.name || "");
    });

    STATE.data.suppliers = (STATE.data.suppliers || []).filter(function (row) {
      return isBranchAllowedForUser(row.custom_branch || "");
    });

    STATE.data.checks = (STATE.data.checks || []).filter(function (row) {
      if (row.asset && assetNames.has(row.asset)) return true;
      return isBranchAllowedForUser(row.location || "");
    });

    STATE.data.repairs = (STATE.data.repairs || []).filter(function (row) {
      return row.asset && assetNames.has(row.asset);
    });

    STATE.data.maintenance = (STATE.data.maintenance || []).filter(function (row) {
      return row.asset_name && assetNames.has(row.asset_name);
    });

    STATE.data.machineryTransfers = (STATE.data.machineryTransfers || []).filter(function (row) {
      const sourceBranch = canonicalBranchDisplayName(row.source_branch || "");
      const targetBranch = canonicalBranchDisplayName(row.target_branch || "");
      return isBranchAllowedForUser(sourceBranch) || isBranchAllowedForUser(targetBranch);
    });

    STATE.data.machineryRequests = (STATE.data.machineryRequests || []).filter(function (row) {
      const isRequestingBranch = isBranchAllowedForUser(row.requesting_branch || "");
      const isApprovedSourceBranch = ["Approved", "Asset Allocated", "Transfer Created", "Completed"].indexOf(String(row.request_status || "")) !== -1 &&
        isBranchAllowedForUser(row.allocated_source_branch || "");
      return isRequestingBranch || isApprovedSourceBranch;
    });

    STATE.data.movementItems = (STATE.data.movementItems || []).filter(function (row) {
      return row.asset && assetNames.has(row.asset);
    });

    const movementNames = new Set(
      STATE.data.movementItems.map(function (row) { return row.parent; }).filter(Boolean)
    );
    STATE.data.movements = (STATE.data.movements || []).filter(function (row) {
      return movementNames.has(row.name);
    });

    STATE.data.depreciation = (STATE.data.depreciation || []).filter(function (row) {
      return row.asset && assetNames.has(row.asset);
    });

    STATE.data.activities = (STATE.data.activities || []).filter(function (row) {
      return row.asset && assetNames.has(row.asset);
    });

    // Ticket / Helpdesk saves Branch, Category and Specific Issue inside the
    // LIFE_TICKET_META block in Issue.description. Use that confirmed metadata
    // to enforce branch access before any complaint is rendered.
    STATE.data.issues = (STATE.data.issues || []).filter(function (row) {
      const meta = getLifeHelpdeskTicketMeta(row);
      return isAssetHelpdeskComplaint(meta) && isBranchAllowedForUser(meta.branch || "");
    });

    Object.keys(STATE.sources || {}).forEach(function (key) {
      if (STATE.sources[key] && Array.isArray(STATE.data[key])) {
        STATE.sources[key].count = STATE.data[key].length;
      }
    });
  }

  function lockBranchFilterControl() {
    const select = STATE.root.querySelector('[data-filter="location"]');
    if (!select) return;

    if (!STATE.access || !STATE.access.restricted) {
      select.disabled = false;
      select.removeAttribute("title");
      return;
    }

    const allowed = sortLifeBranchNames(
      uniqueSorted((STATE.access.allowedBranches || []).filter(function (branch) {
        return !isTestingBranchName(branch);
      }))
    );

    if (allowed.length === 1) {
      select.innerHTML = '<option value="' + escapeAttribute(allowed[0]) + '">' +
        escapeHtml(allowed[0]) + "</option>";
      select.value = allowed[0];
      select.disabled = true;
      select.title = "Branch is locked to the logged-in user's ERPNext branch.";
      STATE.filters.location = allowed[0];
    } else {
      const current = isBranchAllowedForUser(STATE.filters.location)
        ? STATE.filters.location
        : "";
      select.innerHTML = '<option value="">All permitted branches</option>' +
        allowed.map(function (branch) {
          return '<option value="' + escapeAttribute(branch) + '">' + escapeHtml(branch) + "</option>";
        }).join("");
      select.value = current;
      select.disabled = false;
      select.title = "Only branches assigned to this user are available.";
      STATE.filters.location = current;
    }
  }

  async function loadAllData() {
    if (STATE.loading) return;

    setLoading(true, "Reading Asset records…");

    STATE.sources = {};
    STATE.operationalSourcesLoaded = false;
    STATE.operationalSourcesLoading = false;

    try {
      await resolveDashboardUserRoles();
      await resolveLoggedInBranchAccess();
      // First paint needs only the Asset register and its small master lists.
      // Operational registers and large history sources are deliberately not
      // allowed to delay the first usable screen.
      await Promise.all([
        loadSource("assets"),
        loadSource("assetCategories"),
        loadSource("branches")
      ]);

      setLoading(true, "Preparing permitted Asset views…");

      // Approval email deep links are the exception: preload the two workflow
      // sources so the requested approval opens immediately and reliably.
      const deepLink = getDashboardDeepLink();
      if (deepLink.page === "approvals" || deepLink.request) {
        await Promise.all([
          loadSource("machineryRequests"),
          loadSource("machineryTransfers")
        ]);
        await Promise.all([
          loadMachineryRequestEmployeeNames(),
          loadLinkedMachineryTransfers()
        ]);
      }

      // Apply the logged-in branch boundary before any filter, KPI, report,
      // Machine 360, export, label, supplier, check or master is rendered.
      applyBranchScopeToLoadedData();

      STATE.loadedAt = new Date();

      // Restricted optional pages must never become the apparent landing page.
      // Keep the live Asset Command Centre visible when Asset Movement cannot
      // be read by the current role.
      if (
        STATE.currentPage === "movements" &&
        !sourceAvailable("machineryTransfers") &&
        !sourceAvailable("movements")
      ) {
        STATE.currentPage = "dashboard";
        STATE.root.querySelectorAll("[data-page-panel]").forEach(function (panel) {
          panel.classList.toggle("is-active", panel.dataset.pagePanel === "dashboard");
        });
        STATE.root.querySelectorAll("[data-page]").forEach(function (button) {
          button.classList.toggle("is-active", button.dataset.page === "dashboard");
        });
      }

      populateFilterOptions();
      readFiltersFromControls();
      applyFiltersAndRender();
      applyDashboardDeepLink();
      updateHeaderSummary();
      showToast(
        STATE.access.restricted
          ? ((STATE.access.allowedBranches || []).join(", ") + " branch data loaded.")
          : "Live Asset records refreshed. Missing or restricted DocTypes were not queried."
      );
      window.setTimeout(loadDeferredOperationalSources, 80);
    } catch (error) {
      void 0;
      renderFatalError(error);
      showToast(error.message || "Could not load Asset data.", true);
    } finally {
      setLoading(false);
    }
  }

  async function loadDeferredOperationalSources() {
    if (STATE.operationalSourcesLoading || STATE.operationalSourcesLoaded) return;
    STATE.operationalSourcesLoading = true;
    try {
      await Promise.all([
        "checks",
        "maintenance",
        "issues",
        "machineryRequests",
        "machineryTransfers"
      ].map(function (key) {
        return sourceAvailable(key) ? Promise.resolve() : loadSource(key);
      }));
      normalizeTechnicianVisitSource();
      await Promise.all([
        loadMachineryRequestEmployeeNames(),
        loadLinkedMachineryTransfers()
      ]);
      applyBranchScopeToLoadedData();
      STATE.operationalSourcesLoaded = true;
      populateFilterOptions();
      readFiltersFromControls();
      applyFiltersAndRender();
      updateHeaderSummary();
    } catch (error) {
      void 0;
    } finally {
      STATE.operationalSourcesLoading = false;
    }
  }

  async function loadDeferredDashboardSources() {
    if (STATE.deferredSourcesLoading) return;
    STATE.deferredSourcesLoading = true;
    try {
      await Promise.all([
        loadSource("activities"),
        loadSource("depreciation"),
        loadSource("movements"),
        loadSource("movementItems")
      ]);
      applyBranchScopeToLoadedData();
      applyFiltersAndRender();
      updateHeaderSummary();
    } catch (error) {
      // These sources support history and reports only. The operational
      // dashboard remains usable when either source is unavailable.
      void 0;
    } finally {
      STATE.deferredSourcesLoading = false;
    }
  }

  function normalizeTechnicianVisitSource() {
    STATE.data.maintenance = (STATE.data.maintenance || []).map(function (row) {
      return Object.assign({}, row, {
        custom_asset_name: row.asset_name || "",
        asset_maintenance: row.name || "",
        asset_name: row.asset || "",
        item_code: row.asset || "",
        item_name: row.asset_name || "",
        task_name: row.task || "",
        maintenance_type: row.visit_type || "",
        periodicity: "",
        maintenance_status: row.status || "Scheduled",
        assign_to_name: row.technician_name || "",
        task_assignee_email: row.technician_email || "",
        due_date: row.scheduled_date || "",
        completion_date: row.visit_completed_on || "",
        description: row.technician_findings || row.completion_remark || "",
        location: row.branch__location || ""
      });
    });
  }

  function renderFatalError(error) {
    const body = pageBody("dashboard");
    if (!body) return;

    body.innerHTML = noticeHtml(
      "Asset data could not be loaded",
      escapeHtml(error && error.message ? error.message : String(error)),
      "bad"
    );

  }

  function populateFilterOptions() {
    const assets = getProductionAssets();


    const branchMasterNames = getBranchMasterNames();
    const assetBranchNames = uniqueSorted(assets.map(function (row) {
      return getLifeBranchName(row.location);
    }));
    const branchFilterNames = sortLifeBranchNames(uniqueSorted(
      branchMasterNames.concat(assetBranchNames)
    ));

    setSelectOptions(
      "location",
      branchFilterNames.filter(function (branch) { return isBranchAllowedForUser(branch); }),
      sourceAvailable("branches") ? "All Branches" : "All Branches / Locations"
    );
    lockBranchFilterControl();

    const realAssetCategories = sourceAvailable("assetCategories")
      ? uniqueSorted((STATE.data.assetCategories || []).map(function (row) { return row.name; }))
      : uniqueSorted(assets.map(function (row) { return row.asset_category; }));
    setSelectOptions("category", realAssetCategories, "All Asset Categories");
    setSelectOptions(
      "machinery_category",
      ["Skin", "Slimming"],
      "All Machinery Categories"
    );
    // Department is a real Asset filter. Build its options only from
    // permitted live Asset records so branch users see only relevant values.
    const departmentNames = uniqueSorted(
      assets.map(function (row) { return row.department; }).filter(Boolean)
    );
    setSelectOptions("department", departmentNames, "All Departments");

    // Supplier and Status remain removed from the visible Master Filter.
    setSelectOptions("supplier", [], "All Suppliers / Vendors");
    setSelectOptions("status", [], "All Statuses");
    refreshAssetSearchOptionsForFilters();
  }

  function populateAssetSearchOptions(assetRows) {
    const input = STATE.root.querySelector('[data-filter="search"]');
    if (!input) return;

    const listId = "life-asset-search-select-options";
    let list = STATE.root.querySelector("#" + listId);
    if (!list) {
      list = document.createElement("datalist");
      list.id = listId;
      STATE.root.appendChild(list);
    }

    const assets = (assetRows || []).slice().sort(function (a, b) {
      return String(a.asset_name || a.item_name || a.name).localeCompare(
        String(b.asset_name || b.item_name || b.name),
        undefined,
        { numeric: true, sensitivity: "base" }
      );
    });
    list.innerHTML = assets.map(function (asset) {
      const label = [
        asset.asset_name || asset.item_name || "Unnamed Asset",
        getLifeBranchName(asset.location) || "No branch"
      ].join(" · ");
      return '<option value="' + escapeAttribute(asset.name) + '" label="' + escapeAttribute(label) + '"></option>';
    }).join("");
    input.setAttribute("list", listId);
    input.setAttribute("autocomplete", "off");
    input.setAttribute("aria-label", "Select or search Asset");
  }

  function refreshAssetSearchOptionsForFilters() {
    const filters = STATE.filters || {};
    const eligibleAssets = getProductionAssets().filter(function (asset) {
      const branch = getLifeBranchName(asset.location);
      if (!isBranchAllowedForUser(branch) || isTestingBranchName(branch)) return false;
      if (filters.location && branch !== filters.location) return false;
      if (filters.category && asset.asset_category !== filters.category) return false;
      if (filters.machinery_category && asset.custom_machinery_assets_category !== filters.machinery_category) return false;
      return true;
    });

    const selectedSearch = String(filters.search || "").trim();
    const selectedIsAssetId = (STATE.data.assets || []).some(function (asset) { return asset.name === selectedSearch; });
    const selectedStillEligible = eligibleAssets.some(function (asset) { return asset.name === selectedSearch; });
    if (selectedIsAssetId && !selectedStillEligible) {
      STATE.filters.search = "";
      const input = STATE.root.querySelector('[data-filter="search"]');
      if (input) input.value = "";
    }

    populateAssetSearchOptions(eligibleAssets);
  }

  function setSelectOptions(filterName, values, allLabel) {
    const select = STATE.root.querySelector('[data-filter="' + filterName + '"]');
    if (!select) return;

    const current = STATE.filters[filterName] || select.value || "";
    select.innerHTML = '<option value="">' + escapeHtml(allLabel) + "</option>" + values
      .map(function (value) {
        return '<option value="' + escapeAttribute(value) + '">' + escapeHtml(value) + "</option>";
      })
      .join("");

    if (values.indexOf(current) !== -1) {
      select.value = current;
    } else {
      STATE.filters[filterName] = "";
      select.value = "";
    }
  }

  function uniqueSorted(values) {
    return Array.from(new Set(values.filter(function (value) { return value != null && String(value).trim() !== ""; })))
      .map(String)
      .sort(function (a, b) { return a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }); });
  }


  function isTestingBranchName(value) {
    const normalized = normalizeBranchText(canonicalBranchDisplayName(value));
    return normalized === normalizeBranchText("Testing Branch");
  }

  function getProductionAssets() {
    return (STATE.data.assets || []).filter(function (asset) {
      const branch = getLifeBranchName(asset.location);
      return !isTestingBranchName(branch) && isBranchAllowedForUser(branch);
    });
  }

  const LIFE_BRANCH_ORDER = [
    "Head Office",
    "Chanda Nagar",
    "Madhapur",
    "Gachibowli",
    "Kukatpally",
    "S.R. Nagar",
    "Banjara Hills",
    "Dilsukhnagar",
    "Himayatnagar",
    "Vijayawada",
    "Vizag",
    "Nellore"
  ];

  // Exact Branch document IDs confirmed by the LIFE Helpdesk branch selector.
  // These keep Target Branch available for permission-restricted branch users
  // whose Branch get_list response contains only their own branch.
  const LIFE_TRANSFER_BRANCH_IDS = [
    "Head Office",
    "Chandanagar",
    "S R Nagar",
    "Madhapur",
    "Banjara Hills",
    "Himayathnagar",
    "Dilsukhnagar",
    "Gachibowli",
    "Vijayawada",
    "Vizag",
    "Nellore",
    "Kukatpally"
  ];

  function normalizeBranchText(value) {
    return String(value == null ? "" : value)
      .toUpperCase()
      .replace(/&/g, " AND ")
      .replace(/[._/\\()[\]]/g, " ")
      .replace(/[–—-]+/g, " ")
      .replace(/\bLIFE\s+SLIMMING(?:\s+AND\s+COSMETIC)?(?:\s+PVT\.?\s+LTD\.?)?\b/g, " ")
      .replace(/\bLSACPL\b/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

  function canonicalBranchDisplayName(value) {
    const raw = String(value == null ? "" : value).trim();
    if (!raw) return "";

    const text = normalizeBranchText(raw);

    const mappings = [
      { label: "Head Office", pattern: /\bHEAD\s*OFFICE\b|\bCORPORATE\s*OFFICE\b|(?:^|\s)HO(?:\s|$)/ },
      { label: "Chanda Nagar", pattern: /\bCHANDA\s*NAGAR\b|\bCHANDANAGAR\b|(?:^|\s)L?\s*CND(?:\s|$)/ },
      { label: "Madhapur", pattern: /\bMADHAPUR\b|(?:^|\s)L?\s*MP(?:\s|$)/ },
      { label: "Gachibowli", pattern: /\bGACHIBOWLI\b|(?:^|\s)L?\s*GB(?:\s|$)/ },
      { label: "Kukatpally", pattern: /\bKPHB\b|\bKUKATPALLY\b|\bKUKAT\s*PALLY\b|(?:^|\s)L?\s*KP(?:\s|$)/ },
      { label: "S.R. Nagar", pattern: /\bS\s*R\s*NAGAR\b|\bSR\s*NAGAR\b|(?:^|\s)L?\s*SRN(?:\s|$)/ },
      { label: "Banjara Hills", pattern: /\bBANJARA(?:\s*HILLS?)?\b|(?:^|\s)L?\s*BH(?:\s|$)/ },
      { label: "Dilsukhnagar", pattern: /\b(?:DILSUKH|DILSHUKH?)\s*NAGAR\b|(?:^|\s)L?\s*DN(?:\s|$)/ },
      { label: "Himayatnagar", pattern: /\bHIMAYATH?\s*NAGAR\b|\bHIMAYATNAGAR\b|(?:^|\s)L?\s*HN(?:\s|$)/ },
      { label: "Vijayawada", pattern: /\bVIJAYAWADA\b|(?:^|\s)L?\s*VW(?:\s|$)/ },
      { label: "Vizag", pattern: /\bVIZAG\b|\bVISAKHAPATNAM\b|(?:^|\s)L?\s*VZ(?:\s|$)/ },
      { label: "Nellore", pattern: /\bNELLORE\b|(?:^|\s)L?\s*NLR(?:\s|$)/ },
      { label: "Testing Branch", pattern: /\bTESTING\s*BRANCH\b|\bTEST\s*BRANCH\b/ }
    ];

    for (let i = 0; i < mappings.length; i += 1) {
      if (mappings[i].pattern.test(text)) return mappings[i].label;
    }

    return raw
      .replace(/\s+/g, " ")
      .trim();
  }

  function warehouseDisplayName(value) {
    return String(value == null ? "" : value)
      .replace(/\s*[-–—]\s*LSACPL\s*$/i, "")
      .replace(/\s+LSACPL\s*$/i, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  function getBranchMasterNames() {
    return uniqueSorted((STATE.data.branches || []).map(function (row) {
      return canonicalBranchDisplayName(row.branch || row.name || "");
    }).filter(function (name) {
      return Boolean(name) && !isTestingBranchName(name);
    }));
  }

  function findExactBranchMasterName(value) {
    const raw = String(value == null ? "" : value).trim();
    if (!raw) return "";

    const normalized = normalizeBranchText(raw);
    if (!normalized) return "";

    const branches = getBranchMasterNames();

    for (let i = 0; i < branches.length; i += 1) {
      if (normalizeBranchText(branches[i]) === normalized) {
        return branches[i];
      }
    }

    const candidates = branches.filter(function (branch) {
      const branchNormalized = normalizeBranchText(branch);
      if (!branchNormalized || branchNormalized.length < 3) return false;
      return normalized.indexOf(branchNormalized) !== -1 ||
        branchNormalized.indexOf(normalized) !== -1;
    });

    if (candidates.length) {
      candidates.sort(function (a, b) {
        return normalizeBranchText(b).length - normalizeBranchText(a).length;
      });
      return candidates[0];
    }

    return "";
  }

  function resolveAliasToBranchMaster(aliasLabel) {
    return findExactBranchMasterName(aliasLabel) || aliasLabel;
  }

  function getLifeBranchName(value) {
    const raw = String(value == null ? "" : value).trim();
    if (!raw) return "Unassigned Location";

    const directMasterMatch = findExactBranchMasterName(raw);
    if (directMasterMatch) return directMasterMatch;

    const text = normalizeBranchText(raw);

    const matches = [
      { label: "Head Office", pattern: /\bHEAD\s*OFFICE\b|\bCORPORATE\s*OFFICE\b|(?:^|\s)HO(?:\s|$)/ },
      { label: "Chanda Nagar", pattern: /\bCHANDA\s*NAGAR\b|\bCHANDANAGAR\b|(?:^|\s)L?\s*CND(?:\s|$)/ },
      { label: "Madhapur", pattern: /\bMADHAPUR\b|(?:^|\s)L?\s*MP(?:\s|$)/ },
      { label: "Gachibowli", pattern: /\bGACHIBOWLI\b|(?:^|\s)L?\s*GB(?:\s|$)/ },
      { label: "Kukatpally", pattern: /\bKPHB\b|\bKUKATPALLY\b|\bKUKAT\s*PALLY\b|(?:^|\s)L?\s*KP(?:\s|$)/ },
      { label: "S.R. Nagar", pattern: /\bS\s*R\s*NAGAR\b|\bSR\s*NAGAR\b|(?:^|\s)L?\s*SRN(?:\s|$)/ },
      { label: "Banjara Hills", pattern: /\bBANJARA\s*HILLS?\b|(?:^|\s)L?\s*BH(?:\s|$)/ },
      { label: "Dilsukhnagar", pattern: /\b(?:DILSUKH|DILSHUKH?)\s*NAGAR\b|(?:^|\s)L?\s*DN(?:\s|$)/ },
      { label: "Himayatnagar", pattern: /\bHIMAYAT\s*NAGAR\b|\bHIMAYATNAGAR\b|(?:^|\s)L?\s*HN(?:\s|$)/ },
      { label: "Vijayawada", pattern: /\bVIJAYAWADA\b|(?:^|\s)L?\s*VW(?:\s|$)/ },
      { label: "Vizag", pattern: /\bVIZAG\b|\bVISAKHAPATNAM\b|(?:^|\s)L?\s*VZ(?:\s|$)/ },
      { label: "Nellore", pattern: /\bNELLORE\b|(?:^|\s)L?\s*NLR(?:\s|$)/ },
      { label: "Testing Branch", pattern: /\bTESTING\s*BRANCH\b|\bTEST\s*BRANCH\b/ }
    ];

    for (let i = 0; i < matches.length; i += 1) {
      if (matches[i].pattern.test(text)) {
        return resolveAliasToBranchMaster(matches[i].label);
      }
    }

    const cleaned = raw
      .replace(/\s*[-–—]\s*(?:LIFE\s+SLIMMING.*|LSACPL.*)$/i, "")
      .replace(/\s+/g, " ")
      .trim();

    return canonicalBranchDisplayName(cleaned || raw);
  }

  function sortLifeBranchNames(values) {
    return values.slice().sort(function (a, b) {
      const normalizedA = normalizeBranchText(a);
      const normalizedB = normalizeBranchText(b);

      const canonicalA = LIFE_BRANCH_ORDER.findIndex(function (name) {
        return normalizeBranchText(name) === normalizedA;
      });
      const canonicalB = LIFE_BRANCH_ORDER.findIndex(function (name) {
        return normalizeBranchText(name) === normalizedB;
      });

      if (canonicalA !== -1 || canonicalB !== -1) {
        if (canonicalA === -1) return 1;
        if (canonicalB === -1) return -1;
        return canonicalA - canonicalB;
      }

      return a.localeCompare(b, undefined, {
        numeric: true,
        sensitivity: "base"
      });
    });
  }

  function readFiltersFromControls() {
    STATE.root.querySelectorAll("[data-filter]").forEach(function (control) {
      STATE.filters[control.dataset.filter] = control.value || "";
    });
    enforceBranchFilter();
  }

  function currentDateFilterSnapshot() {
    return {
      period: STATE.filters.period || "custom",
      from: STATE.filters.from || "",
      to: STATE.filters.to || ""
    };
  }

  function saveCurrentPageDateFilters() {
    const snapshot = currentDateFilterSnapshot();
    if (STATE.currentPage === "movements") STATE.transferDateFilters = snapshot;
    else STATE.mainDateFilters = snapshot;
  }

  function restoreDateFiltersForPage(page) {
    let snapshot;
    if (page === "movements") {
      snapshot = STATE.transferDateFilters || STATE.mainDateFilters || currentDateFilterSnapshot();
      STATE.transferDateFilters = Object.assign({}, snapshot);
    } else {
      snapshot = STATE.mainDateFilters || currentDateFilterSnapshot();
      STATE.mainDateFilters = Object.assign({}, snapshot);
    }
    STATE.filters.period = snapshot.period || "custom";
    STATE.filters.from = snapshot.from || "";
    STATE.filters.to = snapshot.to || "";
    setFilterControl("period", STATE.filters.period);
    setFilterControl("from", STATE.filters.from);
    setFilterControl("to", STATE.filters.to);
  }

  function enhanceMasterDateControls() {
    if (!STATE.root) return;

    ["from", "to"].forEach(function (name) {
      const control = STATE.root.querySelector('[data-filter="' + name + '"]');
      if (!control || control.type !== "date" || control.closest(".la-master-formatted-date")) return;

      const wrapper = document.createElement("div");
      wrapper.className = "la-master-formatted-date";

      const display = document.createElement("input");
      display.type = "text";
      display.className = "la-master-formatted-date-display";
      display.readOnly = true;
      display.tabIndex = -1;
      display.setAttribute("aria-hidden", "true");

      const icon = document.createElement("span");
      icon.className = "la-master-formatted-date-icon";
      icon.setAttribute("aria-hidden", "true");
      icon.textContent = "▦";

      control.parentNode.insertBefore(wrapper, control);
      wrapper.appendChild(display);
      wrapper.appendChild(icon);
      wrapper.appendChild(control);
      updateMasterDateDisplay(control);
    });
  }

  function updateMasterDateDisplay(control) {
    if (!control) return;
    const wrapper = control.closest(".la-master-formatted-date");
    if (!wrapper) return;
    const display = wrapper.querySelector(".la-master-formatted-date-display");
    if (display) display.value = control.value ? formatDate(control.value) : "";
    wrapper.classList.toggle("is-disabled", Boolean(control.disabled));
  }

  function setFilterControl(name, value) {
    const control = STATE.root.querySelector('[data-filter="' + name + '"]');
    if (control) {
      control.value = value == null ? "" : String(value);
      if (name === "from" || name === "to") updateMasterDateDisplay(control);
    }
  }

  function resetFilters() {
    STATE.branchDrilldownActive = false;
    STATE.filters = {
      period: "this_month",
      from: "",
      to: "",
      company: "",
      location: lockedBranchValue(),
      category: "",
      machinery_category: "",
      department: "",
      supplier: "",
      status: "",
      search: ""
    };

    Object.keys(STATE.filters).forEach(function (key) {
      setFilterControl(key, STATE.filters[key]);
    });

    syncPeriodInputs(true);
    saveCurrentPageDateFilters();
    applyFiltersAndRender();
  }

  function scheduleFilterApply(delay) {
    clearTimeout(STATE.filterTimer);
    STATE.filterTimer = setTimeout(function () {
      readFiltersFromControls();
      saveCurrentPageDateFilters();
      applyFiltersAndRender();
    }, delay || 0);
  }

  function syncPeriodInputs(initial) {
    const period = STATE.filters.period || getFilterValue("period") || "this_month";
    const range = getPeriodRange(period);

    if (period !== "custom") {
      STATE.filters.from = range.from;
      STATE.filters.to = range.to;
      setFilterControl("from", range.from);
      setFilterControl("to", range.to);
    } else if (initial && (!STATE.filters.from || !STATE.filters.to)) {
      const current = getPeriodRange("this_month");
      STATE.filters.from = current.from;
      STATE.filters.to = current.to;
      setFilterControl("from", current.from);
      setFilterControl("to", current.to);
    }

    const disabled = period !== "custom" && period !== "all";
    const fromControl = STATE.root.querySelector('[data-filter="from"]');
    const toControl = STATE.root.querySelector('[data-filter="to"]');
    if (fromControl) fromControl.disabled = period === "all";
    if (toControl) toControl.disabled = period === "all";
    updateMasterDateDisplay(fromControl);
    updateMasterDateDisplay(toControl);

    if (disabled) {
      if (fromControl) fromControl.title = "Choose Custom to edit this date.";
      if (toControl) toControl.title = "Choose Custom to edit this date.";
    }
  }

  function getFilterValue(name) {
    const control = STATE.root.querySelector('[data-filter="' + name + '"]');
    return control ? control.value : "";
  }

  function getPeriodRange(period) {
    const today = startOfDay(new Date());
    let from = null;
    let to = new Date(today);

    switch (period) {
      case "today":
        from = new Date(today);
        break;
      case "this_week": {
        const day = today.getDay() || 7;
        from = addDays(today, 1 - day);
        break;
      }
      case "this_month": {
        // LIFE business month: 6th of the cycle month through 5th of next month.
        if (today.getDate() >= 6) {
          from = new Date(today.getFullYear(), today.getMonth(), 6);
          to = new Date(today.getFullYear(), today.getMonth() + 1, 5);
        } else {
          from = new Date(today.getFullYear(), today.getMonth() - 1, 6);
          to = new Date(today.getFullYear(), today.getMonth(), 5);
        }
        // Never show a future To date for the active cycle.
        if (to > today) to = new Date(today);
        break;
      }
      case "last_month": {
        let currentStart;
        if (today.getDate() >= 6) {
          currentStart = new Date(today.getFullYear(), today.getMonth(), 6);
        } else {
          currentStart = new Date(today.getFullYear(), today.getMonth() - 1, 6);
        }
        from = new Date(currentStart.getFullYear(), currentStart.getMonth() - 1, 6);
        to = new Date(currentStart.getFullYear(), currentStart.getMonth(), 5);
        break;
      }
      case "this_quarter": {
        const quarterStart = Math.floor(today.getMonth() / 3) * 3;
        from = new Date(today.getFullYear(), quarterStart, 1);
        break;
      }
      case "ytd":
        from = new Date(today.getFullYear(), 0, 1);
        break;
      case "all":
        return { from: "", to: "" };
      case "custom":
        return {
          from: STATE.filters.from || getFilterValue("from") || "",
          to: STATE.filters.to || getFilterValue("to") || ""
        };
      default:
        from = new Date(today.getFullYear(), today.getMonth(), 1);
        break;
    }

    return { from: toIsoDate(from), to: toIsoDate(to) };
  }

  function applyFiltersAndRender() {
    enforceBranchFilter();
    const filters = STATE.filters;
    const query = normalize(filters.search);
    const technicianPage = STATE.currentPage === "maintenance";
    const visibleDateSnapshot = currentDateFilterSnapshot();
    const mainDateSnapshot = STATE.currentPage === "movements"
      ? (STATE.mainDateFilters || visibleDateSnapshot)
      : visibleDateSnapshot;
    const transferDateSnapshot = STATE.currentPage === "movements"
      ? visibleDateSnapshot
      : (STATE.transferDateFilters || mainDateSnapshot);
    const mainRange = mainDateSnapshot.period === "all"
      ? { from: "", to: "" }
      : { from: mainDateSnapshot.from || "", to: mainDateSnapshot.to || "" };
    const transferRange = transferDateSnapshot.period === "all"
      ? { from: "", to: "" }
      : { from: transferDateSnapshot.from || "", to: transferDateSnapshot.to || "" };
    const movementRange = STATE.currentPage === "movements" ? transferRange : mainRange;

    const assets = STATE.data.assets.filter(function (asset) {
      const assetBranch = getLifeBranchName(asset.location);
      if (isTestingBranchName(assetBranch)) return false;
      if (!isBranchAllowedForUser(assetBranch)) return false;
      if (filters.company && asset.company !== filters.company) return false;
      if (filters.location && getLifeBranchName(asset.location) !== filters.location) return false;
      if (filters.category && asset.asset_category !== filters.category) return false;
      if (filters.machinery_category && asset.custom_machinery_assets_category !== filters.machinery_category) return false;
      if (!technicianPage && filters.department && asset.department !== filters.department) return false;
      if (!technicianPage && filters.supplier && asset.supplier !== filters.supplier) return false;
      if (!technicianPage && filters.status && asset.status !== filters.status) return false;

      if (query && !technicianPage) {
        const haystack = normalize([
          asset.name,
          asset.asset_name,
          asset.item_code,
          asset.item_name,
          asset.asset_category,
          asset.custom_machinery_assets_category,
          asset.location,
          getLifeBranchName(asset.location),
          asset.custodian,
          asset.department,
          asset.company,
          asset.supplier,
          asset.policy_number,
          asset.insurer,
          asset.status
        ].join(" "));
        if (haystack.indexOf(query) === -1) return false;
      }

      return true;
    });

    const assetNames = new Set(assets.map(function (asset) { return asset.name; }));

    STATE.filtered.assets = assets;
    STATE.filtered.branches = (STATE.data.branches || []).filter(function (row) {
      const branch = row.branch || row.name || "";
      return !isTestingBranchName(branch) && isBranchAllowedForUser(branch);
    });

    STATE.filtered.suppliers = (STATE.data.suppliers || []).filter(function (supplier) {
      if (!isBranchAllowedForUser(supplier.custom_branch || "")) return false;
      if (!filters.supplier) return true;

      return normalizeText(supplier.name) === normalizeText(filters.supplier) ||
        normalizeText(supplier.supplier_name) === normalizeText(filters.supplier);
    });

    const fullAssetMap = indexBy(getProductionAssets(), "name");
    STATE.filtered.checks = (STATE.data.checks || []).filter(function (row) {
      const linkedAsset = row.asset ? fullAssetMap[row.asset] : null;
      const rowLocation = getLifeBranchName(row.location || (linkedAsset ? linkedAsset.location : ""));

      if (isTestingBranchName(rowLocation)) return false;
      if (!isBranchAllowedForUser(rowLocation)) return false;
      if (row.asset && !assetNames.has(row.asset)) return false;
      if (!row.asset && filters.location && rowLocation !== filters.location) return false;
      if (filters.machinery_category && String(row.machinery_category || "") !== String(filters.machinery_category)) return false;
      if (!dateInRange(row.check_date || row.creation || row.modified, mainRange)) return false;

      if (query) {
        const haystack = normalize([
          row.name,
          row.asset,
          row.asset_name,
          rowLocation,
          row.machinery_category,
          row.machine_condition,
          row.check_type,
          row.checked_by,
          row.overall_result,
          row.linked_complaint,
          row.overall_remark
        ].join(" "));
        if (haystack.indexOf(query) === -1) return false;
      }

      return true;
    });

    STATE.filtered.maintenance = STATE.data.maintenance.filter(function (row) {
      if (!assetNames.has(row.asset_name)) return false;
      if (!dateInRange(row.due_date || row.completion_date || row.modified, mainRange)) return false;
      if (query && technicianPage) {
        const haystack = normalize([
          row.name,
          row.visit_number,
          row.asset_name,
          row.item_name,
          row.branch__location,
          row.visit_type,
          row.task,
          row.technician_name,
          row.technician_email,
          row.technician_mobile,
          row.status,
          row.technician_findings,
          row.actions_performed,
          row.parts_details,
          row.completion_remark
        ].join(" "));
        if (haystack.indexOf(query) === -1) return false;
      }
      return true;
    });
    STATE.filtered.repairs = STATE.data.repairs.filter(function (row) {
      return assetNames.has(row.asset) && dateInRange(row.failure_date || row.completion_date || row.modified, mainRange);
    });

    STATE.filtered.issues = STATE.data.issues.filter(function (row) {
      const ticketMeta = getLifeHelpdeskTicketMeta(row);
      if (!isAssetHelpdeskComplaint(ticketMeta)) return false;
      if (!isBranchAllowedForUser(ticketMeta.branch || "")) return false;
      if (filters.location && normalizeBranchText(ticketMeta.branch || "") !== normalizeBranchText(filters.location)) return false;

      if (!dateInRange(
        row.opening_date || row.creation || row.modified,
        mainRange
      )) {
        return false;
      }

      if (query) {
        const haystack = normalize([
          row.name,
          row.subject,
          row.customer,
          row.customer_name,
          row.raised_by,
          row.status,
          row.priority,
          row.issue_type,
          ticketMeta.branch,
          ticketMeta.category,
          ticketMeta.issue,
          ticketMeta.group,
          stripHtml(row.description || ""),
          row.service_level_agreement,
          row.agreement_status,
          stripHtml(row.resolution_details || ""),
          row.lead,
          row.contact,
          row.project,
          row.company,
          row.owner,
          row.modified_by
        ].join(" "));

        if (haystack.indexOf(query) === -1) return false;
      }

      return true;
    });

    STATE.filtered.machineryTransfers = (STATE.data.machineryTransfers || []).filter(function (row) {
      const sourceBranch = canonicalBranchDisplayName(row.source_branch || "");
      const targetBranch = canonicalBranchDisplayName(row.target_branch || "");
      const linkedRequest = (STATE.data.machineryRequests || []).find(function (requestRow) {
        return requestRow && requestRow.machinery_transfer === row.name;
      });
      const linkedAssetId = linkedRequest ? (linkedRequest.allocated_asset || "") : "";
      const linkedAsset = (STATE.sourceMachineryAssets || []).concat(STATE.data.assets || []).find(function (assetRow) {
        return assetRow && assetRow.name === linkedAssetId;
      });
      const linkedAssetCategory = (linkedAsset && linkedAsset.asset_category) || (linkedRequest && linkedRequest.asset_category) || "Machinery";
      const linkedMachineryCategory = (linkedAsset && linkedAsset.custom_machinery_assets_category) || (linkedRequest && linkedRequest.machinery_category) || "";
      if (isTestingBranchName(sourceBranch) || isTestingBranchName(targetBranch)) return false;
      if (!isBranchAllowedForUser(sourceBranch) && !isBranchAllowedForUser(targetBranch)) return false;
      if (filters.location && normalizeBranchText(sourceBranch) !== normalizeBranchText(filters.location) && normalizeBranchText(targetBranch) !== normalizeBranchText(filters.location)) return false;
      if (filters.category && normalizeText(linkedAssetCategory) !== normalizeText(filters.category)) return false;
      if (filters.machinery_category && normalizeText(linkedMachineryCategory) !== normalizeText(filters.machinery_category)) return false;
      if (!dateInRange(row.request_date_and_time || row.required_by || row.modified || row.creation, movementRange)) return false;

      if (query) {
        const haystack = normalize([
          row.name,
          sourceBranch,
          targetBranch,
          row.requested_by,
          row.requested_by_name,
          linkedAssetId,
          linkedAsset ? (linkedAsset.asset_name || linkedAsset.item_name || "") : "",
          linkedAssetCategory,
          linkedMachineryCategory,
          row.transfer_reason,
          row.transfer_status,
          row.source_warehouse,
          row.target_warehouse,
          stripHtml(row.remarks || ""),
          row.owner,
          row.modified_by
        ].join(" "));
        if (haystack.indexOf(query) === -1) return false;
      }

      return true;
    });

    STATE.filtered.machineryRequests = (STATE.data.machineryRequests || []).filter(function (row) {
      const branch = canonicalBranchDisplayName(row.requesting_branch || "");
      const sourceBranch = canonicalBranchDisplayName(row.allocated_source_branch || "");
      const filterBranch = canonicalBranchDisplayName(filters.location || "");
      const sourceVisible = ["Approved", "Asset Allocated", "Transfer Created", "Completed"].indexOf(String(row.request_status || "")) !== -1 && isBranchAllowedForUser(sourceBranch);
      if (isTestingBranchName(branch) || isTestingBranchName(sourceBranch)) return false;
      if (!isBranchAllowedForUser(branch) && !sourceVisible) return false;
      if (filterBranch && normalizeBranchText(branch) !== normalizeBranchText(filterBranch) && normalizeBranchText(sourceBranch) !== normalizeBranchText(filterBranch)) return false;
      if (filters.category && normalizeText(row.asset_category || "Machinery") !== normalizeText(filters.category)) return false;
      if (filters.machinery_category && normalizeText(row.machinery_category || "") !== normalizeText(filters.machinery_category)) return false;
      if (!dateInRange(row.request_date || row.required_by || row.modified || row.creation, movementRange)) return false;
      if (query) {
        const haystack = normalize([
          row.name, branch, row.requested_by, row.priority, row.requested_item,
          row.asset_category, row.machinery_category, row.requirement_reason,
          row.request_status, row.allocated_source_branch, row.allocated_asset,
          row.source_warehouse, row.target_warehouse, row.machinery_transfer
        ].join(" "));
        if (haystack.indexOf(query) === -1) return false;
      }
      return true;
    });

    STATE.filtered.movements = STATE.data.movements.filter(function (row) {
      if (!dateInRange(row.transaction_date || row.modified, movementRange)) return false;
      const items = STATE.data.movementItems.filter(function (item) { return item.parent === row.name; });
      return items.length === 0 || items.some(function (item) { return assetNames.has(item.asset); });
    });

    const movementNames = new Set(STATE.filtered.movements.map(function (row) { return row.name; }));
    STATE.filtered.movementItems = STATE.data.movementItems.filter(function (row) {
      return movementNames.has(row.parent) && assetNames.has(row.asset);
    });

    STATE.filtered.depreciation = STATE.data.depreciation.filter(function (row) {
      return assetNames.has(row.asset) && dateInRange(row.modified || row.creation, mainRange);
    });
    STATE.filtered.activities = STATE.data.activities.filter(function (row) {
      return assetNames.has(row.asset) && dateInRange(row.date || row.modified, mainRange);
    });

    STATE.tablePage = {};
    renderActiveFilters();
    updateNavCounts();
    updateHeaderSummary();
    renderCurrentPage();
  }

  function dateInRange(value, range) {
    if (!range || (!range.from && !range.to)) return true;
    const date = parseDate(value);
    if (!date) return false;

    if (range.from) {
      const from = parseDate(range.from);
      if (from && date < startOfDay(from)) return false;
    }

    if (range.to) {
      const to = parseDate(range.to);
      if (to && date > endOfDay(to)) return false;
    }

    return true;
  }

  function renderActiveFilters() {
    const wrap = STATE.root.querySelector("[data-active-filters]");
    if (!wrap) return;

    const labels = {
      period: "Period",
      location: "Branch / Location",
      category: "Category",
      machinery_category: "Machinery",
      department: "Department",
      supplier: "Supplier / Vendor",
      status: "Status",
      search: "Search"
    };

    const chips = [];

    const chipKeys = STATE.currentPage === "repairs"
      ? ["location", "search"]
      : STATE.currentPage === "checks"
        ? ["location", "category"]
      : STATE.currentPage === "maintenance"
        ? ["location", "category", "machinery_category", "search"]
        : STATE.currentPage === "movements"
          ? ["location", "category", "machinery_category", "search"]
        : STATE.currentPage === "approvals"
          ? ["location", "category", "machinery_category", "search"]
        : ["location", "category", "machinery_category", "department", "supplier", "status", "search"];

    chipKeys.forEach(function (key) {
      if (STATE.filters[key]) chips.push({ label: labels[key], value: STATE.filters[key] });
    });

    wrap.innerHTML = chips.map(function (chip) {
      return '<span class="la-filter-chip"><b>' + escapeHtml(chip.label) + ":</b> " + escapeHtml(chip.value) + "</span>";
    }).join("");
  }

  function updateNavCounts() {
    const approvalRows = getApprovalQueueRows();

    const counts = {
      // Asset Register displays one row per Asset document.
      assets: STATE.filtered.assets.length,
      checks: sourceAvailable("checks") ? STATE.filtered.checks.length : null,
      complaints: sourceAvailable("issues")
        ? STATE.filtered.issues.filter(function (row) {
            const status = String(row.status || "").toLowerCase();
            return status !== "resolved" && status !== "closed";
          }).length
        : null,
      technicians: sourceAvailable("maintenance")
        ? STATE.filtered.maintenance.length
        : null,
      movements: sourceAvailable("machineryTransfers") || sourceAvailable("machineryRequests")
        ? STATE.filtered.machineryTransfers.length + STATE.filtered.machineryRequests.length
        : STATE.filtered.movements.length,
      approvals: approvalRows.length,
      depreciation: getDepreciationDueAssets().length
    };

    Object.keys(counts).forEach(function (key) {
      const elements = STATE.root.querySelectorAll('[data-count="' + key + '"]');
      if (!elements.length) return;
      elements.forEach(function (element) {
        if (counts[key] == null) {
          element.textContent = "—";
          element.title = "This live source is unavailable or Read permission is not assigned.";
        } else {
          element.textContent = formatNumber(counts[key]);
          element.removeAttribute("title");
        }
      });
    });

    const movementButton = STATE.root.querySelector('[data-page="movements"]');
    if (movementButton) {
      const restricted = !sourceAvailable("machineryTransfers") && !sourceAvailable("movements");
      // Branch users must still be able to open the page and create a transfer
      // request even when their role cannot read the historical registers.
      movementButton.classList.remove("is-disabled");
      movementButton.setAttribute("aria-disabled", "false");
      movementButton.title = restricted
        ? "Transfer request entry is available. Historical records require Machinery Transfer Read permission."
        : "";
    }
  }

  function updateHeaderSummary() {
    const productionAssets = getProductionAssets();
    const locations = uniqueSorted(
      productionAssets.map(function (asset) {
        return getLifeBranchName(asset.location);
      }).filter(function (name) { return name && !isTestingBranchName(name); })
    );

    const summary =
      formatNumber(sumAssetUnits(productionAssets)) +
      " asset units · " +
      formatNumber(locations.length) +
      " branches / locations";

    setText("[data-branch-summary]", summary);
  }

  function syncCheckDeskAssetSelector(show, assetRows) {
    const machineryControl = STATE.root.querySelector('[data-filter="machinery_category"]');
    const machineryField = machineryControl ? machineryControl.closest(".la-field") : null;
    let field = STATE.root.querySelector("[data-check-asset-filter]");

    if (!show) {
      if (field) field.style.display = "none";
      return;
    }

    if (!field) {
      field = document.createElement("div");
      field.className = "la-field";
      field.dataset.checkAssetFilter = "1";
      field.innerHTML = '<span>Asset</span><select data-check-asset-select aria-label="Select Asset for Check Desk"></select>';
      if (machineryField && machineryField.parentNode) {
        machineryField.parentNode.insertBefore(field, machineryField.nextSibling);
      }
    }

    field.style.display = "";
    const select = field.querySelector("[data-check-asset-select]");
    if (!select) return;

    const assets = (assetRows || STATE.filtered.assets || getProductionAssets()).slice().sort(function (a, b) {
      return String(a.asset_name || a.item_name || a.name).localeCompare(
        String(b.asset_name || b.item_name || b.name),
        undefined,
        { numeric: true, sensitivity: "base" }
      );
    });
    select.innerHTML = '<option value="">Select Asset</option>' + assets.map(function (asset) {
      return '<option value="' + escapeAttribute(asset.name) + '">' +
        escapeHtml(asset.name + " · " + (asset.asset_name || asset.item_name || "Unnamed Asset")) +
      '</option>';
    }).join("");
    select.value = assets.some(function (asset) { return asset.name === STATE.checkAssetName; })
      ? STATE.checkAssetName
      : "";
    select.onchange = function () {
      STATE.checkAssetName = select.value || "";
      renderCheckDesk();
    };
  }

  function syncMasterFiltersForPage(page) {
    const complaintPage = page === "repairs";
    const checkPage = page === "checks";
    const technicianPage = page === "maintenance";
    const transferPage = page === "movements";
    const approvalPage = page === "approvals";
    const assetOnlyFilters = ["category", "machinery_category", "department", "supplier", "status"];
    const permanentlyHiddenFilters = ["supplier", "status"];

    assetOnlyFilters.forEach(function (filterName) {
      const control = STATE.root.querySelector('[data-filter="' + filterName + '"]');
      const field = control ? control.closest(".la-field") : null;
      const hiddenForChecks = checkPage && ["machinery_category", "department", "supplier", "status"].indexOf(filterName) !== -1;
      const hiddenForTechnicians = technicianPage && ["department", "supplier", "status"].indexOf(filterName) !== -1;
      const hiddenForTransfers = transferPage && ["department", "supplier", "status"].indexOf(filterName) !== -1;
      const hiddenForApprovals = approvalPage && ["department", "supplier", "status"].indexOf(filterName) !== -1;
      const permanentlyHidden = permanentlyHiddenFilters.indexOf(filterName) !== -1;
      if (field) field.style.display = permanentlyHidden || complaintPage || hiddenForChecks || hiddenForTechnicians || hiddenForTransfers || hiddenForApprovals ? "none" : "";
    });

    const searchControl = STATE.root.querySelector('[data-filter="search"]');
    const searchField = searchControl ? searchControl.closest(".la-field") : null;
    if (searchField) searchField.style.display = checkPage ? "none" : "";
    syncCheckDeskAssetSelector(checkPage);
    const searchLabel = searchField ? searchField.querySelector("span") : null;
    if (searchLabel) searchLabel.textContent = complaintPage ? "Search Complaint" : (technicianPage ? "Search Visit" : "Search Asset");
    if (searchControl) {
      if (complaintPage || technicianPage) {
        searchControl.removeAttribute("list");
      } else {
        searchControl.setAttribute("list", "life-asset-search-select-options");
      }
      searchControl.placeholder = complaintPage
        ? "Complaint ID, category, issue, branch, priority, status…"
        : technicianPage
          ? "Visit number, technician, asset, branch, task…"
          : "Select or search Asset ID, name or branch…";
    }

    const note = STATE.root.querySelector(".la-filter-note");
    if (note) {
      note.textContent = complaintPage
        ? "Filter Ticket Helpdesk asset complaints by date, permitted branch and search."
        : checkPage
          ? "Check visible Assets by date, permitted branch, Asset Category and selected Asset."
        : technicianPage
          ? "Filter real Technicians And Visits records by date, permitted branch, asset category and search."
          : "One filter drives assets, checks, complaints, technician visits, transfers, approvals, Machine 360, reports, labels and control views. LIFE business month runs from the 6th to the 5th.";
    }

    // Removed controls must never silently filter any dashboard page.
    permanentlyHiddenFilters.forEach(function (filterName) {
      STATE.filters[filterName] = "";
      setFilterControl(filterName, "");
    });

    // Check Desk additionally replaces Machinery Category and Search with its
    // branch-visible Asset selector.
    if (checkPage) {
      ["machinery_category", "search"].forEach(function (filterName) {
        STATE.filters[filterName] = "";
        setFilterControl(filterName, "");
      });
    }
  }

  function openPage(page) {
    if (!pageBody(page)) return;

    const previousPage = STATE.currentPage;
    saveCurrentPageDateFilters();
    STATE.currentPage = page;
    restoreDateFiltersForPage(page);

    // A branch name clicked in Command Centre is a temporary drill-down for
    // Asset Register. Returning to Command Centre removes only that temporary
    // filter. A login-locked branch is restored and can never be cleared.
    let clearedBranchDrilldown = false;
    if (page === "dashboard" && STATE.branchDrilldownActive) {
      STATE.branchDrilldownActive = false;
      STATE.filters.location = lockedBranchValue();
      setFilterControl("location", STATE.filters.location);
      clearedBranchDrilldown = true;
    }

    STATE.root.querySelectorAll("[data-page-panel]").forEach(function (panel) {
      panel.classList.toggle("is-active", panel.dataset.pagePanel === page);
    });

    STATE.root.querySelectorAll("[data-page]").forEach(function (button) {
      button.classList.toggle("is-active", button.dataset.page === page);
    });

    syncMasterFiltersForPage(page);
    renderActiveFilters();

    // Large audit/history tables are page-specific. Fetch them only when a
    // user opens a view that needs them, instead of slowing every login.
    if (page === "asset360" || page === "reports") {
      loadDeferredDashboardSources();
    }
    if (page === "movements") {
      ensureSourceMachineryAssets().then(function () {
        if (STATE.currentPage === "movements") applyFiltersAndRender();
      }).catch(function () {
        // The normal permitted transfer register remains available.
      });
    }

    const sidebar = STATE.root.querySelector("[data-sidebar]");
    if (sidebar && window.matchMedia("(max-width: 820px)").matches) {
      sidebar.classList.remove("is-mobile-open");
    }

    if (clearedBranchDrilldown || page === "movements" || previousPage === "movements" || page === "checks" || previousPage === "checks" || page === "maintenance" || previousPage === "maintenance") {
      applyFiltersAndRender();
    } else {
      renderCurrentPage();
    }
    renderFavoriteMenus();

    const top = STATE.root.getBoundingClientRect().top + window.scrollY;
    window.scrollTo({ top: Math.max(0, top), behavior: "smooth" });
  }

  function getDashboardDeepLink() {
    let params;
    try {
      params = new URLSearchParams(window.location.search || "");
    } catch (error) {
      return { page: "", request: "" };
    }

    let requestedPage = String(params.get("open") || params.get("page") || "").trim().toLowerCase();
    const requestName = String(params.get("request") || params.get("request_name") || "").trim();
    if (["approval", "approval-desk", "approvals-desk"].indexOf(requestedPage) !== -1) requestedPage = "approvals";
    if (requestName && !requestedPage) requestedPage = "approvals";
    return { page: requestedPage, request: requestName };
  }

  function applyDashboardDeepLink() {
    if (!STATE.root || STATE.root.dataset.deepLinkHandled === "1") return;
    const deepLink = getDashboardDeepLink();
    if (deepLink.page !== "approvals" && !deepLink.request) return;
    STATE.root.dataset.deepLinkHandled = "1";

    openPage("approvals");
    if (deepLink.request) {
      window.setTimeout(function () {
        openMachineryRequestDetail(deepLink.request);
      }, 120);
    }
  }

  function renderCurrentPage() {
    switch (STATE.currentPage) {
      case "dashboard": renderDashboard(); break;
      case "register": renderRegister(); break;
      case "checks": scheduleCheckDeskRender(); break;
      case "maintenance": renderMaintenance(); break;
      case "repairs": renderRepairs(); break;
      case "movements": renderMovements(); break;
      case "depreciation": renderDepreciation(); break;
      case "asset360": renderAsset360(); break;
      case "reports": renderReports(); break;
      case "approvals": renderApprovals(); break;
      case "labels": renderLabels(); break;
      case "masters": renderMasters(); break;
      default: renderDashboard(); break;
    }
  }

  function pageBody(page) {
    return STATE.root.querySelector('[data-page-body="' + page + '"]');
  }

  function scheduleCheckDeskRender() {
    const body = pageBody("checks");
    if (!body) return;

    if (STATE.checkRenderFrame && typeof window.cancelAnimationFrame === "function") {
      window.cancelAnimationFrame(STATE.checkRenderFrame);
    }

    body.innerHTML = '<div class="la-empty-state"><div><div class="la-empty-icon">⌛</div><div class="la-empty-title">Opening Check Desk…</div><div class="la-empty-note">Preparing the permitted Asset check position.</div></div></div>';

    const run = function () {
      STATE.checkRenderFrame = 0;
      if (STATE.currentPage === "checks") renderCheckDesk();
    };

    if (typeof window.requestAnimationFrame === "function") {
      STATE.checkRenderFrame = window.requestAnimationFrame(run);
    } else {
      window.setTimeout(run, 0);
    }
  }

  function renderDashboard() {
    const body = pageBody("dashboard");
    if (!body) return;

    const assets = STATE.filtered.assets;
    const totalUnits = sumAssetUnits(assets);
    const workingAssets = assets.filter(isOperationalAsset);
    const maintenanceAssets = assets.filter(function (asset) { return asset.status === "In Maintenance"; });
    const downAssets = assets.filter(function (asset) { return asset.status === "Out of Order"; });
    const retiredAssets = assets.filter(isRetiredAsset);
    const workingUnits = sumAssetUnits(workingAssets);
    const maintenanceUnits = sumAssetUnits(maintenanceAssets);
    const downUnits = sumAssetUnits(downAssets);
    const retiredUnits = sumAssetUnits(retiredAssets);
    const totalCost = sum(assets, getAssetCost);
    const bookValue = sum(assets, getAssetBookValue);
    const locations = uniqueSorted(assets.map(function (asset) { return getLifeBranchName(asset.location); }));
    const itemTypes = uniqueSorted(assets.map(function (asset) { return asset.item_code || asset.item_name; }));
    const insuranceAlerts = getInsuranceAlerts(assets, 60);
    const depreciationDue = getDepreciationDueAssets();
    const issues = sourceAvailable("issues") ? STATE.filtered.issues : [];
    const openIssues = issues.filter(function (issue) {
      return ["Resolved", "Closed"].indexOf(issue.status || "") === -1;
    });
    const failedSlaIssues = issues.filter(function (issue) {
      return normalize(issue.agreement_status) === "failed";
    });
    const pastUsefulLife = assets.filter(function (asset) {
      return !isRetiredAsset(asset) && (asset.status === "Fully Depreciated" || (getAssetCost(asset) > 0 && getAssetBookValue(asset) <= 0));
    });

    const buckets = ["Machinery", "Electronics", "Vehicles", "Furniture"].map(function (name) {
      const rows = assets.filter(function (asset) { return assetCommandBucket(asset) === name; });
      return {
        name: name,
        rows: rows,
        units: sumAssetUnits(rows),
        working: sumAssetUnits(rows.filter(isOperationalAsset)),
        down: sumAssetUnits(rows.filter(function (asset) { return asset.status === "Out of Order"; })),
        value: sum(rows, getAssetBookValue)
      };
    });

    const statusRows = buildCommandStatusRows(assets);
    const locationRows = buildCommandLocationRows(assets);
    const departmentRows = buildCommandDepartmentRows(assets);
    const ageRows = buildCommandAgeRows(assets);
    const attentionRows = buildCommandAttentionRows(assets);
    const movementValue = sourceAvailable("machineryTransfers")
      ? formatNumber(STATE.filtered.machineryTransfers.length)
      : (sourceAvailable("movements") ? formatNumber(STATE.filtered.movements.length) : "—");
    const activityValue = sourceAvailable("activities") ? formatNumber(STATE.filtered.activities.length) : "—";
    STATE.exportData = {
      title: "Asset Command Centre - Location Summary",
      columns: ["Location", "Units", "Working", "Down", "Availability %", "Gross Value", "Book Value"],
      rows: locationRows.map(function (row) {
        return [row.location, row.units, row.working, row.down, row.availability, row.cost, row.bookValue];
      })
    };

    body.innerHTML = [
      '<div class="la-command-hero">',
        '<div><div class="la-command-kicker">👤 ' + escapeHtml(getCurrentUserDisplay()) + '</div>',
        '<h2>Asset Command Centre</h2>',
        '<p>Machinery, electronics, vehicles and furniture across all locations visible to the logged-in ERPNext user.</p></div>',
      '</div>',

      '<div class="la-command-strip">',
        commandStripHtml("Fleet", totalUnits, locations.length + " locations"),
        commandStripHtml(
          "Transfers in cycle",
          movementValue,
          sourceAvailable("machineryTransfers")
            ? "Machinery Transfer documents"
            : (sourceAvailable("movements") ? "Asset Movement documents" : "No confirmed read access")
        ),
        commandStripHtml("Machines down", downUnits, "Status = Out of Order"),
        commandStripHtml("Insurance ≤ 60 days", insuranceAlerts.length, "Expired and expiring"),
        commandStripHtml("Past useful life", sumAssetUnits(pastUsefulLife), "Fully depreciated, not disposed"),
        commandStripHtml("Open complaints", sourceAvailable("issues") ? formatNumber(openIssues.length) : "—", sourceAvailable("issues") ? formatNumber(failedSlaIssues.length) + " SLA failed · live Issue records" : "No confirmed Issue read access"),
      '</div>',

      '<div class="la-category-command-grid">',
        commandCategoryHtml("🗂️", "All Assets", totalUnits, workingUnits, downUnits, bookValue, "all"),
        buckets.map(function (row) {
          const icon = row.name === "Machinery" ? "⚙️" : row.name === "Electronics" ? "💻" : row.name === "Vehicles" ? "🚗" : "🪑";
          return commandCategoryHtml(icon, row.name, row.units, row.working, row.down, row.value, row.name.toLowerCase());
        }).join(""),
      '</div>',

      '<div class="la-command-kpi-grid">',
        kpiHtml("Total asset units", formatNumber(totalUnits), formatNumber(itemTypes.length) + " item types", "▤", "info"),
        kpiHtml("Working now", formatNumber(workingUnits), percentage(workingUnits, totalUnits) + "% availability", "✓", "ok"),
        kpiHtml("Not working", formatNumber(downUnits), "Across " + formatNumber(countDistinctLocations(downAssets)) + " location(s)", "!", "bad"),
        kpiHtml("In maintenance", formatNumber(maintenanceUnits), "Current Asset status", "⚒", "warn"),
        kpiHtml("Gross asset value", formatAmount(totalCost), "Visible Asset records", "₹", "gold"),
        kpiHtml("Current book value", formatAmount(bookValue), formatAmount(Math.max(0, totalCost - bookValue)) + " depreciation", "₹", "purple"),
        clickableKpiHtml("Open complaints", sourceAvailable("issues") ? formatNumber(openIssues.length) : "—", sourceAvailable("issues") ? formatNumber(failedSlaIssues.length) + " SLA failed" : "Issue source unavailable", "🚨", failedSlaIssues.length ? "bad" : (openIssues.length ? "warn" : "ok"), "repairs"),
        kpiHtml("Depreciation due", formatNumber(depreciationDue.length), "Next depreciation date reached", "↓", depreciationDue.length ? "warn" : "ok"),
        commandStatusHtml("Working", workingUnits, totalUnits, sum(workingAssets, getAssetBookValue), "ok"),
        commandStatusHtml("In Maintenance", maintenanceUnits, totalUnits, sum(maintenanceAssets, getAssetBookValue), "warn"),
        commandStatusHtml("Out of Order", downUnits, totalUnits, sum(downAssets, getAssetBookValue), "bad"),
        commandStatusHtml("Sold / Scrapped", retiredUnits, totalUnits, sum(retiredAssets, getAssetBookValue), "muted"),
      '</div>',

      '<div class="la-grid la-command-tables-stack" style="margin-top:13px">',
        renderDataTable("command-status", "ERPNext Asset Status Position", [
          { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } },
          { key: "units", label: "Units", type: "number" },
          { key: "share", label: "Share", type: "number", render: function (row) { return row.share + "%"; } },
          { key: "locations", label: "Locations", type: "number" },
          { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } }
        ], statusRows, { pageSize: 12 }),
        renderDataTable("command-locations", "Branch / Location Position", [
          {
            key: "location",
            label: "Branch / Location",
            render: function (row) {
              return '<span class="la-branch-link">' +
                escapeHtml(row.location) +
              '</span>';
            }
          },
          { key: "units", label: "Units", type: "number" },
          { key: "working", label: "Working", type: "number" },
          { key: "down", label: "Down", type: "number" },
          { key: "availability", label: "Availability", type: "number", render: function (row) { return row.availability + "%"; } },
          { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } }
        ], locationRows, {
          pageSize: 12,
          rowAction: "open-branch-assets",
          rowDataKey: "location",
          rowDataAttribute: "branch-name",
          rowClass: "la-branch-row"
        }),
      '</div>',

      '<div style="margin-top:13px">',
        renderDataTable("command-attention", "Priority Attention", [
          { key: "priority", label: "Priority", render: function (row) { return badgeHtml(row.priority, row.tone); } },
          { key: "trigger", label: "Trigger" },
          { key: "asset", label: "Asset / Location", render: function (row) { return assetButton(row.asset, row.assetName) + '<span class="la-cell-sub">' + escapeHtml(getLifeBranchName(row.location)) + '</span>'; } },
          { key: "detail", label: "Detail" },
          { key: "action", label: "Action", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Asset" data-docname="' + escapeAttribute(row.asset) + '">Open Asset</button>'; } }
        ], attentionRows, { pageSize: 15 }),
      '</div>',

      '<div class="la-command-section-head"><div><h3>Department / Group Position</h3><p>Calculated from Asset.department. No complaint or session values are invented.</p></div></div>',
      '<div class="la-department-command-grid">',
        departmentRows.slice(0, 16).map(commandDepartmentHtml).join("") || emptyStateHtml("No department data", "Department is not populated in the visible Asset records."),
      '</div>',

      '<div style="margin-top:13px">',
        renderDataTable("command-age", "Asset Age Analysis", [
          { key: "band", label: "Age Band" },
          { key: "units", label: "Units", type: "number" },
          { key: "working", label: "Working", type: "number" },
          { key: "down", label: "Down", type: "number" },
          { key: "cost", label: "Original Cost", type: "number", render: function (row) { return formatAmount(row.cost); } },
          { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } }
        ], ageRows, { pageSize: 10 }),
      '</div>',

      '<div class="la-grid la-grid-2" style="margin-top:13px">',
        renderRecentActivityCard(),
        renderConfirmedSourceStatusCard(),
      '</div>'
    ].join("");
  }

  function assetUnitCount(asset) {
    const quantity = toNumber(asset && asset.asset_quantity);
    return quantity > 0 ? quantity : 1;
  }

  function sumAssetUnits(rows) {
    return (rows || []).reduce(function (total, row) { return total + assetUnitCount(row); }, 0);
  }

  function getCurrentUserDisplay() {
    const element = STATE.root && STATE.root.querySelector("[data-user-name]");
    return element && element.textContent ? element.textContent : (window.frappe && frappe.session ? frappe.session.user : "ERPNext User");
  }

  function assetCommandBucket(asset) {
    const text = normalize([asset.asset_category, asset.item_name, asset.item_code, asset.department].join(" "));
    if (/vehicle|car|bike|scooter|van|ambulance|four wheeler|two wheeler/.test(text)) return "Vehicles";
    if (/furniture|chair|table|desk|sofa|bed|stool|rack|locker|cupboard|cabinet|fixture|fitting|mirror/.test(text)) return "Furniture";
    if (/electronic|computer|laptop|desktop|printer|camera|cctv|router|network|ups|inverter|mobile|phone|tv|monitor|projector|ac |air conditioner|server/.test(text)) return "Electronics";
    return "Machinery";
  }

  function commandStripHtml(label, value, note) {
    return '<div class="la-command-strip-item"><span>' + escapeHtml(label) + '</span><b>' + escapeHtml(String(value)) + '</b><small>' + escapeHtml(note || "") + '</small></div>';
  }

  function commandCategoryHtml(icon, label, units, working, down, value, tone) {
    return '<div class="la-command-category la-command-category-' + escapeAttribute(tone) + '">' +
      '<div class="la-command-category-top"><span>' + icon + '</span><b>' + escapeHtml(label) + '</b></div>' +
      '<strong>' + formatNumber(units) + '</strong>' +
      '<p>' + formatNumber(working) + ' working · ' + formatNumber(down) + ' down</p>' +
      '<small>' + formatAmount(value) + ' book value</small>' +
      '</div>';
  }

  function commandStatusHtml(label, units, total, value, tone) {
    return '<div class="la-command-status la-command-status-' + escapeAttribute(tone) + '">' +
      '<span>' + escapeHtml(label) + '</span><b>' + formatNumber(units) + ' <em>(' + percentage(units, total) + '%)</em></b>' +
      '<small>' + formatAmount(value) + ' book value</small></div>';
  }

  function countDistinctLocations(rows) {
    return uniqueSorted((rows || []).map(function (row) { return getLifeBranchName(row.location); })).length;
  }

  function buildCommandStatusRows(assets) {
    const groups = groupBy(assets, function (asset) { return asset.status || "Not Set"; });
    const total = sumAssetUnits(assets);
    return Object.keys(groups).map(function (status) {
      const rows = groups[status];
      const units = sumAssetUnits(rows);
      return {
        status: status,
        units: units,
        share: percentage(units, total),
        locations: countDistinctLocations(rows),
        bookValue: sum(rows, getAssetBookValue)
      };
    }).sort(function (a, b) { return b.units - a.units; });
  }

  function buildCommandLocationRows(assets) {
    const groups = groupBy(assets, function (asset) { return getLifeBranchName(asset.location); });
    return Object.keys(groups).map(function (location) {
      const rows = groups[location];
      const units = sumAssetUnits(rows);
      const working = sumAssetUnits(rows.filter(isOperationalAsset));
      const down = sumAssetUnits(rows.filter(function (asset) { return asset.status === "Out of Order"; }));
      return {
        location: location,
        units: units,
        working: working,
        down: down,
        availability: percentage(working, units),
        cost: sum(rows, getAssetCost),
        bookValue: sum(rows, getAssetBookValue)
      };
    }).sort(function (a, b) { return b.units - a.units; });
  }

  function buildCommandDepartmentRows(assets) {
    const groups = groupBy(assets, function (asset) { return asset.department || "Unassigned Department"; });
    return Object.keys(groups).map(function (department) {
      const rows = groups[department];
      return {
        department: department,
        units: sumAssetUnits(rows),
        working: sumAssetUnits(rows.filter(isOperationalAsset)),
        down: sumAssetUnits(rows.filter(function (asset) { return asset.status === "Out of Order"; })),
        value: sum(rows, getAssetBookValue)
      };
    }).sort(function (a, b) { return b.units - a.units; });
  }

  function commandDepartmentHtml(row) {
    const icon = /skin/i.test(row.department) ? "✦" : /slim/i.test(row.department) ? "⚖" : /hair/i.test(row.department) ? "✂" : /physio/i.test(row.department) ? "❦" : /it|computer|network/i.test(row.department) ? "💻" : "⚙";
    return '<div class="la-department-command-card"><div><span>' + icon + '</span><b>' + escapeHtml(row.department) + '</b></div>' +
      '<strong>' + formatNumber(row.units) + '</strong><p>' + formatNumber(row.working) + ' working · ' + formatNumber(row.down) + ' down</p>' +
      '<small>' + formatAmount(row.value) + ' book value</small></div>';
  }

  function buildCommandAgeRows(assets) {
    const bands = [
      { band: "Under 1 year", min: 0, max: 12 },
      { band: "1 – 3 years", min: 12, max: 36 },
      { band: "3 – 5 years", min: 36, max: 60 },
      { band: "5 – 7 years", min: 60, max: 84 },
      { band: "Over 7 years", min: 84, max: Infinity },
      { band: "Date not available", min: -1, max: -1 }
    ];
    return bands.map(function (band) {
      const rows = assets.filter(function (asset) {
        const months = ageInMonths(asset.available_for_use_date || asset.purchase_date);
        if (band.min === -1) return months == null || months < 0;
        return months >= band.min && months < band.max;
      });
      return {
        band: band.band,
        units: sumAssetUnits(rows),
        working: sumAssetUnits(rows.filter(isOperationalAsset)),
        down: sumAssetUnits(rows.filter(function (asset) { return asset.status === "Out of Order"; })),
        cost: sum(rows, getAssetCost),
        bookValue: sum(rows, getAssetBookValue)
      };
    }).filter(function (row) { return row.units > 0; });
  }

  function buildCommandAttentionRows(assets) {
    const rows = [];
    assets.forEach(function (asset) {
      const assetName = asset.asset_name || asset.item_name || asset.name;
      if (asset.status === "Out of Order") {
        rows.push({ priority: "Urgent", tone: "bad", trigger: "Asset down", asset: asset.name, assetName: assetName, location: getLifeBranchName(asset.location), detail: "ERPNext status is Out of Order", action: "Open" });
      }
      if (asset.insurance_end_date) {
        const days = daysFromToday(asset.insurance_end_date);
        if (days != null && days <= 60) {
          rows.push({ priority: days < 0 ? "Urgent" : "High", tone: days < 0 ? "bad" : "warn", trigger: days < 0 ? "Insurance expired" : "Insurance expiring", asset: asset.name, assetName: assetName, location: getLifeBranchName(asset.location), detail: formatDate(asset.insurance_end_date) + (days < 0 ? " · expired" : " · " + days + " day(s) remaining"), action: "Open" });
        }
      }
      if (asset.next_depreciation_date && isDatePastOrToday(asset.next_depreciation_date)) {
        rows.push({ priority: "Medium", tone: "gold", trigger: "Depreciation due", asset: asset.name, assetName: assetName, location: getLifeBranchName(asset.location), detail: "Next depreciation date: " + formatDate(asset.next_depreciation_date), action: "Open" });
      }
    });
    const rank = { Urgent: 1, High: 2, Medium: 3 };
    return rows.sort(function (a, b) { return (rank[a.priority] || 9) - (rank[b.priority] || 9); }).slice(0, 100);
  }

  function daysFromToday(value) {
    const date = parseDate(value);
    if (!date) return null;
    return Math.ceil((startOfDay(date) - startOfDay(new Date())) / 86400000);
  }

