  function getAllProductionChecks() {
    const assetMap = indexBy(getProductionAssets(), "name");
    return (STATE.data.checks || []).filter(function (row) {
      const asset = row.asset ? assetMap[row.asset] : null;
      const location = getLifeBranchName(row.location || (asset ? asset.location : ""));
      return !isTestingBranchName(location);
    });
  }

  function getChecksForAsset(assetName, filteredOnly) {
    const rows = filteredOnly ? (STATE.filtered.checks || []) : getAllProductionChecks();
    return rows.filter(function (row) { return row.asset === assetName; }).sort(function (a, b) {
      return compareValues(
        String(b.check_date || b.creation || b.modified || "") + " " + String(b.check_time || ""),
        String(a.check_date || a.creation || a.modified || "") + " " + String(a.check_time || "")
      );
    });
  }

  function latestCheckForAsset(assetName) {
    const rows = getChecksForAsset(assetName, false);
    return rows.length ? rows[0] : null;
  }

  function checkPositionFromLatest(latest) {
    if (!latest) {
      return { label: "Never Checked", tone: "warn", rank: 1, latest: null };
    }

    const next = parseDate(latest.next_check_date);
    const today = startOfDay(new Date());
    if (next) {
      const nextDay = startOfDay(next);
      if (nextDay < today) return { label: "Overdue", tone: "bad", rank: 0, latest: latest };
      if (nextDay.getTime() === today.getTime()) return { label: "Due Today", tone: "warn", rank: 1, latest: latest };
      return { label: "Next " + formatDate(latest.next_check_date), tone: "ok", rank: 3, latest: latest };
    }

    const result = String(latest.overall_result || "").toLowerCase();
    if (result === "fail" || result.indexOf("attention") !== -1) {
      return { label: latest.overall_result || "Attention", tone: "bad", rank: 0, latest: latest };
    }

    return { label: "Checked", tone: "ok", rank: 2, latest: latest };
  }

  function checkPositionForAsset(asset) {
    return checkPositionFromLatest(latestCheckForAsset(asset.name));
  }

  function renderCheckDesk() {
    const body = pageBody("checks");
    if (!body) return;

    const checkHistoryUnavailable = !sourceAvailable("checks");

    const assets = (STATE.filtered.assets || []).slice();
    const checks = STATE.filtered.checks || [];
    const allChecksByAsset = groupBy(getAllProductionChecks(), function (row) {
      return row.asset || "";
    });

    Object.keys(allChecksByAsset).forEach(function (assetName) {
      allChecksByAsset[assetName].sort(function (a, b) {
        return compareValues(
          String(b.check_date || b.creation || b.modified || "") + " " + String(b.check_time || ""),
          String(a.check_date || a.creation || a.modified || "") + " " + String(a.check_time || "")
        );
      });
    });

    if (!STATE.checkAssetName || !assets.some(function (asset) { return asset.name === STATE.checkAssetName; })) {
      STATE.checkAssetName = assets.length ? assets[0].name : "";
    }
    syncCheckDeskAssetSelector(true, assets);

    const positions = assets.map(function (asset) {
      const history = allChecksByAsset[asset.name] || [];
      const position = checkPositionFromLatest(history.length ? history[0] : null);
      return { asset: asset, position: position };
    }).sort(function (a, b) {
      if (a.position.rank !== b.position.rank) return a.position.rank - b.position.rank;
      return String(a.asset.asset_name || a.asset.item_name || a.asset.name).localeCompare(
        String(b.asset.asset_name || b.asset.item_name || b.asset.name),
        undefined,
        { numeric: true, sensitivity: "base" }
      );
    });

    const overdue = positions.filter(function (row) { return row.position.label === "Overdue"; }).length;
    const neverChecked = positions.filter(function (row) { return !row.position.latest; }).length;
    const failed = checks.filter(function (row) {
      const value = String(row.overall_result || "").toLowerCase();
      return value === "fail" || value.indexOf("attention") !== -1;
    }).length;

    const selectedAsset = assets.find(function (asset) { return asset.name === STATE.checkAssetName; }) || null;

    STATE.exportData = {
      title: "LIFE Asset Check Desk",
      columns: ["Check ID", "Asset", "Asset Name", "Location", "Check Date", "Check Type", "Checked By", "Result", "Machine Condition", "Next Check Date", "Linked Complaint", "Remark"],
      rows: checks.map(function (row) {
        return [row.name, row.asset, row.asset_name, getLifeBranchName(row.location), row.check_date, row.check_type, row.checked_by, row.overall_result, row.machine_condition, row.next_check_date, row.linked_complaint, row.overall_remark];
      })
    };

    const leftRows = positions.length ? positions.map(function (entry) {
      const asset = entry.asset;
      const latest = entry.position.latest;
      const selected = asset.name === STATE.checkAssetName;
      return [
        '<button type="button" class="la-check-asset', selected ? ' is-selected' : '', '" data-action="select-check-asset" data-asset-name="', escapeAttribute(asset.name), '">',
          '<span><b>', escapeHtml(asset.name), '</b><small>', escapeHtml(asset.asset_name || asset.item_name || "Unnamed Asset"), ' · ', escapeHtml(getLifeBranchName(asset.location) || "No location"), '</small>',
          latest ? '<small>Last: ' + escapeHtml(formatDate(latest.check_date || latest.creation)) + ' · ' + escapeHtml(latest.overall_result || "No result") + '</small>' : '<small>No LIFE Asset Check record yet</small>',
          '</span>',
          badgeHtml(entry.position.label, entry.position.tone),
        '</button>'
      ].join("");
    }).join("") : '<div class="la-check-empty">No Asset records match the current master filters.</div>';

    let rightHtml = '<div class="la-check-empty">Select an Asset to view its check position.</div>';

    if (selectedAsset) {
      const history = allChecksByAsset[selectedAsset.name] || [];
      const latest = history.length ? history[0] : null;
      const selectedPosition = checkPositionFromLatest(latest);
      const historyRows = history.map(function (row) {
        return {
          name: row.name,
          check_date: row.check_date || row.creation,
          type: row.check_type || "—",
          result: row.overall_result || "—",
          condition: row.machine_condition || "—",
          checked_by: row.checked_by || "—",
          next: row.next_check_date || "",
          complaint: row.linked_complaint || "",
          remark: row.overall_remark || ""
        };
      });

      const historyColumns = [
        { key: "check_date", label: "Date", type: "date" },
        { key: "type", label: "Check Type" },
        { key: "result", label: "Result", render: function (row) { return badgeHtml(row.result, checkResultTone(row.result)); } },
        { key: "condition", label: "Machine Condition" },
        { key: "checked_by", label: "Checked By" },
        { key: "next", label: "Next Check", type: "date" },
        { key: "complaint", label: "Complaint", render: function (row) { return row.complaint ? '<button type="button" class="la-button la-button-small" data-action="open-complaint-detail" data-complaint-name="' + escapeAttribute(row.complaint) + '">' + escapeHtml(row.complaint) + '</button>' : "—"; } },
        { key: "remark", label: "Remark", render: clampCell("remark") },
        { key: "open", label: "Open", render: function (row) { return '<button type="button" class="la-button la-button-small la-button-primary" data-doctype="LIFE Asset Check" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
      ];

      rightHtml = [
        '<div class="la-check-work-body">',
          '<div class="la-check-summary">',
            '<div class="la-check-mini"><small>Asset</small><b>', escapeHtml(selectedAsset.name), '</b></div>',
            '<div class="la-check-mini"><small>Location</small><b>', escapeHtml(getLifeBranchName(selectedAsset.location) || "—"), '</b></div>',
            '<div class="la-check-mini"><small>Check Position</small><b>', escapeHtml(selectedPosition.label), '</b></div>',
            '<div class="la-check-mini"><small>Check Records</small><b>', formatNumber(history.length), '</b></div>',
          '</div>',
          detailGridHtml([
            ["Asset Name", selectedAsset.asset_name || selectedAsset.item_name || "—"],
            ["Asset Category", selectedAsset.asset_category || "—"],
            ["Machinery Category", selectedAsset.custom_machinery_assets_category || "—"],
            ["Asset Status", selectedAsset.status || "—"],
            ["Last Check", latest ? formatDate(latest.check_date || latest.creation) : "Never"],
            ["Last Result", latest ? (latest.overall_result || "—") : "—"],
            ["Machine Condition", latest ? (latest.machine_condition || "—") : "—"],
            ["Next Check", latest ? formatDate(latest.next_check_date) : "—"]
          ]),
          '<div class="la-check-actions">',
            '<button type="button" class="la-button la-button-primary" data-action="new-asset-check" data-asset-name="', escapeAttribute(selectedAsset.name), '">＋ Start New Check</button>',
            '<button type="button" class="la-button" data-action="show-asset" data-asset-name="', escapeAttribute(selectedAsset.name), '">Open Asset</button>',
            '<button type="button" class="la-button la-button-light" data-action="open-check-list">Open Check List</button>',
            '<button type="button" class="la-button la-button-gold" data-action="export">⇩ Export Checks</button>',
          '</div>',
          '<div class="la-check-note">Select <b>Start New Check</b>, mark every point <b>Pass</b> or <b>Fail</b>, add remarks for failed points, and save directly from this dashboard.</div>',
          '<div style="margin-top:13px">',
            renderDataTable("asset-check-history", "Real Check History — " + selectedAsset.name, historyColumns, historyRows, {
              pageSize: 10,
              rowAction: "open-check-detail",
              rowDataKey: "name",
              rowDataAttribute: "check-name",
              rowClass: "la-popup-row"
            }),
          '</div>',
        '</div>'
      ].join("");
    }

    body.innerHTML = [
      checkHistoryUnavailable
        ? noticeHtml("Check history is restricted", "Historical LIFE Asset Check records are not readable for this role. You can still select a visible Asset and use Start New Check when Create permission is assigned.", "warn")
        : "",
      '<div class="la-grid la-grid-4" style="margin-bottom:13px">',
        kpiHtml("Assets in scope", formatNumber(assets.length), "Testing Branch excluded", "🏷️", "info"),
        kpiHtml("Checks in period", formatNumber(checks.length), "LIFE Asset Check records", "✅", "ok"),
        kpiHtml("Overdue", formatNumber(overdue), neverChecked + " never checked", "⌛", overdue ? "bad" : "ok"),
        kpiHtml("Failed / Attention", formatNumber(failed), "Current filtered period", "!", failed ? "warn" : "ok"),
      '</div>',
      '<div class="la-check-desk">',
        '<div class="la-check-list">',
          '<div class="la-check-head"><h3>Assets to Check</h3><span>', formatNumber(positions.length), ' asset(s)</span></div>',
          '<div class="la-check-scroll">', leftRows, '</div>',
        '</div>',
        '<div class="la-check-work">',
          '<div class="la-check-head"><h3>Asset Check</h3><span>', selectedAsset ? escapeHtml(selectedAsset.asset_name || selectedAsset.item_name || selectedAsset.name) : "", '</span></div>',
          rightHtml,
        '</div>',
      '</div>'
    ].join("");
  }

  function checkResultTone(value) {
    const text = String(value || "").toLowerCase();
    if (text === "fail") return "bad";
    if (text.indexOf("attention") !== -1) return "warn";
    if (text === "pass") return "ok";
    return "info";
  }

  function openNewAssetCheck(assetName) {
    const asset = getProductionAssets().find(function (row) { return row.name === assetName; });
    if (!asset) {
      showToast("Select an Asset before starting the check.", true);
      return;
    }

    const category = String(asset.asset_category || "Machinery").trim();
    const schedule = inlineCheckSchedule(category);
    const points = inlineChecklistForAsset(asset);
    const today = toIsoDate(new Date());
    const nextDate = addDaysIso(today, schedule.days);
    const rows = points.map(function (point, index) {
      return [
        '<div class="la-inline-check-row" data-inline-check-row data-index="', index, '">',
          '<div>', index + 1, '</div>',
          '<div><b>', escapeHtml(point), '</b></div>',
          '<div class="la-inline-result">',
            '<button type="button" class="la-result-button" data-action="set-check-result" data-result="Pass">Pass</button>',
            '<button type="button" class="la-result-button" data-action="set-check-result" data-result="Fail">Fail</button>',
          '</div>',
          '<input class="la-inline-remark" data-check-remark placeholder="Remark (required when Fail)">',
        '</div>'
      ].join("");
    }).join("");

    const html = [
      '<div class="la-inline-check la-check-pad" data-inline-check data-asset="', escapeAttribute(asset.name), '">',
        '<div class="la-check-pad-header">',
          '<div class="la-check-pad-logo">L</div>',
          '<div class="la-check-pad-title"><b>LIFE Asset Inspection Pad</b><small>Machinery safety and condition checklist</small></div>',
          '<div class="la-check-pad-ref"><b>Asset:</b> ', escapeHtml(asset.name), '<br><b>Frequency:</b> ', escapeHtml(schedule.type), '</div>',
        '</div>',
        '<div class="la-check-pad-section">Asset Identification</div>',
        '<div class="la-inline-check-info">',
          inlineCheckField("Asset", asset.name),
          inlineCheckField("Asset Name", asset.asset_name || asset.item_name || "—"),
          inlineCheckField("Branch / Location", getLifeBranchName(asset.location) || asset.location || "—"),
          inlineCheckField("Category", category),
        '</div>',
        '<div class="la-check-pad-section">Inspection Information</div>',
        '<div class="la-inline-check-info la-check-inspection-info">',
          '<div class="la-inline-field"><label>Check Date</label><input type="date" data-check-date value="', escapeAttribute(today), '"></div>',
          '<div class="la-inline-field"><label>Check Time</label><input type="time" step="1" data-check-time value="', escapeAttribute(currentTimeValue()), '"></div>',
          '<div class="la-inline-field"><label>Check Type</label><select data-check-type><option', schedule.type === "Weekly" ? ' selected' : '', '>Weekly</option><option', schedule.type === "Monthly" ? ' selected' : '', '>Monthly</option><option', schedule.type === "Quarterly" ? ' selected' : '', '>Quarterly</option></select></div>',
          '<div class="la-inline-field"><label>Machine Condition</label><select data-machine-condition><option>Working</option><option>Partially Working</option><option>Not Working</option></select></div>',
          '<div class="la-inline-field"><label>Next Check Date</label><input type="date" data-next-check-date value="', escapeAttribute(nextDate), '"></div>',
        '</div>',
        '<div class="la-check-pad-section">Pass / Fail Inspection Checklist</div>',
        '<div class="la-inline-check-table">',
          '<div class="la-inline-check-row is-head"><div>No.</div><div>Check Point</div><div>Result</div><div>Remark</div></div>',
          rows,
        '</div>',
        '<div class="la-check-pad-section">Photographs &amp; Video</div>',
        '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin:10px 0 14px">',
          '<label style="min-height:132px;border:2px dashed #b8c9bd;border-radius:12px;background:#f8fcf7;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:7px;cursor:pointer;text-align:center;padding:12px">',
            '<span style="font-size:26px">📷</span><b>Add Photo</b><small style="color:#69768b">Camera or gallery · multiple allowed</small>',
            '<input type="file" multiple data-check-photo style="display:none">',
          '</label>',
          '<label style="min-height:132px;border:2px dashed #b8c9bd;border-radius:12px;background:#f8fcf7;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:7px;cursor:pointer;text-align:center;padding:12px">',
            '<span style="font-size:26px">🎬</span><b>Add Video</b><small style="color:#69768b">Record or choose a video</small>',
            '<input type="file" data-check-video style="display:none">',
          '</label>',
        '</div>',
        '<div data-check-media-preview style="display:none;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:0 0 14px"></div>',
        '<small style="display:block;color:#69768b;margin:-5px 0 14px">Photos and video are saved as private attachments on this Asset Check.</small>',
        '<div class="la-inline-field"><label>Overall Remark</label><textarea rows="2" data-overall-remark placeholder="Optional overall remark"></textarea></div>',
        '<div class="la-check-pad-signoff">',
          '<div><small>Checked By</small><b>', escapeHtml(getCurrentUserId()), '</b></div>',
          '<div><small>Inspection Date</small><b>', escapeHtml(formatDate(today)), '</b></div>',
          '<div><small>Final Result</small><b>Calculated from Pass / Fail entries</b></div>',
        '</div>',
      '</div>'
    ].join("");

    openModal(
      "Start New Check · " + asset.name,
      html,
      '<button type="button" class="la-button" data-action="close-modal">Cancel</button>' +
      '<button type="button" class="la-button la-button-primary" data-action="save-inline-check">Save Check</button>'
    );

    const checkForm = STATE.root.querySelector("[data-inline-check]");
    if (checkForm) {
      const photoInput = checkForm.querySelector("[data-check-photo]");
      const videoInput = checkForm.querySelector("[data-check-video]");
      [{ input: photoInput, kind: "photo" }, { input: videoInput, kind: "video" }].forEach(function (entry) {
        if (!entry.input) return;
        entry.input.addEventListener("change", function () {
          const invalid = Array.from(entry.input.files || []).find(function (file) {
            return !isValidCheckMediaFile(file, entry.kind);
          });
          if (invalid) {
            entry.input.value = "";
            showToast(
              entry.kind === "photo"
                ? "Please select an image file: JPG, JPEG, PNG, GIF, WEBP, BMP or SVG."
                : "Please select a video file: MP4, WEBM, OGG, MOV or M4V.",
              true
            );
          }
          renderCheckMediaPreview(checkForm);
        });
      });
    }
  }

  function isValidCheckMediaFile(file, kind) {
    if (!file) return false;
    const name = String(file.name || "").toLowerCase();
    const type = String(file.type || "").toLowerCase();
    if (kind === "photo") {
      return type.indexOf("image/") === 0 || /\.(jpg|jpeg|png|gif|webp|bmp|svg)$/.test(name);
    }
    return type.indexOf("video/") === 0 || /\.(mp4|webm|ogg|mov|m4v)$/.test(name);
  }

  function renderCheckMediaPreview(form) {
    const preview = form && form.querySelector("[data-check-media-preview]");
    if (!preview) return;
    const photoInput = form.querySelector("[data-check-photo]");
    const videoInput = form.querySelector("[data-check-video]");
    const files = [];
    Array.from(photoInput && photoInput.files ? photoInput.files : []).forEach(function (file) { files.push({ file: file, type: "photo" }); });
    Array.from(videoInput && videoInput.files ? videoInput.files : []).forEach(function (file) { files.push({ file: file, type: "video" }); });
    preview.style.display = files.length ? "grid" : "none";
    preview.innerHTML = files.map(function (entry) {
      const url = URL.createObjectURL(entry.file);
      const media = entry.type === "photo"
        ? '<img src="' + escapeAttribute(url) + '" alt="Selected inspection photo" style="width:100%;height:92px;object-fit:cover;border-radius:8px">'
        : '<video src="' + escapeAttribute(url) + '" muted playsinline style="width:100%;height:92px;object-fit:cover;border-radius:8px;background:#18211b"></video>';
      return '<div style="border:1px solid #d9e2dc;border-radius:10px;padding:7px;background:#fff;overflow:hidden">' + media + '<small title="' + escapeAttribute(entry.file.name) + '" style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:5px">' + escapeHtml(entry.file.name) + '</small></div>';
    }).join("");
