  function inlineCheckSchedule(category) {
    const text = String(category || "").toLowerCase();
    if (text.indexOf("furniture") !== -1) return { type: "Quarterly", days: 90 };
    if (text.indexOf("electronic") !== -1) return { type: "Monthly", days: 30 };
    return { type: "Weekly", days: 7 };
  }

  function inlineChecklistForAsset(asset) {
    const category = String(asset.asset_category || "").toLowerCase();
    if (category.indexOf("furniture") !== -1) {
      return [
        "Structure is stable with no wobble, crack or broken joint",
        "Upholstery, laminate or polish is in acceptable condition",
        "Wheels, hinges, drawers and moving parts work correctly",
        "No rust, sharp edge, loose part or other safety risk",
        "Asset is clean and presentable",
        "Asset tag is intact and the item is in the correct location"
      ];
    }
    if (category.indexOf("electronic") !== -1) {
      return [
        "Item is physically present and asset tag is intact",
        "Power supply, cable, plug and adapter are safe",
        "Item powers on and completes its normal function",
        "Body, screen, controls and casing are free of damage",
        "Ports, accessories and connections are available and working",
        "Battery or power backup is working where applicable",
        "Item is clean, ventilated and safely positioned"
      ];
    }
    return [
      "Machine is physically present and asset tag is intact",
      "Machine powers on and self-test completes normally",
      "Body, panel, display and controls are free of damage",
      "Power cable, plug point and earthing are safe",
      "Handpieces, probes, pedals and accessories are available",
      "Safety controls and emergency stop work correctly",
      "Functional output is tested and working normally",
      "Calibration or preventive-maintenance status is valid",
