  function addDaysIso(isoDate, days) {
    const parts = String(isoDate || "").split("-").map(Number);
    const date = parts.length === 3 ? new Date(parts[0], parts[1] - 1, parts[2]) : new Date();
    date.setDate(date.getDate() + Number(days || 0));
    return toIsoDate(date);
  }

  function setInlineCheckResult(button) {
    const row = button && button.closest ? button.closest("[data-inline-check-row]") : null;
    if (!row) return;
    row.dataset.result = button.dataset.result || "";
    row.querySelectorAll(".la-result-button").forEach(function (item) {
      item.classList.toggle("is-selected", item === button);
    });
  }

  async function saveInlineAssetCheck(button) {
    const modal = STATE.root.querySelector("[data-inline-check]");
    if (!modal || (button && button.disabled)) return;
    const assetName = modal.dataset.asset || "";
    const asset = getProductionAssets().find(function (row) { return row.name === assetName; });
    if (!asset) {
      showToast("Asset record is no longer available. Refresh and try again.", true);
      return;
    }

    const itemRows = Array.from(modal.querySelectorAll("[data-inline-check-row]"));
    const missing = itemRows.filter(function (row) { return !row.dataset.result; });
    if (missing.length) {
      showToast("Choose Pass or Fail for every check point.", true);
      missing[0].scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }
    const failWithoutRemark = itemRows.find(function (row) {
      const remark = row.querySelector("[data-check-remark]");
      return row.dataset.result === "Fail" && !(remark && remark.value.trim());
    });
    if (failWithoutRemark) {
      showToast("Enter a remark for every failed check point.", true);
      const input = failWithoutRemark.querySelector("[data-check-remark]");
      if (input) input.focus();
      return;
    }

    const checkItems = itemRows.map(function (row) {
      const remark = row.querySelector("[data-check-remark]");
      const point = row.children[1] ? row.children[1].textContent.trim() : "Check point";
      return {
        doctype: "LIFE Asset Check Item",
        check_point: point,
        result: row.dataset.result,
        remark: remark ? remark.value.trim() : ""
      };
    });
    const overallResult = checkItems.some(function (row) { return row.result === "Fail"; }) ? "Fail" : "Pass";
    const photoInput = modal.querySelector("[data-check-photo]");
    const videoInput = modal.querySelector("[data-check-video]");
    const attachments = Array.from(photoInput && photoInput.files ? photoInput.files : []).concat(Array.from(videoInput && videoInput.files ? videoInput.files : []));
    const category = String(asset.asset_category || "Machinery");
    const doc = {
      doctype: "LIFE Asset Check",
      naming_series: "LAC-.YYYY.-.#####",
      asset: asset.name,
      asset_name: asset.asset_name || asset.item_name || "",
      location: asset.location || "",
      machinery_category: asset.custom_machinery_assets_category || "",
      machine_condition: modal.querySelector("[data-machine-condition]").value,
      check_date: modal.querySelector("[data-check-date]").value,
      check_time: modal.querySelector("[data-check-time]").value,
      check_type: modal.querySelector("[data-check-type]").value || inlineCheckSchedule(category).type,
      checked_by: getCurrentUserId(),
      overall_result: overallResult,
      next_check_date: modal.querySelector("[data-next-check-date]").value,
      overall_remark: modal.querySelector("[data-overall-remark]").value.trim(),
      check_items: checkItems
    };

    if (button) {
      button.disabled = true;
      button.textContent = "Saving…";
    }
    try {
      const saved = await frappeCall("frappe.client.insert", { doc: doc });
      const failedAttachments = [];
      for (let index = 0; index < attachments.length; index += 1) {
        if (button) button.textContent = "Uploading " + (index + 1) + " / " + attachments.length + "…";
        try {
          await uploadAssetCheckAttachment(saved.name, attachments[index]);
        } catch (uploadError) {
          failedAttachments.push(attachments[index].name);
          void 0;
        }
      }
      closeModal();
      showToast(
        "Asset Check " + ((saved && saved.name) || "") + " saved · " + overallResult +
        (failedAttachments.length ? ". Attachment upload failed: " + failedAttachments.join(", ") : attachments.length ? " · " + attachments.length + " attachment(s) uploaded." : "."),
        !!failedAttachments.length
      );
      await loadAllData();
      STATE.checkAssetName = asset.name;
      renderCheckDesk();
    } catch (error) {
      showToast(error && error.message ? error.message : "Could not save LIFE Asset Check.", true);
      if (button) {
        button.disabled = false;
        button.textContent = "Save Check";
      }
    }
  }

  async function uploadAssetCheckAttachment(checkName, file) {
    if (!checkName || !file) return;
    const data = new FormData();
    data.append("file", file, file.name);
    data.append("doctype", "LIFE Asset Check");
    data.append("docname", checkName);
    data.append("is_private", "1");
    const headers = {};
    if (window.frappe && frappe.csrf_token) headers["X-Frappe-CSRF-Token"] = frappe.csrf_token;
    const response = await fetch("/api/method/upload_file", {
      method: "POST",
      credentials: "same-origin",
      headers: headers,
      body: data
    });
    if (!response.ok) throw new Error("Asset Check was saved, but attachment " + file.name + " could not be uploaded.");
  }

  function currentTimeValue() {
    const now = new Date();
    const two = function (value) { return String(value).padStart(2, "0"); };
    return [two(now.getHours()), two(now.getMinutes()), two(now.getSeconds())].join(":");
  }

