  function renderMaintenance() {
    const body = pageBody("maintenance");
    if (!body) return;

    const visitHistoryUnavailable = !sourceAvailable("maintenance");

    const assetsByName = new Map(getProductionAssets().map(function (asset) {
      return [asset.name, asset];
    }));

    const rows = STATE.filtered.maintenance.map(function (row) {
      const assetDoc = assetsByName.get(row.asset_name || "") || null;
      return {
        name: row.name,
        asset: row.asset_name || "",
        assetLabel: assetDoc ? (assetDoc.asset_name || assetDoc.item_name || row.item_name || row.item_code || "") : (row.item_name || row.item_code || ""),
        item: row.item_name || row.item_code || "",
        branch: canonicalBranchDisplayName(row.branch__location || (assetDoc ? assetDoc.location : "")),
        task: row.task_name || row.maintenance_type || row.task || "",
        type: row.maintenance_type || "",
        periodicity: row.periodicity || "",
        assignee: row.assign_to_name || row.task_assignee_email || "",
        dueDate: row.due_date || "",
        completionDate: row.completion_date || "",
        status: derivedMaintenanceStatus(row),
        description: stripHtml(row.description || ""),
        actions: stripHtml(row.actions_performed || ""),
        docstatus: row.docstatus,
        raw: row
      };
    });

    const planned = rows.filter(function (row) { return row.status === "Planned" || row.status === "Scheduled" || row.status === "Assigned"; }).length;
    const completed = rows.filter(function (row) { return row.status === "Completed"; }).length;
    const overdue = rows.filter(function (row) { return row.status === "Overdue"; }).length;
    const cancelled = rows.filter(function (row) { return row.status === "Cancelled"; }).length;
    const preventive = rows.filter(function (row) {
      const value = normalizeText(row.type + " " + row.task);
      return value.indexOf("preventive") !== -1 || value.indexOf("scheduled") !== -1;
    }).length;
    const complaintVisits = rows.filter(function (row) {
      const value = normalizeText(row.type + " " + row.task + " " + row.description);
      return value.indexOf("breakdown") !== -1 || value.indexOf("corrective") !== -1 || value.indexOf("complaint") !== -1 || value.indexOf("repair") !== -1;
    }).length;
    const reportPending = rows.filter(function (row) { return row.status === "Report Pending"; }).length;
    const visitSpend = sum(rows, function (row) { return row.raw && row.raw.service_cost; });
    const next30 = rows.filter(function (row) {
      const due = parseDate(row.dueDate);
      const today = startOfDay(new Date());
      return due && due >= today && due <= addDays(today, 30) && (row.status === "Planned" || row.status === "Scheduled" || row.status === "Assigned");
    }).length;

    STATE.exportData = {
      title: "Technicians And Visits",
      columns: ["Visit Log", "Technician", "Branch", "Asset", "Asset Name", "Task", "Maintenance Type", "Periodicity", "Due Date", "Completion Date", "Status", "Description", "Actions Performed"],
      rows: rows.map(function (row) {
        return [row.name, row.assignee, row.branch, row.asset, row.assetLabel, row.task, row.type, row.periodicity, row.dueDate, row.completionDate, row.status, row.description, row.actions];
      })
    };

    const technicianGroups = groupBy(rows.filter(function (row) { return row.assignee; }), function (row) {
      return row.assignee;
    });
    const technicianRows = Object.keys(technicianGroups).sort().map(function (technician) {
      const visits = technicianGroups[technician];
      const done = visits.filter(function (row) { return row.status === "Completed"; }).length;
      const open = visits.filter(function (row) { return row.status !== "Completed" && row.status !== "Cancelled"; }).length;
      const late = visits.filter(function (row) { return row.status === "Overdue"; }).length;
      const branches = uniqueSorted(visits.map(function (row) { return row.branch; }).filter(Boolean));
      const assets = uniqueSorted(visits.map(function (row) { return row.asset; }).filter(Boolean));
      return {
        technician: technician,
        visits: visits.length,
        completed: done,
        open: open,
        overdue: late,
        completionRate: visits.length ? Math.round((done / visits.length) * 100) : 0,
        branches: branches.join(", "),
        assets: assets.length
      };
    });

    const technicianColumns = [
      { key: "technician", label: "Technician" },
      { key: "branches", label: "Branches Visited" },
      { key: "visits", label: "Visits", type: "number" },
      { key: "assets", label: "Assets", type: "number" },
      { key: "completed", label: "Completed", type: "number" },
      { key: "open", label: "Open", type: "number" },
      { key: "overdue", label: "Overdue", type: "number", render: function (row) { return badgeHtml(row.overdue, row.overdue ? "bad" : "ok"); } },
      { key: "completionRate", label: "Completion", type: "number", render: function (row) { return badgeHtml(row.completionRate + "%", row.completionRate >= 80 ? "ok" : (row.completionRate >= 50 ? "warn" : "bad")); } }
    ];

    const columns = [
      {
        key: "name",
        label: "Visit ID",
        render: function (row) {
          return '<button type="button" class="la-button la-button-small la-register-id la-visit-id" data-action="open-technician-visit-detail" data-visit-name="' + escapeAttribute(row.name) + '">' + escapeHtml(row.name || "View") + '</button>';
        }
      },
      {
        key: "asset",
        label: "Asset",
        render: function (row) {
          return '<span class="la-visit-one-line" title="' + escapeAttribute(row.asset || "") + '">' + escapeHtml(row.assetLabel || row.asset || "—") + '</span>';
        }
      },
      { key: "branch", label: "Branch / Location" },
      { key: "assignee", label: "Technician" },
      {
        key: "type",
        label: "Visit / Task",
        render: function (row) {
          return '<span class="la-visit-one-line" title="' + escapeAttribute(row.task || "") + '">' + escapeHtml(row.type || row.task || "Maintenance") + '</span>';
        }
      },
      { key: "status", label: "Status", render: function (row) { return maintenanceStatusBadge(row.status); } },
      { key: "dueDate", label: "Due Date", render: function (row) { return formatDate(row.dueDate); } },
      {
        key: "open",
        label: "Open",
        sortable: false,
        type: "center",
        render: function (row) {
          return '<button type="button" class="la-button la-button-small la-button-primary" data-doctype="Technicians And Visits" data-docname="' + escapeAttribute(row.name) + '">Open</button>';
        }
      }
    ];

    body.innerHTML = [
      visitHistoryUnavailable
        ? noticeHtml("Technician visit history is restricted", "Historical Technicians And Visits records are not readable for this role. The New Technician Visit form remains available when Create permission is assigned.", "warn")
        : "",
      '<div class="la-grid la-grid-5 la-five-kpi-row">',
      kpiHtml("Visits in scope", rows.length, completed + " completed · " + planned + " planned", "🔧", "info"),
      kpiHtml("Preventive Visits", preventive, "Scheduled maintenance work", "✓", "ok"),
      kpiHtml("Complaint Visits", complaintVisits, "Breakdown / corrective work", "!", complaintVisits ? "warn" : "ok"),
      kpiHtml("Report Pending", reportPending, overdue + " overdue · " + next30 + " due next 30 days", "⌛", reportPending || overdue ? "bad" : "ok"),
      kpiHtml("Visit Spend", formatAmount(visitSpend), cancelled + " cancelled", "₹", "gold"),
      "</div>",
      '<div style="margin-top:13px">',
      actionBarHtml([
        { action: "new-maintenance", label: "+ New Technician Visit", style: "primary" },
        { action: "refresh", label: "↻ Refresh", style: "light" },
        { action: "export", label: "⇩ Export CSV", style: "gold" }
      ], rows.length + " real Technicians And Visits record(s) in the current filter"),
      noticeHtml("Real ERPNext source", "Every row below comes from your Technicians And Visits DocType. Technician uses Technician Name, and branch uses Branch / Location with the linked Asset location as fallback.", "info"),
