  function parseLifeTicketMetaBlock(description) {
    const match = String(description || "").match(/<!--LIFE_TICKET_META:([\s\S]*?)-->/);
    if (!match || !match[1]) return {};

    try {
      return JSON.parse(match[1]) || {};
    } catch (error) {
      return {};
    }
  }

  function lifeTicketReadableText(description) {
    const holder = document.createElement("div");
    holder.innerHTML = String(description || "")
      .replace(/<!--LIFE_TICKET_META:[\s\S]*?-->/g, "")
      .replace(/<br\s*\/?\s*>/gi, "\n")
      .replace(/<\/p>|<\/div>/gi, "\n");
    return String(holder.textContent || holder.innerText || "")
      .replace(/\r/g, "")
      .replace(/\n{2,}/g, "\n")
      .trim();
  }

  function lifeTicketLabelValue(text, label, nextLabels) {
    const escapedLabel = String(label).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const stops = (nextLabels || []).map(function (item) {
      return String(item).replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*:";
    });
    const stopPattern = stops.length ? "(?=" + stops.join("|") + "|$)" : "$";
    const match = String(text || "").match(new RegExp(escapedLabel + "\\s*:\\s*([\\s\\S]*?)" + stopPattern, "i"));
    return match && match[1] ? match[1].trim() : "";
  }

  function getLifeHelpdeskTicketMeta(issue) {
    const meta = parseLifeTicketMetaBlock(issue && issue.description);
    const text = lifeTicketReadableText(issue && issue.description);

    if (!meta.branch) meta.branch = lifeTicketLabelValue(text, "Branch", ["Category"]);
    if (!meta.category) meta.category = lifeTicketLabelValue(text, "Category", ["Issue"]);
    if (!meta.issue) meta.issue = lifeTicketLabelValue(text, "Issue", ["Other Issue", "Employee Involved", "Tagged To", "Tag To", "CC To", "Details"]);
    if (!meta.asset) {
      const assetText = lifeTicketLabelValue(text, "Asset", ["Tag To", "CC To", "Details"]);
      meta.asset = String(assetText || "").split(/\s+-\s+/)[0].trim();
    }
    if (!meta.resolver) meta.resolver = lifeTicketLabelValue(text, "Tag To", ["CC To", "Details"]);

    meta.group = classifyLifeAssetComplaint(meta.category, meta.issue);
    return meta;
  }

  function getLifeHelpdeskTicketDetails(issue) {
    const text = lifeTicketReadableText(issue && issue.description);
    return lifeTicketLabelValue(text, "Details", []) || text;
  }

  function classifyLifeAssetComplaint(category, specificIssue) {
    const categoryKey = normalizeText(category);
    const issueKey = normalizeText(specificIssue);

    if (categoryKey.indexOf("machinery") !== -1) return "Machinery";
    if (
      categoryKey.indexOf("electronics") !== -1 ||
      categoryKey.indexOf("electronic") !== -1 ||
      categoryKey.indexOf("electrical") !== -1 ||
      categoryKey === "electrical / equipment"
    ) return "Electronics";
    if (categoryKey.indexOf("furniture") !== -1 || issueKey.indexOf("furniture") !== -1) return "Furniture";

    return "";
  }

  function isAssetHelpdeskComplaint(meta) {
    return Boolean(meta && meta.group && meta.branch);
  }

