  function issueOpeningDateTime(issue) {
    const date = String(issue.opening_date || "").trim();
    const time = String(issue.opening_time || "").trim();

    if (date && time) return date + " " + time;
    return date || issue.creation || issue.modified || "";
  }

  function isDateTimePast(value) {
    const date = parseDate(value);
    return Boolean(date && date.getTime() < new Date().getTime());
  }

  function issueStatusTone(status) {
    switch (String(status || "").toLowerCase()) {
      case "open":
        return "bad";
      case "replied":
        return "info";
      case "on hold":
        return "warn";
      case "resolved":
        return "ok";
      case "closed":
        return "muted";
      default:
        return "info";
    }
  }

  function issuePriorityTone(priority) {
    const value = String(priority || "").toLowerCase();

    if (
      value.indexOf("urgent") !== -1 ||
      value.indexOf("high") !== -1
    ) {
      return "bad";
    }

    if (
      value.indexOf("medium") !== -1 ||
      value.indexOf("normal") !== -1
    ) {
      return "warn";
    }

    if (value.indexOf("low") !== -1) {
      return "ok";
    }

    return "muted";
  }

  function issueSlaTone(status) {
    switch (String(status || "").toLowerCase()) {
      case "failed":
        return "bad";
      case "fulfilled":
        return "ok";
      case "first response due":
      case "resolution due":
        return "warn";
      default:
        return "info";
    }
  }

  function issueDeadlineHtml(value, completed) {
    if (!value) return "—";

    const overdue = !completed && isDateTimePast(value);

    return [
      '<div class="la-date-position ',
      overdue ? "is-overdue" : "",
      '">',
      '<b>', escapeHtml(formatDateTime(value)), '</b>',
      '<span>',
      completed
        ? "Completed"
        : overdue
          ? "Overdue"
          : "Pending",
      "</span>",
      "</div>"
    ].join("");
  }

  function currentUserHasAnyRole(roleNames) {
    const roles = dashboardUserRoles();
    if (currentDashboardUser() === "Administrator" || roles.indexOf("System Manager") !== -1) return true;
    return (roleNames || []).some(function (role) { return roles.indexOf(role) !== -1; });
  }

