        '<button type="button" class="la-button la-button-small" data-action="apply-machinery-request-action" data-request-name="' + name + '" data-request-action="reject">Reject</button></span>';
    }
    if (["Approved", "Asset Allocated"].indexOf(state) !== -1 && (isBranchAllowedForUser(row.allocatedSourceBranch || "") || currentUserHasAnyRole(["System Manager"]))) {
      return '<button type="button" class="la-button la-button-small la-button-primary" data-action="transfer-allocated-machinery" data-request-name="' + name + '">Create Machinery Transfer</button>';
