  async function getMachineryRequestDocument(requestName) {
    const cached = (STATE.data.machineryRequests || []).find(function (row) { return row.name === requestName; });
    // The custom API has already applied requesting/source-branch visibility.
    // Use that row first so an allocated source branch never triggers Frappe's
    // standard Requesting Branch User Permission rejection.
    if (cached) return cached;
    try {
      return await frappeCall("frappe.client.get", { doctype: "Machinery Request", name: requestName });
    } catch (error) {
      throw error;
    }
  }

