  function machineryAvailabilityTrackerHtml() {
    if (!STATE.sourceMachineryAssetsLoaded && !STATE.sourceMachineryTrackerError) {
      if (!STATE.sourceMachineryTrackerLoading) {
        STATE.sourceMachineryTrackerLoading = true;
        Promise.all([ensureSourceMachineryAssets(), ensureRequestWarehouseOptions()]).then(function () {
          STATE.sourceMachineryTrackerLoading = false;
          STATE.sourceMachineryTrackerError = "";
          if (STATE.currentPage === "movements") renderMovements();
        }).catch(function (error) {
          STATE.sourceMachineryTrackerLoading = false;
          STATE.sourceMachineryTrackerError = error && error.message ? error.message : "Machinery locations could not be loaded.";
          if (STATE.currentPage === "movements") renderMovements();
        });
      }
      return '<div style="margin-bottom:14px">' + noticeHtml("Loading Machinery Availability", "Reading the current Machinery Asset location for every branch visible to your ERPNext user.", "info") + '</div>';
    }

    if (STATE.sourceMachineryTrackerError) {
      return '<div style="margin-bottom:14px">' + noticeHtml("Machinery Availability Unavailable", STATE.sourceMachineryTrackerError, "warn") + '</div>';
    }

    const targetBranch = canonicalBranchDisplayName(lockedBranchValue() || "");
    const targetKey = normalizeBranchText(targetBranch);
    // Restricted branch users must still see the controlled cross-branch
    // Machinery directory so they can request equipment from another branch.
    // HO/multi-branch users can narrow the tracker with the master Branch filter.
    const activeBranch = STATE.access && STATE.access.restricted
      ? ""
      : canonicalBranchDisplayName(STATE.filters.location || "");
    const activeCategory = normalizeText(STATE.filters.category || "");
    const activeMachineryCategory = normalizeText(STATE.filters.machinery_category || "");
    const activeSearch = normalize(STATE.filters.search || "");
    const rows = (STATE.sourceMachineryAssets || []).filter(function (asset) {
      const category = normalize(asset.asset_category || "");
      const status = normalize(asset.status || "");
      const branch = canonicalBranchDisplayName(asset.location || "");
      if (category !== "machinery" || status === "sold" || status === "scrapped" || !branch || isTestingBranchName(branch)) return false;
      if (activeBranch && normalizeBranchText(branch) !== normalizeBranchText(activeBranch)) return false;
      if (activeCategory && category !== activeCategory) return false;
      if (activeMachineryCategory && normalizeText(asset.custom_machinery_assets_category || "") !== activeMachineryCategory) return false;
      if (activeSearch) {
        const haystack = normalize([
          asset.name,
          asset.asset_name,
          asset.item_name,
          asset.asset_category,
          asset.custom_machinery_assets_category,
          asset.location,
          branch,
          asset.status
        ].join(" "));
        if (haystack.indexOf(activeSearch) === -1) return false;
      }
      return true;
    }).map(function (asset) {
      const branch = canonicalBranchDisplayName(asset.location || "");
      const atTargetBranch = Boolean(targetKey && normalizeBranchText(branch) === targetKey);
      return {
        name: asset.name || "",
        assetName: asset.asset_name || asset.item_name || asset.name || "",
        machineryCategory: asset.custom_machinery_assets_category || "Not Set",
        branch: branch,
        status: asset.status || "Not Set",
        availability: atTargetBranch ? "At Your Branch" : "Available to Request",
        atTargetBranch: atTargetBranch
      };
    }).sort(function (a, b) {
      return String(a.branch).localeCompare(String(b.branch)) || String(a.assetName).localeCompare(String(b.assetName));
    });

    const columns = [
      {
        key: "name",
        label: "Machinery ID",
        render: function (row) {
          return '<span class="la-button la-button-small la-register-id" title="Machinery Asset ID">' + escapeHtml(row.name) + '</span>';
        }
