      { key: "status", label: "Machine Status", render: function (row) { return badgeHtml(row.status, statusTone(row.status)); } },
      { key: "availability", label: "Availability", render: function (row) { return badgeHtml(row.availability, row.atTargetBranch ? "info" : "ok"); } },
