  function getApprovalQueueRows() {
    const rows = [];

    if (sourceAvailable("machineryRequests")) {
      STATE.filtered.machineryRequests.forEach(function (row) {
        const status = String(row.request_status || "Draft");
        if (["Approved", "Asset Allocated", "Completed", "Rejected", "Transfer Created"].indexOf(status) !== -1) return;
        rows.push({
          type: "Machinery Request",
          reference: row.name,
          doctype: "Machinery Request",
          date: row.request_date || row.creation || row.modified,
          status: status,
          workflowState: status,
          owner: row.requested_by || row.owner || "",
          detail: [
            canonicalBranchDisplayName(row.requesting_branch || ""),
            row.requested_item,
            "Qty " + (row.quantity || 1),
            row.priority,
            row.requirement_reason
          ].filter(Boolean).join(" · "),
          age: daysSince(row.request_date || row.creation || row.modified),
          requestStatus: status,
          tone: status.indexOf("Pending") !== -1 ? "warn" : "info"
        });
      });
    }

    // Machinery Transfer no longer has a separate approval stage. Only
    // Machinery Request approvals belong in the Approvals Desk.

    if (sourceAvailable("movements")) {
      STATE.filtered.movements.forEach(function (row) {
        if (Number(row.docstatus) !== 0) return;

        rows.push({
          type: "Transfer / Shifting",
          reference: row.name,
          doctype: "Asset Movement",
          date: row.transaction_date || row.creation || row.modified,
          status: "Draft — pending submission / approval",
          owner: row.reference_name || "",
          detail: [
            row.purpose || "Asset Movement",
            joinReference(row.reference_doctype, row.reference_name)
          ].filter(Boolean).join(" · "),
          age: daysSince(row.transaction_date || row.creation || row.modified),
          tone: "warn"
        });
      });
    }

    return rows.sort(function (a, b) {
      if (a.tone !== b.tone) return a.tone === "bad" ? -1 : 1;
      return compareValues(a.date, b.date);
    });
  }

  function getApprovedMachineryRequestRows() {
    const approvedStatuses = ["approved", "asset allocated", "transfer created", "completed"];
    // Approval history must not disappear because of a temporary master
    // date, category, machinery-category or Asset search filter. STATE.data
    // has already been restricted by ERPNext permissions and branch scope.
    return (STATE.data.machineryRequests || []).filter(function (row) {
      return approvedStatuses.indexOf(normalizeText(row.request_status || "")) !== -1;
    }).map(function (row) {
      const approvedOn = row.approved_on || row.stock_manager_approved_on || row.sales_manager_approved_on || row.modified || "";
      const approvedBy = row.approved_by || row.stock_manager_approved_by || row.sales_manager_approved_by || row.modified_by || "";
      return {
        reference: row.name || "",
        machinery: machineryAssetDisplayName(row.allocated_asset) || row.requested_item || "—",
        requestingBranch: canonicalBranchDisplayName(row.requesting_branch || ""),
        sourceBranch: canonicalBranchDisplayName(row.allocated_source_branch || ""),
        requestedBy: row.custom_requested_by_name || STATE.machineryRequestEmployeeNames[row.requested_by] || row.requested_by || "—",
        status: row.request_status || "Approved",
        approvedOn: approvedOn,
        approvedBy: approvedBy,
        transfer: row.machinery_transfer || ""
      };
    }).sort(function (a, b) {
      return String(b.approvedOn || "").localeCompare(String(a.approvedOn || ""));
    });
  }

  function daysSince(value) {
    const date = parseDate(value);
    if (!date) return 0;
    return Math.max(
      0,
      Math.floor(
        (startOfDay(new Date()).getTime() - startOfDay(date).getTime()) /
        86400000
      )
    );
  }

