  function renderMasters() {
    const body = pageBody("masters");
    if (!body) return;

    const assets = STATE.filtered.assets || [];
    const liveSuppliers = sourceAvailable("suppliers")
      ? (STATE.filtered.suppliers || [])
      : [];

    const categories = uniqueSorted(assets.map(function (row) { return row.asset_category; }));
    const branches = uniqueSorted(assets.map(function (row) { return getLifeBranchName(row.location); }));
    const departments = uniqueSorted(assets.map(function (row) { return row.department; }));
    const assetSupplierNames = uniqueSorted(assets.map(function (row) { return row.supplier; }));

    function categoryMeta(name) {
      const key = normalizeText(name);
      if (key.indexOf("MACHIN") !== -1) return { icon: "⚙️", tone: "machinery", note: "Treatment and clinical machinery recorded in ERPNext Asset." };
      if (key.indexOf("ELECT") !== -1 || key.indexOf("COMPUT") !== -1 || key.indexOf("IT") !== -1) return { icon: "💻", tone: "electronics", note: "Electronics, computing, communication and support equipment." };
      if (key.indexOf("VEHIC") !== -1 || key.indexOf("CAR") !== -1) return { icon: "🚗", tone: "vehicles", note: "Vehicles and transport assets recorded in ERPNext Asset." };
      if (key.indexOf("FURN") !== -1 || key.indexOf("FIXTURE") !== -1) return { icon: "🪑", tone: "furniture", note: "Furniture, fixtures and physical workplace assets." };
      return { icon: "🏷️", tone: "other", note: "Live ERPNext Asset records under this category." };
    }

    const categoryRows = categories.map(function (category) {
      const rows = assets.filter(function (asset) { return asset.asset_category === category; });
      return {
        category: category,
        records: rows.length,
        units: sumAssetUnits(rows),
        value: rows.reduce(function (sum, asset) { return sum + getAssetBookValue(asset); }, 0),
        items: uniqueSorted(rows.map(function (asset) { return asset.item_code || asset.item_name; })).length,
        branches: uniqueSorted(rows.map(function (asset) { return getLifeBranchName(asset.location); })).length,
        departments: uniqueSorted(rows.map(function (asset) { return asset.department; })).length,
        suppliers: uniqueSorted(rows.map(function (asset) { return asset.supplier; })).length,
        meta: categoryMeta(category)
      };
    }).sort(function (a, b) { return b.units - a.units; });

    const itemMap = new Map();
    assets.forEach(function (asset) {
      const key = [
        asset.asset_category || "Uncategorised",
        asset.item_code || "",
        asset.item_name || asset.asset_name || asset.name || ""
      ].join("||");

      if (!itemMap.has(key)) {
        itemMap.set(key, {
          category: asset.asset_category || "Uncategorised",
          item_code: asset.item_code || "—",
          item_name: asset.item_name || asset.asset_name || asset.name || "—",
          records: 0,
          units: 0,
          value: 0,
          branchSet: new Set(),
          departmentSet: new Set(),
          supplierSet: new Set(),
          statusSet: new Set()
        });
      }

      const row = itemMap.get(key);
      row.records += 1;
      row.units += assetUnitCount(asset);
      row.value += getAssetBookValue(asset);
      if (getLifeBranchName(asset.location)) row.branchSet.add(getLifeBranchName(asset.location));
      if (asset.department) row.departmentSet.add(asset.department);
      if (asset.supplier) row.supplierSet.add(asset.supplier);
      if (asset.status) row.statusSet.add(asset.status);
    });

    const itemRows = Array.from(itemMap.values()).map(function (row) {
      return {
        category: row.category,
        item_code: row.item_code,
        item_name: row.item_name,
        records: row.records,
        units: row.units,
        value: row.value,
        branches: row.branchSet.size,
        departments: Array.from(row.departmentSet).join(", ") || "—",
        suppliers: Array.from(row.supplierSet).join(", ") || "—",
        statuses: Array.from(row.statusSet).join(", ") || "—"
      };
    }).sort(function (a, b) {
      return a.category.localeCompare(b.category, undefined, { sensitivity: "base" }) ||
        a.item_name.localeCompare(b.item_name, undefined, { sensitivity: "base" });
    });

    const masterRows = [
      { master: "Asset", doctype: "Asset", count: assets.length, source: "Live Asset documents in the current filter", position: "Available" },
      { master: "Supplier / Vendor", doctype: "Supplier", count: sourceAvailable("suppliers") ? liveSuppliers.length : assetSupplierNames.length, source: sourceAvailable("suppliers") ? "Live Supplier documents linked to visible Assets" : "Derived from Supplier values on visible Assets", position: sourceAvailable("suppliers") ? "Available" : "Derived" },
      { master: "Branch", doctype: "Branch", count: sourceAvailable("branches") ? STATE.filtered.branches.length : branches.length, source: sourceAvailable("branches") ? "Live Branch documents" : "Derived from Asset locations", position: sourceAvailable("branches") ? "Available" : "Derived" },
      { master: "Asset Category", doctype: "Asset Category", count: categories.length, source: "Distinct categories on visible Assets", position: "Derived" },
      { master: "Location", doctype: "Location", count: branches.length, source: "Distinct Asset locations in the current filter", position: "Derived" },
      { master: "Department", doctype: "Department", count: departments.length, source: "Distinct departments on visible Assets", position: "Derived" },
      { master: "LIFE Asset Check", doctype: "LIFE Asset Check", count: sourceAvailable("checks") ? STATE.data.checks.filter(function (row) { return !isTestingBranchName(row.location || ""); }).length : 0, source: "Live preventive asset check documents", position: sourceAvailable("checks") ? "Available" : "No permission" },
      { master: "Issue / Complaints", doctype: "Issue", count: sourceAvailable("issues") ? STATE.data.issues.length : 0, source: "Live ERPNext Issue documents", position: sourceAvailable("issues") ? "Available" : "No permission" },
      { master: "Technicians And Visits", doctype: "Technicians And Visits", count: sourceAvailable("maintenance") ? STATE.data.maintenance.length : 0, source: "Live technician visit records", position: sourceAvailable("maintenance") ? "Available" : "No permission" },
      { master: "Asset Repair", doctype: "Asset Repair", count: sourceAvailable("repairs") ? STATE.data.repairs.length : 0, source: "Live Asset Repair documents", position: sourceAvailable("repairs") ? "Available" : "No permission" },
      { master: "Machinery Transfer", doctype: "Machinery Transfer", count: sourceAvailable("machineryTransfers") ? STATE.data.machineryTransfers.length : 0, source: "Live Machinery Transfer documents", position: sourceAvailable("machineryTransfers") ? "Available" : "No permission" },
      { master: "Asset Movement", doctype: "Asset Movement", count: sourceAvailable("movements") ? STATE.data.movements.length : 0, source: "Live Asset Movement documents", position: sourceAvailable("movements") ? "Available" : "No permission" }
    ];

    const supplierRows = liveSuppliers.map(function (supplier) {
      return {
        name: supplier.name,
        supplier_name: supplier.supplier_name || supplier.name,
        group: supplier.supplier_group || "—",
        type: supplier.supplier_type || "—",
        branch: supplier.custom_branch || "—",
        relation_manager: supplier.custom_relation_manager || "—",
        phone: supplier.custom_phone_number || supplier.custom_company_number || supplier.custom_dealer_number || "—",
        whatsapp: supplier.custom_whatsapp || "—",
        materials: supplier.custom_materials_provided || "—",
        rank: supplier.custom_preference_rank || "—",
        status: Number(supplier.disabled || 0) ? "Disabled" : "Active"
      };
    });

    STATE.exportData = {
      title: "Asset Item Master Position",
      columns: ["Category", "Item Code", "Item Name", "Asset Records", "Units", "Branches", "Departments", "Suppliers", "Statuses", "Book Value"],
      rows: itemRows.map(function (row) {
        return [row.category, row.item_code, row.item_name, row.records, row.units, row.branches, row.departments, row.suppliers, row.statuses, row.value];
      })
    };

    const categoryCards = categoryRows.length
      ? categoryRows.map(function (row) {
          return [
            '<article class="la-master-category-card la-master-category-', row.meta.tone, '">',
              '<div class="la-master-category-top">',
                '<span class="la-master-category-icon">', row.meta.icon, '</span>',
                '<div><small>ASSET CATEGORY</small><h3>', escapeHtml(row.category), '</h3></div>',
              '</div>',
              '<p>', escapeHtml(row.meta.note), '</p>',
              '<div class="la-master-category-metrics">',
                '<span><b>', formatNumber(row.units), '</b><small>Units</small></span>',
                '<span><b>', formatNumber(row.records), '</b><small>Records</small></span>',
                '<span><b>', formatNumber(row.items), '</b><small>Item types</small></span>',
                '<span><b>', formatNumber(row.branches), '</b><small>Branches</small></span>',
              '</div>',
              '<div class="la-master-category-value">Book value <b>', formatAmount(row.value), '</b> · ', formatNumber(row.departments), ' department(s) · ', formatNumber(row.suppliers), ' supplier(s)</div>',
              '<button type="button" class="la-button la-button-small la-button-gold" data-action="open-category-assets" data-category="', escapeAttribute(row.category), '">Open filtered register</button>',
            '</article>'
          ].join("");
        }).join("")
      : noticeHtml("No category position", "No Asset records match the current master filter.", "warn");

    const itemColumns = [
      { key: "category", label: "Asset Category" },
      { key: "item_code", label: "Item Code" },
      { key: "item_name", label: "Item / Asset Type" },
      { key: "suppliers", label: "Supplier / Vendor" },
      { key: "departments", label: "Department(s)" },
      { key: "records", label: "Records", type: "number" },
      { key: "units", label: "Units", type: "number" },
      { key: "branches", label: "Branches", type: "number" },
      { key: "statuses", label: "Status Values" },
      { key: "value", label: "Book Value", type: "amount" }
    ];

    const supplierColumns = [
      { key: "supplier_name", label: "Supplier / Vendor" },
      { key: "group", label: "Supplier Group" },
      { key: "type", label: "Type" },
      { key: "branch", label: "Branch" },
      { key: "relation_manager", label: "Relation Manager" },
      { key: "phone", label: "Phone" },
      { key: "whatsapp", label: "WhatsApp" },
      { key: "materials", label: "Materials / Stock" },
      { key: "rank", label: "Preference Rank" },
      { key: "status", label: "Status", render: function (row) { return badgeHtml(row.status, row.status === "Active" ? "ok" : "bad"); } },
      { key: "open", label: "Open", render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Supplier" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
    ];

    const controlColumns = [
      { key: "master", label: "Master / Control" },
      { key: "doctype", label: "ERPNext DocType" },
      { key: "count", label: "Live Count", type: "number" },
      { key: "source", label: "Data Source" },
      { key: "position", label: "Position", render: function (row) { return badgeHtml(row.position, row.position === "Available" ? "ok" : row.position === "Derived" ? "info" : "bad"); } },
      { key: "open", label: "Open", render: function (row) { return '<button type="button" class="la-button la-button-small" data-action="open-list" data-doctype="' + escapeAttribute(row.doctype) + '">Open List</button>'; } }
    ];

    const readAccess = [
      ["Asset", true],
      ["Supplier", sourceAvailable("suppliers")],
      ["Branch", sourceAvailable("branches")],
      ["Asset Check", sourceAvailable("checks")],
      ["Issue", sourceAvailable("issues")],
