  function openDoctypeList(doctype) {
    const name = String(doctype || "").trim();
    if (!name) return;

    try {
      if (
        window.frappe &&
        typeof frappe.set_route === "function"
      ) {
        frappe.set_route("List", name);
        return;
      }
    } catch (error) {
      // Fall through to website-compatible route.
    }

    const slug = name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");

    window.open("/app/" + slug, "_blank", "noopener");
  }

  function renderAsset360() {
    const body = pageBody("asset360");
    if (!body) return;

    // Machine 360 must remain a complete machinery finder. Do not apply the
    // dashboard's temporary Branch / Location filter here; ERPNext read and
    // User Permission rules have already limited STATE.data.assets.
    const assets = (STATE.data.assets || []).filter(function (asset) {
      return normalize(asset.asset_category || "") === "machinery" &&
        !isTestingBranchName(getLifeBranchName(asset.location || "")) &&
        normalize(asset.status || "") !== "sold" &&
        normalize(asset.status || "") !== "scrapped";
    }).sort(function (a, b) {
      return String(getLifeBranchName(a.location || "")).localeCompare(String(getLifeBranchName(b.location || "")), undefined, { numeric: true, sensitivity: "base" }) ||
        String(a.custom_machinery_assets_category || "").localeCompare(String(b.custom_machinery_assets_category || ""), undefined, { numeric: true, sensitivity: "base" }) ||
        String(a.asset_name || a.item_name || a.name).localeCompare(String(b.asset_name || b.item_name || b.name), undefined, { numeric: true, sensitivity: "base" });
    });

    if (STATE.asset360Name && !assets.some(function (asset) { return asset.name === STATE.asset360Name; })) STATE.asset360Name = "";
    if (STATE.asset360SearchName && !assets.some(function (asset) { return asset.name === STATE.asset360SearchName; })) STATE.asset360SearchName = "";

    const options = assets.map(function (asset) {
      const label = asset.name + " · " + (asset.asset_name || asset.item_name || "Unnamed Asset") + " · " +
        (asset.custom_machinery_assets_category || "Machinery") + " · " + getLifeBranchName(asset.location);
      return '<option value="' + escapeAttribute(asset.name) + '"' + (asset.name === STATE.asset360SearchName ? " selected" : "") + ">" + escapeHtml(label) + "</option>";
    }).join("");
    const quickAssets = assets.slice().sort(function (a, b) {
      const attentionA = /out of order|maintenance|issue/i.test(String(a.status || "")) ? 1 : 0;
      const attentionB = /out of order|maintenance|issue/i.test(String(b.status || "")) ? 1 : 0;
      if (attentionB !== attentionA) return attentionB - attentionA;
      return String(a.asset_name || a.item_name || a.name).localeCompare(String(b.asset_name || b.item_name || b.name), undefined, { numeric: true, sensitivity: "base" });
    }).slice(0, 8);
    const quickAssetHtml = quickAssets.map(function (asset) {
      return '<button type="button" class="la-button la-button-small" data-action="asset360" data-asset-name="' + escapeAttribute(asset.name) + '">' + escapeHtml(asset.asset_name || asset.item_name || asset.name) + '</button>';
    }).join("");

    let content = [
      '<div class="la-search-hero">',
      "<h2>Machine 360</h2>",
      "<p>Search every permission-visible Machinery Asset across all branches by name, Asset ID, Machinery Category or current branch, then open its complete LIFE history.</p>",
      '<div style="margin:12px 0 6px;color:#fff;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.6px">All branches · All machinery categories · ' + formatNumber(assets.length) + ' machine(s)</div>',
      '<div class="la-search-row">',
      '<select data-asset360-select><option value="">Search Asset ID, machine name, machinery category or branch…</option>' + options + "</select>",
      '<button type="button" class="la-button la-button-gold" data-action="open-selected-asset360">Open 360</button>',
      "</div>",
      quickAssetHtml ? '<div style="display:flex;flex-wrap:wrap;gap:7px;margin-top:10px">' + quickAssetHtml + '</div>' : '',
      "</div>"
    ].join("");

    if (!assets.length) {
      content += emptyStateHtml("No Machinery assets available", "No Machinery Asset records are visible to this ERPNext user. Check Asset read permission and Branch / Location User Permissions.");
      body.innerHTML = content;
      return;
    }

    if (!STATE.asset360Name) {
      content += machine360DirectoryHtml(assets);
      body.innerHTML = content;
      enhancePopupSelects(body.querySelector(".la-search-row"));
      return;
    }

    const asset = assets.find(function (row) { return row.name === STATE.asset360Name; });
    const supplier = sourceAvailable("suppliers")
      ? (STATE.data.suppliers || []).find(function (row) {
          const assetSupplier = normalizeText(asset.supplier);
          return normalizeText(row.name) === assetSupplier ||
            normalizeText(row.supplier_name) === assetSupplier;
        })
      : null;
    const repairs = STATE.data.repairs.filter(function (row) { return row.asset === asset.name; });
    const checks = getChecksForAsset(asset.name, false);
    const maintenance = STATE.data.maintenance.filter(function (row) { return row.asset_name === asset.name; });
    const complaints = (STATE.data.issues || []).filter(function (row) {
      const ticketMeta = getLifeHelpdeskTicketMeta(row);
      const haystack = normalize([row.subject, row.description, row.resolution_details].join(" "));
      return (ticketMeta.asset && ticketMeta.asset === asset.name) ||
        (row.asset && row.asset === asset.name) ||
        haystack.indexOf(normalize(asset.name)) !== -1;
    });
    const movementItems = STATE.data.movementItems.filter(function (row) { return row.asset === asset.name; });
    const machineTransfers = getMachineTransferHistory(asset.name);
    const movementMap = indexBy(STATE.data.movements, "name");
    const schedules = STATE.data.depreciation.filter(function (row) { return row.asset === asset.name; });
    const activities = STATE.data.activities.filter(function (row) { return row.asset === asset.name; });
    const timeline = buildAssetTimeline(asset, repairs, checks, maintenance, complaints, movementItems, movementMap, schedules, activities, machineTransfers);
    const assetRepairCost = sum(repairs, getRepairCost);
    const technicianServiceCost = sum(maintenance, function (row) { return toNumber(row.service_cost); });
    const totalRepairCost = assetRepairCost + technicianServiceCost;
    const overdueMaintenance = maintenance.filter(isMaintenanceAttention).length;

    STATE.exportData = {
      title: "Machine 360 - " + asset.name,
      columns: ["Date", "Type", "Title", "Details", "Reference"],
      rows: timeline.map(function (item) { return [item.date, item.type, item.title, item.body, item.reference]; })
    };

    content += [
      '<div class="la-360-backbar"><button type="button" class="la-button la-button-light" data-action="asset360-back">← Back to Machine Search</button><span>Complete life history for ' + escapeHtml(asset.name) + '</span></div>',
      machine360ProfileHtml(asset, checks, complaints, maintenance, repairs, machineTransfers, totalRepairCost, overdueMaintenance),
      '<div style="margin-top:13px">',
      cardHtml(
        "Machine Journey & Transfer Tracking",
        machineTransfers.length + " Machinery Transfer(s) · current branch " + getLifeBranchName(asset.location),
        machineJourneyHtml(asset, machineTransfers)
      ),
      "</div>",
      '<div class="la-360-master-stack" style="margin-top:13px">',
      cardHtml("Asset Master", asset.name, detailGridHtml([
        ["Asset Name", asset.asset_name || "—"],
        ["Item Code", asset.item_code || "—"],
        ["Item Name", asset.item_name || "—"],
        ["Asset Category", asset.asset_category || "—"],
        ["Machinery Category", asset.custom_machinery_assets_category || "—"],
        ["Company", asset.company || "—"],
        ["Location", getLifeBranchName(asset.location)],
        ["Department", asset.department || "—"],
        ["Employee Name", STATE.machineryRequestEmployeeNames[asset.custodian] || asset.custodian || "—"],
        ["Supplier", asset.supplier || "—"],
        ["Purchase Date", formatDate(asset.purchase_date)],
        ["Available for Use", formatDate(asset.available_for_use_date)],
        ["Status", asset.status || "—"],
        ["Maintenance Required", yesNo(asset.maintenance_required)],
        ["Modified", formatDateTime(asset.modified)],
        ["Modified By", asset.modified_by || "—"]
      ])),
      cardHtml("Finance, Insurance & Depreciation", "Current ERPNext Asset values", detailGridHtml([
        ["Net Purchase Amount", formatAmount(toNumber(asset.gross_purchase_amount || asset.purchase_amount))],
        ["Additional Asset Cost", formatAmount(toNumber(asset.additional_asset_cost))],
        ["Total Asset Cost", formatAmount(getAssetCost(asset))],
        ["Value After Depreciation", formatAmount(getAssetBookValue(asset))],
        ["Accumulated Depreciation", formatAmount(Math.max(0, getAssetCost(asset) - getAssetBookValue(asset)))],
        ["Depreciation Method", asset.depreciation_method || "—"],
        ["Next Depreciation Date", formatDate(asset.next_depreciation_date)],
        ["Insurance Policy", asset.policy_number || "—"],
        ["Insurer", asset.insurer || "—"],
        ["Insured Value", formatAmount(toNumber(asset.insured_value))],
        ["Insurance Start", formatDate(asset.insurance_start_date)],
        ["Insurance End", formatDate(asset.insurance_end_date)],
        ["Comprehensive Insurance", asset.comprehensive_insurance || "—"],
        ["Disposal Date", formatDate(asset.disposal_date)],
        ["Depreciation Schedules", schedules.length],
        ["Repair Cost / Asset Cost", percentage(totalRepairCost, getAssetCost(asset)) + "%"]
      ])),
      "</div>",
      asset.supplier
        ? '<div style="margin-top:13px">' +
          cardHtml(
            "Supplier / Vendor Position",
            supplier
              ? "Live Supplier master record"
              : (sourceAvailable("suppliers") ? "Linked Supplier record was not returned" : "Supplier master permission unavailable"),
            detailGridHtml([
