  function renderReports() {
    const body = pageBody("reports");
    if (!body) return;

    const reportDefinitions = pdfAssetReportDefinitions();
    const activeDefinition = reportDefinitions.find(function (definition) { return definition.id === STATE.reportType; }) || null;
    const report = activeDefinition ? buildReport(activeDefinition.baseType) : null;
    STATE.exportData = report ? report.exportData : { title: "LIFE Asset Report Catalogue", columns: [], rows: [] };

    const assets = STATE.filtered.assets || [];
    const units = sumAssetUnits(assets);
    const locations = uniqueSorted(assets.map(function (asset) { return getLifeBranchName(asset.location); }).filter(Boolean)).length;
    const openComplaints = (STATE.filtered.issues || []).filter(function (issue) {
      return ["closed", "resolved"].indexOf(normalize(issue.status || "")) === -1;
    }).length;
    const pendingTransfers = (STATE.filtered.machineryTransfers || []).filter(function (row) {
      return ["completed", "rejected", "cancelled"].indexOf(normalize(row.workflow_state || row.transfer_status || "")) === -1;
    }).length;
    const passedChecks = (STATE.filtered.checks || []).filter(function (row) { return normalize(row.overall_result || "") === "pass"; }).length;
    const checkCompliance = percentage(passedChecks, (STATE.filtered.checks || []).length);
    let lastGroup = "";
    const catalogue = reportDefinitions.map(function (definition) {
      const isOpen = Boolean(activeDefinition && activeDefinition.id === definition.id);
      let section = "";
      if (definition.group !== lastGroup) {
        lastGroup = definition.group;
        section = '<div class="la-report-section-title">' + escapeHtml(definition.group) + '</div>';
      }
      return section + '<div class="la-report-catalog-row' + (isOpen ? " is-open" : "") + '">' +
        '<div class="la-report-catalog-head" role="button" tabindex="0" aria-expanded="' + (isOpen ? "true" : "false") + '" ' + (isOpen ? 'data-action="close-report"' : 'data-report-type="' + escapeAttribute(definition.id) + '"') + '>' +
          '<div class="la-report-catalog-title">' + escapeHtml(definition.number + ". " + definition.label) + '</div>' +
          '<div class="la-report-catalog-desc">' + escapeHtml(definition.description) + '</div>' +
          (isOpen
            ? '<button type="button" class="la-button la-report-show" data-action="close-report">▲ Hide</button>'
            : '<button type="button" class="la-button la-report-show" data-report-type="' + escapeAttribute(definition.id) + '">▼ Show</button>') +
        '</div>' +
        (isOpen ? '<div class="la-report-catalog-body">' + (report.summaryHtml || "") + report.tableHtml + '<div class="la-report-close"><button type="button" class="la-button" data-action="close-report">Close report</button></div></div>' : "") +
      '</div>';
    }).join("");

    body.innerHTML = [
      '<section class="la-report-hero">',
        '<h2>Reports</h2>',
        '<p>Real ERPNext asset reports driven by the master filter. Every total below is calculated from records visible to the logged-in user.</p>',
        '<div class="la-report-access"><span>', formatNumber(units), ' asset units</span><span>', formatNumber(locations), ' branches / locations</span><span>', formatNumber(reportDefinitions.length), ' report positions</span><span>Permission-aware</span><span>Real records only</span></div>',
      '</section>',
      '<div class="la-grid la-grid-6" style="margin-bottom:13px">',
        kpiHtml("Fleet", units, locations + " branches / locations", "▤", "info"),
        kpiHtml("Asset Cost", formatAmount(sum(assets, getAssetCost)), assets.length + " Asset records", "₹", "gold"),
        kpiHtml("Book Value", formatAmount(sum(assets, getAssetBookValue)), "Current filtered position", "₹", "ok"),
        kpiHtml("Open Complaints", openComplaints, "Real Issue records", "🚨", openComplaints ? "warn" : "ok"),
        kpiHtml("Transfers in Progress", pendingTransfers, "Live Machinery Transfer records", "🚚", pendingTransfers ? "info" : "ok"),
        kpiHtml("Check Compliance", checkCompliance + "%", passedChecks + " passed checks", "✅", checkCompliance >= 80 ? "ok" : "warn"),
      '</div>',
      noticeHtml("37 PDF-aligned report positions", "Open any report below. Figures come only from permission-visible ERPNext records; a field stays blank when its real source is unavailable.", "info"),
      activeDefinition ? '<div class="la-action-bar"><b>Open report: ' + escapeHtml(activeDefinition.label) + '</b><div class="la-action-bar-spacer"></div><button type="button" class="la-button la-button-gold" data-action="export">⇩ Export Current Report</button></div>' : "",
      '<div class="la-report-catalog">' + catalogue + '</div>'
    ].join("");
  }

  function buildReport(type) {
    switch (type) {
      case "machine": return buildMachineWiseReport();
      case "machinery_location": return buildMachineryLocationReport();
      case "availability_matrix": return buildAvailabilityMatrixReport();
      case "department": return buildGroupedAssetReport("department", "Department-wise Asset Summary", "Department");
      case "vendor": return buildGroupedAssetReport("supplier", "Vendor-wise Asset Summary", "Supplier / Vendor");
      case "not_working": return buildNotWorkingReport();
      case "complaints": return buildComplaintReport();
      case "complaint_age": return buildComplaintAgeReport();
      case "visits": return buildVisitReport("all");
      case "technician_performance": return buildVisitReport("technician");
      case "preventive_visits": return buildVisitReport("preventive");
      case "machinery_category": return buildMachineryCategoryReport();
      case "disposal": return buildDisposalReport();
      case "repeat_failures": return buildRepeatFailureReport();
      case "unavailable_warranty": return buildUnavailableReport("Warranty & AMC register", "The loaded Asset schema contains insurance fields, but no confirmed warranty or AMC start/end-date fields. Insurance is not shown as warranty data.");
      case "unavailable_amc": return buildUnavailableReport("AMC renewal calendar", "No confirmed AMC start/end-date fields are loaded from your Asset DocType. Add the exact AMC fields before this report can calculate renewals.");
      case "unavailable_usage": return buildUnavailableReport("Usage-wise report", "No confirmed usage meter or session source is connected. The dashboard will not use Asset status as fake usage data.");
      case "unavailable_utilisation": return buildUnavailableReport("Idle & under-utilised assets", "No confirmed utilisation or session-count source is connected, so idle percentage cannot be calculated correctly.");
      case "unavailable_sessions": return buildUnavailableReport("Cost per session & return", "No confirmed treatment-session and revenue source is connected, so cost per session and return cannot be calculated correctly.");
      case "unavailable_downtime": return buildUnavailableReport("Downtime & revenue impact", "No confirmed downtime start/end and revenue-impact fields are connected. The dashboard will not estimate these values.");
      case "unavailable_spares": return buildUnavailableReport("Spare parts & material consumption", "No confirmed spare-parts child table or Stock Entry link is connected to this report.");
      case "unavailable_it_cover": return buildUnavailableReport("IT warranty, AMC & replacement plan", "No confirmed IT warranty, AMC or replacement-target fields are loaded from Asset.");
      case "unavailable_data_assets": return buildUnavailableReport("Data-bearing asset control", "No confirmed data-bearing or data-classification field is loaded from Asset.");
      case "unavailable_vehicle_expiry": return buildUnavailableReport("Vehicle document expiry calendar", "No confirmed vehicle RC, permit, pollution or document-expiry fields are loaded from Asset.");
      case "unavailable_vehicle_mileage": return buildUnavailableReport("Vehicle running, mileage & service", "No confirmed odometer, mileage or vehicle-service source is connected.");
      case "unavailable_vehicle_workshop": return buildUnavailableReport("Vehicle complaints & workshop", "Current Issue records do not provide a confirmed Vehicle-only link for this report.");
      case "unavailable_furniture_grade": return buildUnavailableReport("Furniture condition grade audit", "No confirmed furniture condition-grade field is loaded from Asset or LIFE Asset Check.");
      case "unavailable_furniture_plan": return buildUnavailableReport("Furniture repair & replacement plan", "A confirmed Furniture repair source and replacement-life rule are required before this report can be calculated.");
      case "checks": return buildCheckReport(false);
      case "check_failures": return buildCheckReport(true);
      case "electronics": return buildCategoryAssetReport("electronics", "Electronics Register");
      case "vehicles": return buildCategoryAssetReport("vehicle", "Vehicle Register");
      case "furniture": return buildCategoryAssetReport("furniture", "Furniture Register");
      case "location": return buildLocationReport();
      case "status": return buildStatusReport();
      case "financial": return buildFinancialReport();
      case "maintenance": return buildMaintenanceRepairReport();
      case "insurance": return buildInsuranceReport();
      case "age": return buildAgeReport();
      case "custodian": return buildCustodianReport();
      case "category":
      default: return buildCategoryReport();
    }
  }

  function buildMachineWiseReport() {
    const assets = STATE.filtered.assets || [];
    const grouped = groupBy(assets, function (asset) {
      return asset.item_code || asset.item_name || asset.asset_name || "Unspecified equipment";
    });
    const rows = Object.keys(grouped).map(function (machine) {
      const groupAssets = grouped[machine];
      const assetNames = new Set(groupAssets.map(function (asset) { return asset.name; }));
      const units = sumAssetUnits(groupAssets);
      const working = sumAssetUnits(groupAssets.filter(isOperationalAsset));
      const down = sumAssetUnits(groupAssets.filter(function (asset) { return /out of order|not working/i.test(String(asset.status || "")); }));
      const ages = groupAssets.map(function (asset) {
        const months = ageInMonths(asset.purchase_date || asset.available_for_use_date);
        return months == null ? null : months / 12;
      }).filter(function (value) { return value != null; });
      const repairs = (STATE.filtered.repairs || []).filter(function (repair) { return assetNames.has(repair.asset); });
      const complaints = (STATE.filtered.issues || []).filter(function (issue) {
        const meta = getLifeHelpdeskTicketMeta(issue);
        if (meta.asset && assetNames.has(meta.asset)) return true;
        const text = normalize([issue.subject, issue.description].join(" "));
        return groupAssets.some(function (asset) { return text.indexOf(normalize(asset.name)) !== -1; });
      });
      return {
        machine: machine,
        category: uniqueSorted(groupAssets.map(function (asset) { return asset.asset_category; }).filter(Boolean)).join(", ") || "—",
        machineryCategory: uniqueSorted(groupAssets.map(function (asset) { return asset.custom_machinery_assets_category; }).filter(Boolean)).join(", ") || "—",
        vendor: uniqueSorted(groupAssets.map(function (asset) { return asset.supplier; }).filter(Boolean)).join(", ") || "—",
        locations: uniqueSorted(groupAssets.map(function (asset) { return getLifeBranchName(asset.location) || asset.location; }).filter(Boolean)).length,
        units: units,
        working: working,
        down: down,
        availability: percentage(working, units),
        averageAge: ages.length ? ages.reduce(function (total, value) { return total + value; }, 0) / ages.length : null,
        cost: sum(groupAssets, getAssetCost),
        bookValue: sum(groupAssets, getAssetBookValue),
        complaints: complaints.length,
        repairSpend: sum(repairs, getRepairCost)
      };
    }).sort(function (a, b) { return b.units - a.units || a.machine.localeCompare(b.machine); });
    const columns = [
      { key: "machine", label: "Machine / Equipment" },
      { key: "category", label: "Asset Category" },
      { key: "machineryCategory", label: "Machinery Category" },
      { key: "vendor", label: "Vendor / OEM" },
      { key: "locations", label: "Locations", type: "number" },
      { key: "units", label: "Units", type: "number" },
      { key: "working", label: "Working", type: "number" },
      { key: "down", label: "Down", type: "number" },
      { key: "availability", label: "Availability", type: "number", render: function (row) { return badgeHtml(row.availability + "%", row.availability >= 90 ? "ok" : row.availability >= 75 ? "warn" : "bad"); } },
      { key: "averageAge", label: "Avg Age", type: "number", render: function (row) { return row.averageAge == null ? "—" : row.averageAge.toFixed(1) + " yr"; } },
      { key: "cost", label: "Asset Cost", type: "number", render: function (row) { return formatAmount(row.cost); } },
      { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } },
      { key: "complaints", label: "Complaints", type: "number" },
      { key: "repairSpend", label: "Repair Spend", type: "number", render: function (row) { return formatAmount(row.repairSpend); } }
    ];
    return {
      summaryHtml: noticeHtml("Machine-wise master", "Grouped from real Asset records. Sessions, useful-life targets and criticality are intentionally omitted when no confirmed source field exists.", "info"),
      tableHtml: renderDataTable("report", "Machine-wise Master", columns, rows, { pageSize: PAGE_SIZE, tableClass: "la-fleet-report" }),
      exportData: { title: "Machine-wise Master", columns: columns.map(function (column) { return column.label; }), rows: rows.map(function (row) { return [row.machine, row.category, row.machineryCategory, row.vendor, row.locations, row.units, row.working, row.down, row.availability, row.averageAge == null ? "" : row.averageAge.toFixed(1), row.cost, row.bookValue, row.complaints, row.repairSpend]; }) }
    };
  }

  function reportMachineryAssets() {
    return (STATE.filtered.assets || []).filter(function (asset) {
      return normalize(asset.asset_category || "") === "machinery";
    });
  }

  function buildMachineryLocationReport() {
    const rows = buildAssetGroupSummary(reportMachineryAssets(), "location", "No Location");
    return reportResult("Branch-wise Machinery Master", groupSummaryColumns("Branch / Location"), rows, ["Branch / Location", "Machinery Records", "Operational", "In Maintenance", "Out of Order", "Retired", "Asset Cost", "Book Value", "Depreciation"]);
  }

  function buildMachineryCategoryReport() {
    const rows = buildAssetGroupSummary(reportMachineryAssets(), "custom_machinery_assets_category", "Not Set");
    return reportResult("Treatment / Machinery Category Position", groupSummaryColumns("Machinery Category"), rows, ["Machinery Category", "Machinery Records", "Operational", "In Maintenance", "Out of Order", "Retired", "Asset Cost", "Book Value", "Depreciation"]);
  }

  function buildAvailabilityMatrixReport() {
    const grouped = groupBy(reportMachineryAssets(), function (asset) {
      const machine = asset.item_code || asset.item_name || asset.asset_name || "Unspecified Machinery";
      const branch = getLifeBranchName(asset.location) || asset.location || "No Location";
      return machine + "\u0001" + branch;
    });
    const rows = Object.keys(grouped).map(function (key) {
      const assets = grouped[key];
      const parts = key.split("\u0001");
      const units = sumAssetUnits(assets);
      const working = sumAssetUnits(assets.filter(isOperationalAsset));
      const down = sumAssetUnits(assets.filter(function (asset) { return /out of order|not working/i.test(String(asset.status || "")); }));
      return { machine: parts[0], location: parts[1], category: uniqueSorted(assets.map(function (asset) { return asset.custom_machinery_assets_category; }).filter(Boolean)).join(", ") || "—", records: assets.length, units: units, working: working, down: down, availability: percentage(working, units) };
    }).sort(function (a, b) { return a.location.localeCompare(b.location) || a.machine.localeCompare(b.machine); });
    const columns = [
      { key: "machine", label: "Machine / Equipment" }, { key: "category", label: "Machinery Category" }, { key: "location", label: "Branch / Location" },
      { key: "records", label: "Asset Records", type: "number" }, { key: "units", label: "Units", type: "number" }, { key: "working", label: "Working", type: "number" }, { key: "down", label: "Down", type: "number" },
      { key: "availability", label: "Availability", type: "number", render: function (row) { return badgeHtml(row.availability + "%", row.availability >= 90 ? "ok" : row.availability >= 75 ? "warn" : "bad"); } }
    ];
    return reportResult("Availability Matrix — Machinery × Location", columns, rows, columns.map(function (column) { return column.label; }), function (row) { return [row.machine, row.category, row.location, row.records, row.units, row.working, row.down, row.availability]; });
  }

  function buildDisposalReport() {
    const rows = (STATE.filtered.assets || []).filter(function (asset) {
      return /sold|scrapped|cancelled|retired|disposed|condemned/i.test(String(asset.status || "")) || Boolean(asset.disposal_date);
    }).map(function (asset) {
      return { name: asset.name, assetName: asset.asset_name || asset.item_name || asset.name, category: asset.asset_category || "—", location: getLifeBranchName(asset.location) || asset.location || "—", status: asset.status || "—", disposalDate: asset.disposal_date || "", cost: getAssetCost(asset), bookValue: getAssetBookValue(asset) };
    });
    const columns = [
      { key: "name", label: "Asset ID" }, { key: "assetName", label: "Asset Name" }, { key: "category", label: "Category" }, { key: "location", label: "Branch" }, { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } },
      { key: "disposalDate", label: "Disposal Date", render: function (row) { return formatDate(row.disposalDate); } }, { key: "cost", label: "Asset Cost", type: "number", render: function (row) { return formatAmount(row.cost); } }, { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } },
      { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Asset" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
    ];
    return reportResult("Disposal & Condemnation Register", columns, rows, columns.slice(0, 8).map(function (column) { return column.label; }), function (row) { return [row.name, row.assetName, row.category, row.location, row.status, row.disposalDate, row.cost, row.bookValue]; });
  }

  function buildComplaintAgeReport() {
    const rows = (STATE.filtered.issues || []).map(function (issue) {
      const meta = getLifeHelpdeskTicketMeta(issue);
      const closed = ["closed", "resolved"].indexOf(normalize(issue.status || "")) !== -1;
      return { name: issue.name, subject: issue.subject || meta.issue || "—", branch: meta.branch || "—", priority: issue.priority || "—", status: issue.status || "—", opened: issue.opening_date || issue.creation || "", ageDays: daysSince(issue.opening_date || issue.creation), position: closed ? "Closed / Resolved" : "Open" };
    }).sort(function (a, b) { return b.ageDays - a.ageDays; });
    const columns = [
      { key: "name", label: "Complaint ID" }, { key: "subject", label: "Complaint" }, { key: "branch", label: "Branch" }, { key: "priority", label: "Priority" }, { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } },
      { key: "opened", label: "Raised On", render: function (row) { return formatDateTime(row.opened); } }, { key: "ageDays", label: "Age", type: "number", render: function (row) { return row.ageDays + " day(s)"; } }, { key: "position", label: "Position" },
      { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Issue" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
    ];
    return {
      summaryHtml: noticeHtml("Complaint ageing", "Age is calculated from the real Issue opening/creation date. No SLA result is invented because a confirmed SLA deadline field is not loaded.", "info"),
      tableHtml: renderDataTable("report", "Complaint Ageing", columns, rows, { pageSize: PAGE_SIZE }),
      exportData: { title: "Complaint Ageing", columns: columns.slice(0, 8).map(function (column) { return column.label; }), rows: rows.map(function (row) { return [row.name, row.subject, row.branch, row.priority, row.status, row.opened, row.ageDays, row.position]; }) }
    };
  }

  function buildRepeatFailureReport() {
    const assetsByName = {};
    (STATE.filtered.assets || []).forEach(function (asset) { assetsByName[asset.name] = asset; });
    const grouped = groupBy((STATE.filtered.repairs || []).filter(function (repair) { return Boolean(repair.asset); }), function (repair) { return repair.asset; });
    const rows = Object.keys(grouped).filter(function (assetName) { return grouped[assetName].length > 1; }).map(function (assetName) {
      const repairs = grouped[assetName];
      const asset = assetsByName[assetName] || {};
      return { asset: assetName, assetName: asset.asset_name || asset.item_name || repairs[0].asset_name || "—", location: getLifeBranchName(asset.location) || asset.location || "—", failures: repairs.length, firstFailure: repairs.map(function (repair) { return repair.failure_date || repair.creation; }).filter(Boolean).sort()[0] || "", lastFailure: repairs.map(function (repair) { return repair.failure_date || repair.creation; }).filter(Boolean).sort().slice(-1)[0] || "", repairCost: sum(repairs, getRepairCost) };
    }).sort(function (a, b) { return b.failures - a.failures; });
    const columns = [{ key: "asset", label: "Asset ID" }, { key: "assetName", label: "Asset Name" }, { key: "location", label: "Branch" }, { key: "failures", label: "Repair Records", type: "number" }, { key: "firstFailure", label: "First Failure", render: function (row) { return formatDate(row.firstFailure); } }, { key: "lastFailure", label: "Latest Failure", render: function (row) { return formatDate(row.lastFailure); } }, { key: "repairCost", label: "Repair Cost", type: "number", render: function (row) { return formatAmount(row.repairCost); } }, { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Asset" data-docname="' + escapeAttribute(row.asset) + '">Open</button>'; } }];
    return {
      summaryHtml: sourceAvailable("repairs") ? "" : noticeHtml("Asset Repair access unavailable", "Repeat failures cannot be calculated because Asset Repair is not permission-visible to this user.", "warn"),
      tableHtml: renderDataTable("report", "Repeat-failure Machines", columns, rows, { pageSize: PAGE_SIZE }),
      exportData: { title: "Repeat-failure Machines", columns: columns.slice(0, 7).map(function (column) { return column.label; }), rows: rows.map(function (row) { return [row.asset, row.assetName, row.location, row.failures, row.firstFailure, row.lastFailure, row.repairCost]; }) }
    };
  }

  function buildVisitReport(mode) {
    const visits = (STATE.filtered.maintenance || []).slice();
    if (mode === "technician") {
      const grouped = groupBy(visits, function (visit) { return visit.technician_name || visit.technician_email || "Not Assigned"; });
      const rows = Object.keys(grouped).map(function (technician) {
        const items = grouped[technician];
        const completed = items.filter(function (visit) { return /completed|closed|done/i.test(String(visit.status || "")); }).length;
        return { technician: technician, visits: items.length, completed: completed, pending: items.length - completed, serviceCost: sum(items, function (visit) { return toNumber(visit.service_cost); }), nextVisit: items.map(function (visit) { return visit.next_visit_date; }).filter(Boolean).sort()[0] || "" };
      }).sort(function (a, b) { return b.visits - a.visits; });
      const columns = [{ key: "technician", label: "Technician" }, { key: "visits", label: "Visits", type: "number" }, { key: "completed", label: "Completed", type: "number" }, { key: "pending", label: "Pending", type: "number" }, { key: "serviceCost", label: "Service Cost", type: "number", render: function (row) { return formatAmount(row.serviceCost); } }, { key: "nextVisit", label: "Next Visit", render: function (row) { return formatDate(row.nextVisit); } }];
      return reportResult("Technician Performance", columns, rows, columns.map(function (column) { return column.label; }), function (row) { return [row.technician, row.visits, row.completed, row.pending, row.serviceCost, row.nextVisit]; });
    }
    let rows = visits.map(function (visit) { return { name: visit.name, technician: visit.technician_name || visit.technician_email || "—", asset: visit.asset || "—", assetName: visit.asset_name || "—", branch: getLifeBranchName(visit.branch__location) || visit.branch__location || "—", visitType: visit.visit_type || "—", scheduled: visit.scheduled_date || "", status: visit.status || "—", nextVisit: visit.next_visit_date || "", cost: toNumber(visit.service_cost) };
    });
    if (mode === "preventive") rows = rows.filter(function (row) { return Boolean(row.nextVisit); }).sort(function (a, b) { return compareValues(a.nextVisit, b.nextVisit); });
    const columns = [{ key: "name", label: "Visit ID" }, { key: "technician", label: "Technician" }, { key: "asset", label: "Asset ID" }, { key: "assetName", label: "Asset Name" }, { key: "branch", label: "Branch" }, { key: "visitType", label: "Visit Type" }, { key: "scheduled", label: "Scheduled", render: function (row) { return formatDate(row.scheduled); } }, { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } }, { key: "nextVisit", label: "Next Visit", render: function (row) { return formatDate(row.nextVisit); } }, { key: "cost", label: "Service Cost", type: "number", render: function (row) { return formatAmount(row.cost); } }, { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Technicians And Visits" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }];
    return reportResult(mode === "preventive" ? "Preventive Visits Due & Overdue" : "Visit Register", columns, rows, columns.slice(0, 10).map(function (column) { return column.label; }), function (row) { return [row.name, row.technician, row.asset, row.assetName, row.branch, row.visitType, row.scheduled, row.status, row.nextVisit, row.cost]; });
  }

  function buildUnavailableReport(title, message) {
    return {
      summaryHtml: noticeHtml(title, message, "warn"),
      tableHtml: "",
      exportData: { title: title, columns: [], rows: [] }
    };
  }

  function buildGroupedAssetReport(field, title, firstLabel) {
    const rows = buildAssetGroupSummary(STATE.filtered.assets || [], field, "Not Set");
    return reportResult(title, groupSummaryColumns(firstLabel), rows, [firstLabel, "Assets", "Operational", "In Maintenance", "Out of Order", "Retired", "Asset Cost", "Book Value", "Depreciation"]);
  }

  function buildNotWorkingReport() {
    const rows = (STATE.filtered.assets || []).filter(function (asset) {
      return /out of order|not working/i.test(String(asset.status || ""));
    }).map(function (asset) {
      return { name: asset.name, assetName: asset.asset_name || asset.item_name || asset.name, category: asset.asset_category || "—", location: getLifeBranchName(asset.location) || asset.location || "—", status: asset.status || "—", bookValue: getAssetBookValue(asset) };
    });
    const columns = [
      { key: "name", label: "Asset ID" }, { key: "assetName", label: "Asset Name" }, { key: "category", label: "Category" }, { key: "location", label: "Branch / Location" },
      { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } },
      { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } },
      { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Asset" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
    ];
    return reportResult("Not-working Asset Register", columns, rows, columns.slice(0, 6).map(function (column) { return column.label; }), function (row) { return [row.name, row.assetName, row.category, row.location, row.status, row.bookValue]; });
  }

  function buildComplaintReport() {
    const rows = (STATE.filtered.issues || []).map(function (issue) {
      const meta = getLifeHelpdeskTicketMeta(issue);
      return { name: issue.name, subject: issue.subject || meta.issue || "—", category: meta.category || meta.group || "—", branch: meta.branch || "—", priority: issue.priority || "—", status: issue.status || "—", opened: issue.opening_date || issue.creation || "" };
    });
    const columns = [
      { key: "name", label: "Complaint ID" }, { key: "subject", label: "Complaint" }, { key: "category", label: "Category" }, { key: "branch", label: "Branch" }, { key: "priority", label: "Priority" },
      { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } }, { key: "opened", label: "Raised On", render: function (row) { return formatDateTime(row.opened); } },
      { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Issue" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
    ];
    return reportResult("Complaint Master", columns, rows, columns.slice(0, 7).map(function (column) { return column.label; }), function (row) { return [row.name, row.subject, row.category, row.branch, row.priority, row.status, row.opened]; });
  }

  function buildCheckReport(failuresOnly) {
    let rows = (STATE.filtered.checks || []).map(function (check) {
      return { name: check.name, asset: check.asset || "—", assetName: check.asset_name || "—", location: getLifeBranchName(check.location) || check.location || "—", checkType: check.check_type || "—", result: check.overall_result || "—", checkedOn: check.check_date || check.creation || "", remark: check.overall_remark || "—" };
    });
    if (failuresOnly) rows = rows.filter(function (row) { return /fail|attention/i.test(row.result); });
    const columns = [
      { key: "name", label: "Check ID" }, { key: "asset", label: "Asset ID" }, { key: "assetName", label: "Asset Name" }, { key: "location", label: "Branch" }, { key: "checkType", label: "Check Type" },
      { key: "result", label: "Result", render: function (row) { return statusBadge(row.result); } }, { key: "checkedOn", label: "Checked On", render: function (row) { return formatDate(row.checkedOn); } }, { key: "remark", label: "Remark" },
      { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="LIFE Asset Check" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
    ];
    return reportResult(failuresOnly ? "Weekly Check Failure Analysis" : "Weekly Check Compliance", columns, rows, columns.slice(0, 8).map(function (column) { return column.label; }), function (row) { return [row.name, row.asset, row.assetName, row.location, row.checkType, row.result, row.checkedOn, row.remark]; });
  }

  function buildCategoryAssetReport(categoryNeedle, title) {
    const rows = (STATE.filtered.assets || []).filter(function (asset) {
      return normalize([asset.asset_category, asset.item_name, asset.item_code].join(" ")).indexOf(normalize(categoryNeedle)) !== -1;
    }).map(function (asset) {
      return { name: asset.name, assetName: asset.asset_name || asset.item_name || asset.name, location: getLifeBranchName(asset.location) || asset.location || "—", custodian: asset.custodian || "—", status: asset.status || "—", purchaseDate: asset.purchase_date || "", cost: getAssetCost(asset), bookValue: getAssetBookValue(asset) };
    });
    const columns = [
      { key: "name", label: "Asset ID" }, { key: "assetName", label: "Asset Name" }, { key: "location", label: "Branch / Location" }, { key: "custodian", label: "Custodian" },
      { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } }, { key: "purchaseDate", label: "Purchase Date", render: function (row) { return formatDate(row.purchaseDate); } },
      { key: "cost", label: "Asset Cost", type: "number", render: function (row) { return formatAmount(row.cost); } }, { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } },
      { key: "open", label: "Open", sortable: false, render: function (row) { return '<button type="button" class="la-button la-button-small" data-doctype="Asset" data-docname="' + escapeAttribute(row.name) + '">Open</button>'; } }
    ];
    return reportResult(title, columns, rows, columns.slice(0, 8).map(function (column) { return column.label; }), function (row) { return [row.name, row.assetName, row.location, row.custodian, row.status, row.purchaseDate, row.cost, row.bookValue]; });
  }

  function buildCategoryReport() {
    const assets = STATE.filtered.assets || [];
    const grouped = groupBy(assets, function (asset) { return asset.asset_category || "Uncategorised"; });
    const rows = Object.keys(grouped).map(function (category) {
      const groupAssets = grouped[category];
      const assetNames = new Set(groupAssets.map(function (asset) { return asset.name; }));
      const units = sumAssetUnits(groupAssets);
      const working = sumAssetUnits(groupAssets.filter(isOperationalAsset));
      const down = sumAssetUnits(groupAssets.filter(function (asset) {
        return /out of order|not working/i.test(String(asset.status || ""));
      }));
      const ages = groupAssets.map(function (asset) {
        const months = ageInMonths(asset.purchase_date || asset.available_for_use_date);
        return months == null ? null : months / 12;
      }).filter(function (value) { return value != null; });
      const repairs = (STATE.filtered.repairs || []).filter(function (repair) { return assetNames.has(repair.asset); });
      const checks = (STATE.filtered.checks || []).filter(function (check) { return assetNames.has(check.asset); });
      const complaints = (STATE.filtered.issues || []).filter(function (issue) {
        const meta = getLifeHelpdeskTicketMeta(issue);
        if (meta.asset && assetNames.has(meta.asset)) return true;
        const text = normalize([issue.subject, issue.description, issue.resolution_details].join(" "));
        return groupAssets.some(function (asset) { return text.indexOf(normalize(asset.name)) !== -1; });
      });
      const openComplaints = complaints.filter(function (issue) {
        return ["closed", "resolved"].indexOf(normalize(issue.status || "")) === -1;
      }).length;
      const passedChecks = checks.filter(function (check) { return normalize(check.overall_result || "") === "pass"; }).length;
      return {
        group: category,
        itemTypes: uniqueSorted(groupAssets.map(function (asset) { return asset.item_code || asset.item_name || asset.asset_name; }).filter(Boolean)).length,
        units: units,
        working: working,
        down: down,
        availability: percentage(working, units),
        averageAge: ages.length ? ages.reduce(function (total, value) { return total + value; }, 0) / ages.length : null,
        cost: sum(groupAssets, getAssetCost),
        bookValue: sum(groupAssets, getAssetBookValue),
        complaints: complaints.length,
        openComplaints: openComplaints,
        repairSpend: sum(repairs, getRepairCost),
        checkScore: percentage(passedChecks, checks.length),
        checkCount: checks.length
      };
    }).sort(function (a, b) { return b.units - a.units; });

    const columns = [
      { key: "group", label: "Category", render: function (row) { return '<span class="la-fleet-category">' + escapeHtml(row.group) + '</span>'; } },
      { key: "itemTypes", label: "Item Types", type: "number" },
      { key: "units", label: "Units", type: "number" },
      { key: "working", label: "Working", type: "number" },
      { key: "down", label: "Down", type: "number" },
      { key: "availability", label: "Availability", type: "number", render: function (row) { return badgeHtml(row.availability + "%", row.availability >= 90 ? "ok" : row.availability >= 75 ? "warn" : "bad"); } },
      { key: "averageAge", label: "Avg Age", type: "number", render: function (row) { return row.averageAge == null ? "—" : row.averageAge.toFixed(1) + " yr"; } },
      { key: "cost", label: "Asset Cost", type: "number", render: function (row) { return formatAmount(row.cost); } },
      { key: "bookValue", label: "Book Value", type: "number", render: function (row) { return formatAmount(row.bookValue); } },
      { key: "complaints", label: "Complaints", type: "number" },
      { key: "openComplaints", label: "Open", type: "number" },
      { key: "repairSpend", label: "Repair Spend", type: "number", render: function (row) { return formatAmount(row.repairSpend); } },
      { key: "checkScore", label: "Check Score", type: "number", render: function (row) { return row.checkCount ? row.checkScore + "%" : "—"; } }
    ];

    return {
      summaryHtml: noticeHtml("A · Fleet & Availability", "Calculated from real Asset, LIFE Asset Check, Issue and Asset Repair records in the active master filter. Missing optional sources remain blank instead of using PDF sample data.", "info"),
      tableHtml: renderDataTable("report", "A · Fleet & Availability — Category Position", columns, rows, { pageSize: PAGE_SIZE, tableClass: "la-fleet-report" }),
      exportData: {
        title: "Fleet and Availability by Category",
        columns: ["Category", "Item Types", "Units", "Working", "Down", "Availability %", "Average Age Years", "Asset Cost", "Book Value", "Complaints", "Open Complaints", "Repair Spend", "Check Score %"],
        rows: rows.map(function (row) { return [row.group, row.itemTypes, row.units, row.working, row.down, row.availability, row.averageAge == null ? "" : row.averageAge.toFixed(1), row.cost, row.bookValue, row.complaints, row.openComplaints, row.repairSpend, row.checkCount ? row.checkScore : ""]; })
      }
    };
  }

  function buildLocationReport() {
