      { key: "purchaseDate", label: "Purchase Date", render: function (row) { return formatDate(row.purchaseDate); } },
      { key: "status", label: "Status", render: function (row) { return statusBadge(row.status); } },
      { key: "cost", label: "Asset Cost", type: "number", render: function (row) { return formatAmount(row.cost); } },
      { key: "depreciation", label: "Depreciation", type: "number", render: function (row) { return formatAmount(row.depreciation); } },
      { key: "depreciatedPercent", label: "Depreciated %", type: "number", render: function (row) { return row.depreciatedPercent + "%"; } },
