    ];

    const summary = '<div class="la-grid la-grid-3" style="margin-bottom:13px">' +
      kpiHtml("Total Asset Cost", formatAmount(sum(rows, function (row) { return row.cost; })), rows.length + " asset(s)", "₹", "gold") +
      kpiHtml("Accumulated Depreciation", formatAmount(sum(rows, function (row) { return row.depreciation; })), "Calculated from asset cost less book value", "↓", "warn") +
      kpiHtml("Current Book Value", formatAmount(sum(rows, function (row) { return row.bookValue; })), "Filtered asset portfolio", "₹", "ok") +
      "</div>";

    return {
      summaryHtml: summary,
