      exportData: {
        title: "Asset Financial Position",
        columns: ["Asset", "Asset Name", "Category", "Location", "Purchase Date", "Status", "Asset Cost", "Depreciation", "Depreciated %", "Book Value"],
        rows: rows.map(function (row) { return [row.name, row.assetName, row.category, row.location, row.purchaseDate, row.status, row.cost, row.depreciation, row.depreciatedPercent, row.bookValue]; })
      }
    };
