  function buildMaintenanceRepairReport() {
    const maintenanceByAsset = groupBy(STATE.filtered.maintenance, function (row) { return row.asset_name; });
    const repairByAsset = groupBy(STATE.filtered.repairs, function (row) { return row.asset; });

    const rows = STATE.filtered.assets.map(function (asset) {
      const maintenance = maintenanceByAsset[asset.name] || [];
      const repairs = repairByAsset[asset.name] || [];
      return {
        name: asset.name,
        assetName: asset.asset_name || asset.item_name || asset.name,
        category: asset.asset_category || "",
        location: getLifeBranchName(asset.location),
        maintenanceLogs: maintenance.length,
        overdueMaintenance: maintenance.filter(isMaintenanceAttention).length,
        repairRecords: repairs.length,
        pendingRepairs: repairs.filter(function (row) { return row.repair_status === "Pending"; }).length,
        repairCost: sum(repairs, getRepairCost),
        assetCost: getAssetCost(asset),
        repairPercent: percentage(sum(repairs, getRepairCost), getAssetCost(asset))
      };
    }).filter(function (row) {
      return row.maintenanceLogs || row.repairRecords;
    }).sort(function (a, b) {
      if (b.pendingRepairs !== a.pendingRepairs) return b.pendingRepairs - a.pendingRepairs;
      if (b.overdueMaintenance !== a.overdueMaintenance) return b.overdueMaintenance - a.overdueMaintenance;
      return b.repairCost - a.repairCost;
    });

    const columns = [
      { key: "name", label: "Asset", render: function (row) { return assetButton(row.name, row.assetName); } },
      { key: "category", label: "Category / Location", render: dualCell("category", "location") },
      { key: "maintenanceLogs", label: "Maintenance Logs", type: "number" },
      { key: "overdueMaintenance", label: "Overdue", type: "number", render: function (row) { return row.overdueMaintenance ? badgeHtml(row.overdueMaintenance, "bad") : "0"; } },
      { key: "repairRecords", label: "Repairs", type: "number" },
      { key: "pendingRepairs", label: "Pending", type: "number", render: function (row) { return row.pendingRepairs ? badgeHtml(row.pendingRepairs, "warn") : "0"; } },
      { key: "repairCost", label: "Repair Cost", type: "number", render: function (row) { return formatAmount(row.repairCost); } },
      { key: "repairPercent", label: "Repair % of Cost", type: "number", render: function (row) { return row.repairPercent + "%"; } }
    ];

    return reportResult(
      "Maintenance and Repair Exposure",
      columns,
      rows,
      ["Asset", "Asset Name", "Category", "Location", "Maintenance Logs", "Overdue Maintenance", "Repair Records", "Pending Repairs", "Repair Cost", "Asset Cost", "Repair % of Cost"],
      function (row) {
        return [row.name, row.assetName, row.category, row.location, row.maintenanceLogs, row.overdueMaintenance, row.repairRecords, row.pendingRepairs, row.repairCost, row.assetCost, row.repairPercent];
      }
    );
