  function buildInsuranceReport() {
    const today = startOfDay(new Date());
    const rows = STATE.filtered.assets.filter(function (asset) { return Boolean(asset.insurance_end_date); }).map(function (asset) {
      const end = parseDate(asset.insurance_end_date);
      return {
        name: asset.name,
        assetName: asset.asset_name || asset.item_name || asset.name,
        location: getLifeBranchName(asset.location),
        policy: asset.policy_number || "",
        insurer: asset.insurer || "",
        insuredValue: toNumber(asset.insured_value),
        startDate: asset.insurance_start_date || "",
        endDate: asset.insurance_end_date || "",
        daysRemaining: end ? dateDiffDays(today, end) : null,
        status: end && end < today ? "Expired" : (end && end <= addDays(today, 30) ? "Expiring Soon" : "Active")
      };
    }).sort(function (a, b) {
      return (a.daysRemaining == null ? 999999 : a.daysRemaining) - (b.daysRemaining == null ? 999999 : b.daysRemaining);
    });

    const columns = [
      { key: "name", label: "Asset", render: function (row) { return assetButton(row.name, row.assetName); } },
      { key: "location", label: "Location" },
      { key: "policy", label: "Policy Number" },
      { key: "insurer", label: "Insurer" },
      { key: "insuredValue", label: "Insured Value", type: "number", render: function (row) { return formatAmount(row.insuredValue); } },
      { key: "startDate", label: "Start Date", render: function (row) { return formatDate(row.startDate); } },
      { key: "endDate", label: "End Date", render: function (row) { return dateAlertHtml(row.endDate, row.status !== "Active"); } },
      { key: "daysRemaining", label: "Days Remaining", type: "number", render: function (row) { return row.daysRemaining == null ? "—" : row.daysRemaining; } },
      { key: "status", label: "Insurance Status", render: function (row) { return badgeHtml(row.status, row.status === "Expired" ? "bad" : row.status === "Expiring Soon" ? "warn" : "ok"); } }
    ];

    return reportResult(
      "Insurance Expiry Report",
      columns,
      rows,
      ["Asset", "Asset Name", "Location", "Policy Number", "Insurer", "Insured Value", "Start Date", "End Date", "Days Remaining", "Insurance Status"],
      function (row) { return [row.name, row.assetName, row.location, row.policy, row.insurer, row.insuredValue, row.startDate, row.endDate, row.daysRemaining, row.status]; }
    );
