  function buildAgeReport() {
    const bands = [
      { label: "Under 1 Year", min: 0, max: 12 },
      { label: "1–3 Years", min: 12, max: 36 },
      { label: "3–5 Years", min: 36, max: 60 },
      { label: "5–7 Years", min: 60, max: 84 },
      { label: "Over 7 Years", min: 84, max: Infinity },
      { label: "Purchase Date Missing", min: null, max: null }
    ];

    const rows = bands.map(function (band) {
      const assets = STATE.filtered.assets.filter(function (asset) {
        const age = ageInMonths(asset.purchase_date || asset.available_for_use_date);
        if (band.min == null) return age == null;
        return age != null && age >= band.min && age < band.max;
      });
      const cost = sum(assets, getAssetCost);
      const bookValue = sum(assets, getAssetBookValue);
      return {
        group: band.label,
        count: assets.length,
        operational: assets.filter(isOperationalAsset).length,
        maintenance: assets.filter(function (asset) { return asset.status === "In Maintenance"; }).length,
        outOfOrder: assets.filter(function (asset) { return asset.status === "Out of Order"; }).length,
        retired: assets.filter(isRetiredAsset).length,
        cost: cost,
        bookValue: bookValue,
        depreciation: Math.max(0, cost - bookValue)
      };
    });

    const columns = groupSummaryColumns("Age Band");
    return reportResult("Asset Age Analysis", columns, rows, ["Age Band", "Assets", "Operational", "In Maintenance", "Out of Order", "Retired", "Asset Cost", "Book Value", "Depreciation"]);
  }

