  function reportResult(title, columns, rows, exportColumns, exportMapper) {
    const mapper = exportMapper || function (row) {
      return [row.group, row.count, row.operational, row.maintenance, row.outOfOrder, row.retired || 0, row.cost, row.bookValue, row.depreciation];
    };

    return {
      summaryHtml: "",
      tableHtml: renderDataTable("report", title, columns, rows, { pageSize: PAGE_SIZE }),
      exportData: {
        title: title,
        columns: exportColumns,
        rows: rows.map(mapper)
      }
    };
  }

  function renderDataTable(tableId, title, columns, sourceRows, options) {
    const settings = options || {};
    const pageSize = settings.pageSize || PAGE_SIZE;
    const rows = sourceRows.slice();
    const sort = STATE.tableSort[tableId];

    if (sort && sort.key) {
      rows.sort(function (a, b) {
        const av = a[sort.key];
        const bv = b[sort.key];
        const comparison = compareValues(av, bv);
        return sort.direction === "desc" ? -comparison : comparison;
      });
    }

    const pageCount = Math.max(1, Math.ceil(rows.length / pageSize));
    const currentPage = Math.min(Math.max(1, STATE.tablePage[tableId] || 1), pageCount);
    STATE.tablePage[tableId] = currentPage;

    const start = (currentPage - 1) * pageSize;
    const pageRows = rows.slice(start, start + pageSize);

    const header = columns.map(function (column) {
      const sortable = column.sortable !== false && column.key;
      const classes = [
        column.type === "number" ? "is-number" : "",
        column.type === "center" ? "is-center" : "",
        column.className || ""
      ].filter(Boolean).join(" ");
      const activeSort = sort && sort.key === column.key;
      const indicator = activeSort ? (sort.direction === "asc" ? "▲" : "▼") : "↕";
      const attrs = sortable
        ? ' data-action="table-sort" data-table-id="' + escapeAttribute(tableId) + '" data-sort-key="' + escapeAttribute(column.key) + '"'
        : "";
      return '<th class="' + classes + '"' + attrs + ">" + escapeHtml(column.label) + (sortable ? '<span class="la-sort-indicator">' + indicator + "</span>" : "") + "</th>";
    }).join("");

    const bodyRows = pageRows.map(function (row) {
      const rowClasses = [];
      const rowAttributes = [];

      if (settings.rowClass) {
        rowClasses.push(settings.rowClass);
      }

      let rowActionConfig = null;
      if (typeof settings.rowActionForRow === "function") {
        rowActionConfig = settings.rowActionForRow(row);
      } else if (settings.rowAction) {
        rowActionConfig = {
          action: settings.rowAction,
          dataKey: settings.rowDataKey || "",
          dataAttribute: settings.rowDataAttribute || "row-value"
        };
      }

      if (rowActionConfig && rowActionConfig.action) {
        const dataKey = rowActionConfig.dataKey || "";
        const dataAttribute = rowActionConfig.dataAttribute || "row-value";
        const dataValue = Object.prototype.hasOwnProperty.call(rowActionConfig, "dataValue")
          ? rowActionConfig.dataValue
          : (dataKey ? row[dataKey] : "");

        rowAttributes.push(
          'data-action="' + escapeAttribute(rowActionConfig.action) + '"'
        );
        rowAttributes.push(
          'data-' + dataAttribute + '="' +
          escapeAttribute(dataValue == null ? "" : dataValue) +
          '"'
        );
        rowAttributes.push('role="button"');
        rowAttributes.push('tabindex="0"');
      }

      const rowClassAttribute = rowClasses.length
        ? ' class="' + rowClasses.join(" ") + '"'
        : "";

      const rowAttributeText = rowAttributes.length
        ? " " + rowAttributes.join(" ")
        : "";

      return "<tr" + rowClassAttribute + rowAttributeText + ">" +
        columns.map(function (column) {
          const classes = [
            column.type === "number" ? "is-number" : "",
            column.type === "center" ? "is-center" : "",
            column.className || ""
          ].filter(Boolean).join(" ");

          const rendered = column.render
            ? column.render(row)
            : formatCellValue(row[column.key], column.type);

          return '<td class="' + classes + '">' +
            (rendered == null || rendered === "" ? "—" : rendered) +
          "</td>";
        }).join("") +
      "</tr>";
    }).join("");

    const tableClass = settings.tableClass
      ? " " + escapeAttribute(settings.tableClass)
      : "";

    const empty = rows.length === 0
      ? '<div class="la-empty-state"><div><div class="la-empty-icon">∅</div><div class="la-empty-title">No records found</div><div class="la-empty-note">Adjust the master filters or confirm that the logged-in user has permission to read these records.</div></div></div>'
      : '<div class="la-table-wrap"><table class="la-table' + tableClass + '"><thead><tr>' + header + "</tr></thead><tbody>" + bodyRows + "</tbody></table></div>";

    const pagination = rows.length === 0 ? "" : [
      '<div class="la-pagination">',
      '<div class="la-pagination-note">Showing ' + formatNumber(start + 1) + "–" + formatNumber(Math.min(start + pageSize, rows.length)) + " of " + formatNumber(rows.length) + "</div>",
      '<button type="button" class="la-page-button" data-action="table-page" data-table-id="' + escapeAttribute(tableId) + '" data-page-number="1"' + (currentPage === 1 ? " disabled" : "") + ">«</button>",
      '<button type="button" class="la-page-button" data-action="table-page" data-table-id="' + escapeAttribute(tableId) + '" data-page-number="' + (currentPage - 1) + '"' + (currentPage === 1 ? " disabled" : "") + ">‹</button>",
      '<span class="la-record-note">Page ' + currentPage + " of " + pageCount + "</span>",
      '<button type="button" class="la-page-button" data-action="table-page" data-table-id="' + escapeAttribute(tableId) + '" data-page-number="' + (currentPage + 1) + '"' + (currentPage === pageCount ? " disabled" : "") + ">›</button>",
      '<button type="button" class="la-page-button" data-action="table-page" data-table-id="' + escapeAttribute(tableId) + '" data-page-number="' + pageCount + '"' + (currentPage === pageCount ? " disabled" : "") + ">»</button>",
      "</div>"
    ].join("");

    return [
      '<div class="la-table-shell">',
      '<div class="la-table-toolbar"><div class="la-table-title">' + escapeHtml(title) + '<span class="la-table-count">' + formatNumber(rows.length) + " record(s)</span></div></div>",
      empty,
      pagination,
      "</div>"
    ].join("");
  }

  function changeTablePage(tableId, pageNumber) {
    if (!tableId || !Number.isFinite(pageNumber)) return;
    STATE.tablePage[tableId] = Math.max(1, pageNumber);
    renderCurrentPage();
  }

  function changeTableSort(tableId, sortKey) {
    if (!tableId || !sortKey) return;
    const current = STATE.tableSort[tableId];
    STATE.tableSort[tableId] = {
      key: sortKey,
      direction: current && current.key === sortKey && current.direction === "asc" ? "desc" : "asc"
    };
    STATE.tablePage[tableId] = 1;
    renderCurrentPage();
  }

  function compareValues(a, b) {
    if (a == null && b == null) return 0;
    if (a == null) return 1;
    if (b == null) return -1;

    const an = Number(a);
    const bn = Number(b);
    if (Number.isFinite(an) && Number.isFinite(bn) && String(a).trim() !== "" && String(b).trim() !== "") {
      return an - bn;
    }

    const ad = parseDate(a);
    const bd = parseDate(b);
    if (ad && bd && /^\d{4}-\d{2}-\d{2}/.test(String(a)) && /^\d{4}-\d{2}-\d{2}/.test(String(b))) {
      return ad.getTime() - bd.getTime();
    }

    return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: "base" });
  }

  function renderSimpleSummaryTable(tableId, title, rows, columns, pageSize) {
    return renderDataTable(tableId, title, columns, rows, { pageSize: pageSize || 8 });
  }

  function renderAttentionTable(rows) {
    const columns = [
      { key: "priority", label: "Priority", render: function (row) { return badgeHtml(row.priority, row.tone); } },
      { key: "type", label: "Attention Type" },
      { key: "asset", label: "Asset", render: function (row) { return row.asset ? assetButton(row.asset, row.assetName) : "—"; } },
      { key: "date", label: "Relevant Date", render: function (row) { return dateAlertHtml(row.date, true); } },
      { key: "detail", label: "Details", render: clampCell("detail") },
      { key: "reference", label: "Reference", render: function (row) { return row.doctype && row.reference ? documentButton(row.doctype, row.reference, row.reference) : "—"; } }
    ];
    return renderDataTable("attention", "Attention Queue", columns, rows, { pageSize: 10 });
  }

  function renderRecentActivityCard() {
    const rows = STATE.filtered.activities.slice().sort(function (a, b) {
      return compareValues(b.date, a.date);
    }).slice(0, 12);

    const content = rows.length
      ? timelineHtml(rows.map(function (row) {
        return {
          date: row.date,
          type: "Activity",
          title: row.subject || "Asset activity",
          body: row.user ? "Recorded by " + row.user : "",
          reference: row.name,
          tone: "info"
        };
      }))
      : emptyStateHtml("No activity records", sourceAvailable("activities") ? "No Asset Activity records match the selected period." : "Asset Activity is unavailable to this user.");

    return cardHtml("Recent Asset Activity", "Latest activity records in the selected period", content);
  }

  function renderSourceStatusCard() {
    const keys = Object.keys(SOURCE_DEFINITIONS);
    const content = '<div class="la-source-list">' + keys.map(function (key) {
      const source = STATE.sources[key] || { ok: false, count: 0, error: "Not loaded" };
      return '<div class="la-source-item">' +
        '<div class="la-source-icon ' + (source.ok ? "is-ok" : "is-bad") + '">' + (source.ok ? "✓" : "!") + "</div>" +
        "<div><div class=\"la-source-name\">" + escapeHtml(SOURCE_DEFINITIONS[key].doctype) + "</div>" +
        '<div class="la-source-status" title="' + escapeAttribute(source.error || "") + '">' +
        (source.ok
          ? formatNumber(source.count) + " record(s) loaded"
          : source.skipped
            ? "Not queried — safe mode"
            : "Unavailable / no permission") +
        "</div></div></div>";
    }).join("") + "</div>";

    return cardHtml("Live Data Sources", "No generated or sample records are used", content);
  }

  function buildAttentionRows(overdueMaintenance, pendingRepairs, insuranceAlerts, depreciationDue) {
    const rows = [];

    overdueMaintenance.forEach(function (row) {
      rows.push({
        priority: "High",
        tone: "bad",
        type: "Maintenance Overdue",
        asset: row.asset_name || "",
        assetName: row.item_name || row.item_code || "",
        date: row.due_date || "",
        detail: row.task_name || row.maintenance_type || row.description || "Maintenance due date passed",
        doctype: "Technicians And Visits",
        reference: row.name
      });
    });

    pendingRepairs.forEach(function (row) {
      rows.push({
        priority: "High",
        tone: "bad",
        type: "Pending Repair",
        asset: row.asset || "",
        assetName: row.asset_name || "",
        date: row.failure_date || "",
        detail: stripHtml(row.description || "Repair is still pending"),
        doctype: "Asset Repair",
        reference: row.name
      });
    });

    insuranceAlerts.forEach(function (asset) {
      const expired = isDatePast(asset.insurance_end_date);
      rows.push({
        priority: expired ? "High" : "Medium",
        tone: expired ? "bad" : "warn",
        type: expired ? "Insurance Expired" : "Insurance Expiring",
        asset: asset.name,
        assetName: asset.asset_name || asset.item_name || "",
        date: asset.insurance_end_date,
        detail: [asset.policy_number, asset.insurer].filter(Boolean).join(" · ") || "Insurance policy requires attention",
        doctype: "Asset",
        reference: asset.name
      });
    });

    depreciationDue.forEach(function (asset) {
      rows.push({
        priority: "Medium",
        tone: "warn",
        type: "Depreciation Due",
        asset: asset.name,
        assetName: asset.asset_name || asset.item_name || "",
        date: asset.next_depreciation_date,
        detail: asset.depreciation_method || "Next depreciation date reached",
        doctype: "Asset",
        reference: asset.name
      });
    });

    return rows.sort(function (a, b) {
      const priorityOrder = { High: 0, Medium: 1, Low: 2 };
      if (priorityOrder[a.priority] !== priorityOrder[b.priority]) return priorityOrder[a.priority] - priorityOrder[b.priority];
      return compareValues(a.date, b.date);
    });
  }

  function buildAssetGroupSummary(assets, field, emptyLabel) {
    const grouped = groupBy(assets, function (asset) { return asset[field] || emptyLabel; });
    return Object.keys(grouped).map(function (group) {
      const groupAssets = grouped[group];
      const cost = sum(groupAssets, getAssetCost);
      const bookValue = sum(groupAssets, getAssetBookValue);
      return {
        group: group,
        count: groupAssets.length,
        operational: groupAssets.filter(isOperationalAsset).length,
        maintenance: groupAssets.filter(function (asset) { return asset.status === "In Maintenance"; }).length,
        outOfOrder: groupAssets.filter(function (asset) { return asset.status === "Out of Order"; }).length,
        retired: groupAssets.filter(isRetiredAsset).length,
        cost: cost,
        bookValue: bookValue,
        depreciation: Math.max(0, cost - bookValue)
      };
    }).sort(function (a, b) {
      if (b.count !== a.count) return b.count - a.count;
      return a.group.localeCompare(b.group, undefined, { numeric: true, sensitivity: "base" });
    });
  }

  function getMachineTransferHistory(assetName) {
    const linkedTransferNames = new Set((STATE.data.machineryRequests || []).filter(function (request) {
      return request.allocated_asset === assetName && request.machinery_transfer;
    }).map(function (request) { return request.machinery_transfer; }));
    return (STATE.data.machineryTransfers || []).filter(function (transfer) {
      return linkedTransferNames.has(transfer.name);
    }).map(function (transfer) {
      const request = (STATE.data.machineryRequests || []).find(function (row) {
        return row.allocated_asset === assetName && row.machinery_transfer === transfer.name;
      }) || {};
      const status = transfer.workflow_state || transfer.transfer_status || "Not Set";
      const raisedOn = transfer.request_date_and_time || transfer.creation || request.creation || "";
      const arrivedOn = /received|installed|completed/i.test(String(status))
        ? (transfer.modified || "")
        : "";
      return {
        name: transfer.name,
        request: request.name || "",
        sourceBranch: canonicalBranchDisplayName(transfer.source_branch || request.allocated_source_branch || request.preferred_source_branch || ""),
        targetBranch: canonicalBranchDisplayName(transfer.target_branch || request.requesting_branch || ""),
        sourceWarehouse: transfer.source_warehouse || request.source_warehouse || "",
        targetWarehouse: transfer.target_warehouse || request.target_warehouse || "",
        status: status,
        raisedOn: raisedOn,
        arrivedOn: arrivedOn,
        eventDate: arrivedOn || raisedOn || transfer.modified || "",
        remarks: transfer.remarks || request.additional_remarks || ""
      };
    }).sort(function (a, b) {
      return String(a.eventDate || "").localeCompare(String(b.eventDate || ""));
    });
  }

  function machineJourneyHtml(asset, transfers) {
    const currentBranch = getLifeBranchName(asset.location) || "Current branch not set";
    const firstSource = transfers.length ? transfers[0].sourceBranch : "";
    const initialBranch = firstSource || currentBranch;
    const stops = [{
      branch: initialBranch,
      label: "Purchased / first recorded",
      date: asset.purchase_date || asset.available_for_use_date || asset.creation,
      reference: asset.name
    }];
    transfers.forEach(function (transfer) {
      if (!transfer.targetBranch) return;
      stops.push({
        branch: transfer.targetBranch,
        label: transfer.status,
        date: transfer.arrivedOn || transfer.raisedOn,
        reference: transfer.name
      });
    });
    if (!stops.length || normalizeBranchText(stops[stops.length - 1].branch) !== normalizeBranchText(currentBranch)) {
      stops.push({ branch: currentBranch, label: "Current Asset location", date: asset.modified, reference: asset.name });
    }
    const journey = transfers.length ? '<div class="la-machine-journey">' + stops.map(function (stop, index) {
      return '<div class="la-machine-journey-stop">' + (index ? '<div class="la-machine-journey-arrow">→</div>' : '') +
        '<div class="la-machine-journey-node' + (index === stops.length - 1 ? ' is-current' : '') + '">' +
          '<small>' + escapeHtml(index === 0 ? "Starting position" : "Transfer " + index) + '</small>' +
          '<b>' + escapeHtml(stop.branch || "Branch not recorded") + '</b>' +
          '<span>' + escapeHtml(formatDateTime(stop.date)) + '</span>' +
          '<span>' + escapeHtml(stop.label || "") + '</span>' +
          '<span>' + escapeHtml(stop.reference || "") + '</span>' +
        '</div></div>';
    }).join("") + '</div>' : '';
    const rows = transfers.length ? transfers.map(function (transfer) {
      return '<tr><td>' + escapeHtml(transfer.name) + '</td><td>' + escapeHtml(transfer.sourceBranch || "—") + '</td><td>' + escapeHtml(transfer.targetBranch || "—") + '</td><td>' + escapeHtml(formatDateTime(transfer.raisedOn)) + '</td><td>' + escapeHtml(transfer.arrivedOn ? formatDateTime(transfer.arrivedOn) : "Not completed") + '</td><td>' + escapeHtml(transfer.status) + '</td></tr>';
    }).join("") : '<tr><td colspan="6">No Machinery Transfer linked to this Asset yet.</td></tr>';
    const summary = [
      ["Purchase Date", formatDate(asset.purchase_date)],
      ["Purchase Amount", formatAmount(toNumber(asset.gross_purchase_amount || asset.purchase_amount || getAssetCost(asset)))],
      ["Current Branch", currentBranch],
      ["Transfers", transfers.length],
      ["Starting Position", initialBranch, formatDateTime(asset.purchase_date || asset.available_for_use_date || asset.creation)]
    ];
    const summaryHtml = '<div class="la-360-journey-summary">' + summary.map(function (item, index) {
      return '<div class="la-360-journey-summary-card' + (index === 4 ? ' is-start' : '') + '"><small>' + escapeHtml(item[0]) + '</small><b>' + escapeHtml(String(item[1])) + '</b>' + (item[2] ? '<span>' + escapeHtml(item[2]) + '</span>' : '') + '</div>';
    }).join("") + '</div>';
    return summaryHtml + journey + '<div class="la-table-wrap"><table class="la-machine-history-table"><thead><tr><th>Transfer</th><th>From Branch</th><th>To Branch</th><th>Raised / Sent On</th><th>Received / Completed On</th><th>Status</th></tr></thead><tbody>' + rows + '</tbody></table></div>';
  }

  function machine360DirectoryHtml(assets) {
    const rows = assets.map(function (asset) {
      return '<button type="button" class="la-360-directory-row" data-action="asset360" data-asset-name="' + escapeAttribute(asset.name) + '"><span class="la-360-directory-id">' + escapeHtml(asset.name) + '</span><span class="la-360-directory-name">' + escapeHtml(asset.asset_name || asset.item_name || "Unnamed Machine") + '<small>' + escapeHtml(asset.custom_machinery_assets_category || asset.asset_category || "Machinery") + '</small></span><span class="la-360-directory-branch">' + escapeHtml(getLifeBranchName(asset.location)) + '</span><span class="la-360-directory-status">' + escapeHtml(asset.status || "Not Set") + '</span><span class="la-360-directory-open">Open 360 →</span></button>';
    }).join("");
    return '<section class="la-360-directory"><div class="la-360-directory-head"><b>Machinery Directory</b><span>' + formatNumber(assets.length) + ' permission-visible machine(s)</span></div>' + rows + '</section>';
  }

  function machine360ProfileHtml(asset, checks, complaints, visits, repairs, transfers, totalRepairCost, overdueMaintenance) {
    const ageMonths = ageInMonths(asset.purchase_date || asset.available_for_use_date);
    const ageText = ageMonths == null ? "Not recorded" : (ageMonths < 12 ? ageMonths + " month(s)" : (ageMonths / 12).toFixed(1) + " yrs");
    return [
      '<section class="la-360-profile">',
      '<div class="la-360-profile-head"><div><h2>' + escapeHtml(asset.asset_name || asset.item_name || asset.name) + '</h2><p>' + escapeHtml(asset.name + " · " + (asset.custom_machinery_assets_category || asset.asset_category || "Machinery") + " · " + getLifeBranchName(asset.location)) + '</p></div><span class="la-360-status">' + escapeHtml(asset.status || "Not Set") + '</span></div>',
      '<div class="la-360-metrics">',
      machine360MetricHtml("Age", ageText, "Purchased " + formatDate(asset.purchase_date)),
      machine360MetricHtml("Checks", checks.length, "LIFE Asset Check"),
      machine360MetricHtml("Complaints", complaints.length, "Linked Issue records"),
      machine360MetricHtml("Repair Spend", formatAmount(totalRepairCost), repairs.length + " repair(s) · " + visits.length + " visit(s)"),
      machine360MetricHtml("Book Value", formatAmount(getAssetBookValue(asset)), "Cost " + formatAmount(getAssetCost(asset))),
      machine360MetricHtml("Transfers", transfers.length, overdueMaintenance + " maintenance attention"),
      '</div></section>'
    ].join("");
  }

  function machine360MetricHtml(label, value, note) {
    return '<div class="la-360-metric"><small>' + escapeHtml(label) + '</small><b title="' + escapeAttribute(String(value)) + '">' + escapeHtml(String(value)) + '</b><span>' + escapeHtml(note || "") + '</span></div>';
  }

  function machine360RecordSectionsHtml(checks, complaints, visits) {
    function section(title, count, headers, rows, emptyText) {
      return '<section class="la-360-section"><div class="la-360-section-title"><span>' + escapeHtml(title) + '</span><small>' + formatNumber(count) + ' record(s)</small></div>' + (rows ? '<div class="la-table-wrap"><table class="la-360-table"><thead><tr>' + headers.map(function (header) { return '<th>' + escapeHtml(header) + '</th>'; }).join("") + '</tr></thead><tbody>' + rows + '</tbody></table></div>' : '<div class="la-360-empty">' + escapeHtml(emptyText) + '</div>') + '</section>';
    }
    const complaintRows = (complaints || []).slice(0, 50).map(function (row) {
      return '<tr><td>' + escapeHtml(row.name) + '</td><td>' + escapeHtml(formatDate(row.opening_date || row.creation)) + '</td><td>' + escapeHtml(row.subject || "—") + '</td><td>' + escapeHtml(row.priority || "—") + '</td><td>' + escapeHtml(row.status || "—") + '</td><td><button type="button" class="la-button la-button-small la-button-primary" data-action="open-complaint-detail" data-complaint-name="' + escapeAttribute(row.name) + '">Open</button></td></tr>';
    }).join("");
    const checkRows = (checks || []).slice(0, 50).map(function (row) {
      return '<tr><td>' + escapeHtml(row.name) + '</td><td>' + escapeHtml(formatDate(row.check_date || row.creation)) + '</td><td>' + escapeHtml(row.check_type || "—") + '</td><td>' + escapeHtml(row.machine_condition || "—") + '</td><td>' + escapeHtml(row.overall_result || "—") + '</td><td>' + escapeHtml(row.checked_by || "—") + '</td><td><button type="button" class="la-button la-button-small la-button-primary" data-action="open-check-detail" data-check-name="' + escapeAttribute(row.name) + '">Open</button></td></tr>';
    }).join("");
    const visitRows = (visits || []).slice(0, 50).map(function (row) {
      return '<tr><td>' + escapeHtml(row.name) + '</td><td>' + escapeHtml(formatDate(row.scheduled_date || row.creation)) + '</td><td>' + escapeHtml(row.visit_type || row.maintenance_type || "—") + '</td><td>' + escapeHtml(row.technician_name || row.assigned_to || "—") + '</td><td>' + escapeHtml(row.status || derivedMaintenanceStatus(row)) + '</td><td>' + escapeHtml(formatAmount(toNumber(row.service_cost))) + '</td><td><button type="button" class="la-button la-button-small la-button-primary" data-action="open-technician-visit-detail" data-visit-name="' + escapeAttribute(row.name) + '">Open</button></td></tr>';
    }).join("");
    return [
      section("Complaint History", complaints.length, ["Complaint", "Date", "Subject", "Priority", "Status", "Open"], complaintRows, "No complaint has been raised for this machine."),
      section("Inspection & Check History", checks.length, ["Check", "Date", "Type", "Condition", "Result", "Checked By", "Open"], checkRows, "No LIFE Asset Check has been recorded for this machine."),
      section("Technician Visit History", visits.length, ["Visit", "Date", "Type", "Technician", "Status", "Cost", "Open"], visitRows, "No technician visit has been recorded for this machine.")
    ].join("");
  }

  function buildAssetTimeline(asset, repairs, checks, maintenance, complaints, movementItems, movementMap, schedules, activities, machineTransfers) {
    const timeline = [];

    timeline.push({
      date: asset.purchase_date || asset.creation,
      type: "Asset",
      title: "Asset acquired / created",
      body: [asset.asset_name, asset.item_name, asset.supplier].filter(Boolean).join(" · "),
      reference: asset.name,
      tone: "gold"
    });

    if (asset.available_for_use_date) {
      timeline.push({
        date: asset.available_for_use_date,
        type: "Asset",
        title: "Available for use",
        body: getLifeBranchName(asset.location),
        reference: asset.name,
        tone: "ok"
      });
    }

    repairs.forEach(function (row) {
      timeline.push({
        date: row.failure_date || row.creation,
        type: "Repair",
        title: "Repair " + (row.repair_status || "recorded"),
        body: stripHtml(row.description || "") + (getRepairCost(row) ? " · " + formatAmount(getRepairCost(row)) : ""),
        reference: row.name,
        doctype: "Asset Repair",
        tone: row.repair_status === "Pending" ? "bad" : row.repair_status === "Completed" ? "ok" : "warn"
      });

      if (row.completion_date) {
        timeline.push({
          date: row.completion_date,
          type: "Repair",
          title: "Repair completed",
          body: stripHtml(row.actions_performed || ""),
          reference: row.name,
          doctype: "Asset Repair",
          tone: "ok"
        });
      }
    });

    (checks || []).forEach(function (row) {
      timeline.push({
        date: row.check_date || row.creation || row.modified,
        type: "Check",
        title: (row.check_type || "Asset") + " check · " + (row.overall_result || "Recorded"),
        body: [row.machine_condition, row.checked_by, row.overall_remark].filter(Boolean).join(" · "),
        reference: row.name,
        doctype: "LIFE Asset Check",
        tone: checkResultTone(row.overall_result)
      });
    });

    maintenance.forEach(function (row) {
      timeline.push({
        date: row.completion_date || row.due_date || row.creation,
        type: "Maintenance",
        title: (row.task_name || row.maintenance_type || "Maintenance") + " · " + derivedMaintenanceStatus(row),
        body: stripHtml(row.actions_performed || row.description || ""),
        reference: row.name,
        doctype: "Technicians And Visits",
        tone: derivedMaintenanceStatus(row) === "Overdue" ? "bad" : derivedMaintenanceStatus(row) === "Completed" ? "ok" : "warn"
      });
    });

    (complaints || []).forEach(function (row) {
      timeline.push({
        date: row.opening_date || row.creation || row.modified,
        type: "Complaint",
        title: (row.subject || row.name || "Asset complaint") + " · " + (row.status || "Open"),
        body: [row.priority, stripHtml(row.description || ""), stripHtml(row.resolution_details || "")].filter(Boolean).join(" · "),
        reference: row.name,
        doctype: "Issue",
        tone: /closed|resolved/i.test(String(row.status || "")) ? "ok" : "bad"
      });
    });

    movementItems.forEach(function (item) {
      const movement = movementMap[item.parent] || {};
      timeline.push({
        date: movement.transaction_date || movement.creation,
        type: "Movement",
        title: movement.purpose || "Asset Movement",
        body: [
          item.source_location ? "From " + item.source_location : "",
          item.target_location ? "To " + item.target_location : "",
          item.from_employee ? "From employee " + item.from_employee : "",
          item.to_employee ? "To employee " + item.to_employee : ""
        ].filter(Boolean).join(" · "),
        reference: item.parent,
        doctype: "Asset Movement",
        tone: "info"
      });
    });

    (machineTransfers || []).forEach(function (transfer) {
      timeline.push({
        date: transfer.eventDate,
        type: "Machinery Transfer",
        title: (transfer.sourceBranch || "Unknown branch") + " → " + (transfer.targetBranch || "Unknown branch"),
        body: [transfer.status, transfer.request ? "Request " + transfer.request : "", transfer.remarks].filter(Boolean).join(" · "),
        reference: transfer.name,
        doctype: "Machinery Transfer",
        tone: /completed|received|installed/i.test(String(transfer.status)) ? "ok" : "info"
      });
    });

    schedules.forEach(function (row) {
      timeline.push({
        date: row.modified || row.creation,
        type: "Depreciation",
        title: "Depreciation schedule " + (row.status || docstatusLabel(row.docstatus)),
        body: [row.depreciation_method, row.finance_book, row.total_number_of_depreciations ? row.total_number_of_depreciations + " entries" : ""].filter(Boolean).join(" · "),
        reference: row.name,
        doctype: "Asset Depreciation Schedule",
        tone: "gold"
      });
    });

    activities.forEach(function (row) {
      timeline.push({
        date: row.date || row.creation,
        type: "Activity",
