  function searchableSelectSnapshot(select) {
    if (!select) return;
    select.__lifeAllOptions = Array.from(select.options).map(function (option) {
      return {
        value: option.value,
        text: option.textContent || "",
        disabled: Boolean(option.disabled)
      };
    });
    if (typeof select.__lifeRenderCombo === "function") select.__lifeRenderCombo("", true);
  }

  function enhancePopupSelects(container) {
    if (!container) return;
    container.querySelectorAll("select").forEach(function (select) {
      if (select.dataset.searchEnhanced === "1") return;
      select.dataset.searchEnhanced = "1";

      const field = select.closest(".la-inline-field");
      const label = field && field.querySelector("label")
        ? field.querySelector("label").textContent.replace(/\s*\*\s*$/, "").trim()
        : "option";
      const combo = document.createElement("div");
      combo.className = "la-search-select";
      const input = document.createElement("input");
      input.type = "text";
      input.className = "la-search-select-input";
      input.placeholder = "Select or search " + label + "…";
      input.autocomplete = "off";
      input.setAttribute("role", "combobox");
      input.setAttribute("aria-expanded", "false");
      const arrow = document.createElement("span");
      arrow.className = "la-search-select-arrow";
      arrow.textContent = "▼";
      const menu = document.createElement("div");
      menu.className = "la-search-select-menu";
      menu.setAttribute("role", "listbox");

      select.parentNode.insertBefore(combo, select);
      combo.appendChild(input);
      combo.appendChild(arrow);
      combo.appendChild(menu);
      combo.appendChild(select);

      const selectedText = function () {
        const option = (select.__lifeAllOptions || []).find(function (row) { return row.value === select.value; });
        return option && option.value ? option.text : "";
      };
      const render = function (query, resetInput) {
        const normalizedQuery = normalize(query || "");
        const options = (select.__lifeAllOptions || []).filter(function (option) {
          return option.value && !option.disabled && (!normalizedQuery || normalize(option.text + " " + option.value).indexOf(normalizedQuery) !== -1);
        });
        menu.innerHTML = options.length ? options.map(function (option) {
          return '<button type="button" class="la-search-select-option' + (option.value === select.value ? ' is-active' : '') + '" data-combo-value="' + escapeAttribute(option.value) + '">' + escapeHtml(option.text) + '</button>';
        }).join("") : '<div class="la-search-select-empty">No matching options</div>';
        if (resetInput) input.value = selectedText();
      };
      select.__lifeRenderCombo = render;
      searchableSelectSnapshot(select);

      const openCombo = function () {
        if (select.disabled) return;
        combo.classList.add("is-open");
        input.setAttribute("aria-expanded", "true");
        render(input.value === selectedText() ? "" : input.value, false);
      };
      const closeCombo = function () {
        combo.classList.remove("is-open");
        input.setAttribute("aria-expanded", "false");
        input.value = selectedText();
      };

      input.addEventListener("focus", openCombo);
      input.addEventListener("click", openCombo);
      input.addEventListener("input", function () {
        combo.classList.add("is-open");
        input.setAttribute("aria-expanded", "true");
        render(input.value, false);
      });
      input.addEventListener("keydown", function (event) {
        if (event.key === "Escape") closeCombo();
        if (event.key === "Enter") {
          const first = menu.querySelector("[data-combo-value]");
          if (first) {
            event.preventDefault();
            first.click();
          }
        }
      });
      menu.addEventListener("mousedown", function (event) { event.preventDefault(); });
      menu.addEventListener("click", function (event) {
        const option = event.target.closest("[data-combo-value]");
        if (!option) return;
        select.value = option.dataset.comboValue || "";
        select.dispatchEvent(new Event("change", { bubbles: true }));
        closeCombo();
      });
      input.addEventListener("blur", function () { window.setTimeout(closeCombo, 120); });
      select.addEventListener("change", function () { render("", true); });
    });
  }

