  async function loadFixedAssetItemsForEntry() {
    try {
      const rows = await frappeCall("frappe.client.get_list", {
        doctype: "Item",
        fields: ["name", "item_name", "item_group", "stock_uom", "asset_category", "is_fixed_asset", "disabled"],
        filters: [["is_fixed_asset", "=", 1], ["disabled", "=", 0]],
        order_by: "item_name asc",
        limit_start: 0,
        limit_page_length: MAX_RECORDS
      });
      if (Array.isArray(rows) && rows.length) return rows;
    } catch (error) {
      void 0;
    }

    const seen = {};
    return (STATE.data.assets || []).reduce(function (rows, asset) {
      const code = String(asset.item_code || "").trim();
      if (!code || seen[code]) return rows;
      seen[code] = true;
      rows.push({
        name: code,
        item_name: asset.item_name || asset.asset_name || code,
        asset_category: asset.asset_category || "",
        is_fixed_asset: 1,
        disabled: 0
      });
      return rows;
    }, []).sort(function (a, b) {
      return String(a.item_name || a.name).localeCompare(String(b.item_name || b.name), undefined, { numeric: true, sensitivity: "base" });
    });
  }

