  async function openInlineNewAsset() {
    openModal(
      "New Asset Entry",
      '<div class="la-check-empty">Loading Item masters and permitted locations…</div>',
      '<button type="button" class="la-button" data-action="close-modal">Cancel</button>'
    );

    const itemMasters = await loadNewAssetItemMasters();
    const categories = uniqueSorted((STATE.data.assetCategories || []).map(function (row) {
      return row.name || "";
    }).concat(distinctAssetFormValues("asset_category")).filter(Boolean));
    const companies = distinctAssetFormValues("company");
    // LIFE uses these two controlled Machinery Category values. Keep any
    // existing values visible as well so older Asset records remain editable.
    const machineryCategories = uniqueSorted([
      "Skin",
      "Slimming"
    ].concat(distinctAssetFormValues("custom_machinery_assets_category")));
    const supplierMap = {};
    (itemMasters.suppliers || []).forEach(function (row) {
      const name = String(row.name || "").trim();
      if (name) supplierMap[name] = {
        name: name,
        label: String(row.supplier_name || name).trim() + (row.supplier_name && row.supplier_name !== name ? " · " + name : "")
      };
    });
    distinctAssetFormValues("supplier").forEach(function (name) {
      if (!supplierMap[name]) supplierMap[name] = { name: name, label: name };
    });
    const suppliers = Object.keys(supplierMap).map(function (name) {
      return supplierMap[name];
    }).sort(function (a, b) {
      return a.label.localeCompare(b.label, undefined, { numeric: true, sensitivity: "base" });
    });
    // Asset.location is a Link to Location, not Branch. Preserve the exact
    // Location document ID as the option value and use branch aliases only in
    // the user-facing label. This prevents values such as "S.R. Nagar" from
    // being submitted when the real Location document has a different ID.
    const locationMap = {};
    const addLocation = function (name, label) {
      const exactName = String(name || "").trim();
      if (!exactName || locationMap[exactName]) return;
      const friendly = canonicalBranchDisplayName(label || getLifeBranchName(exactName) || exactName);
      if (!friendly || isTestingBranchName(friendly) || !isBranchAllowedForUser(friendly)) return;
      locationMap[exactName] = {
        name: exactName,
        label: friendly + (normalizeBranchText(friendly) !== normalizeBranchText(exactName) ? " · " + exactName : "")
      };
    };
    (itemMasters.locations || []).forEach(function (row) {
      addLocation(row.name, row.location_name || row.name);
    });
    (STATE.data.assets || []).forEach(function (asset) {
      addLocation(asset.location, getLifeBranchName(asset.location) || asset.location);
    });
    const locations = Object.keys(locationMap).map(function (key) {
      return locationMap[key];
    }).sort(function (a, b) {
      return String(a.label).localeCompare(String(b.label), undefined, { numeric: true, sensitivity: "base" });
    });
    const today = toIsoDate(new Date());

    const optionHtml = function (rows, placeholder, valueGetter, labelGetter) {
      return ['<option value="">' + escapeHtml(placeholder) + '</option>'].concat(rows.map(function (row) {
        const value = valueGetter ? valueGetter(row) : row;
        const label = labelGetter ? labelGetter(row) : row;
        return '<option value="' + escapeAttribute(value) + '">' + escapeHtml(label) + '</option>';
      })).join("");
    };

    const itemGroupOptions = optionHtml(itemMasters.itemGroups, "Select Item Group");
    const uomOptions = optionHtml(itemMasters.uoms, "Select Stock UOM");
    const categoryOptions = optionHtml(categories, "Select Asset Category");
    const companyOptions = optionHtml(companies, "Select Company");
    const locationOptions = optionHtml(locations, "Select Branch / Location", function (row) {
      return row.name;
    }, function (row) {
      return row.label;
    });
    const machineryOptions = optionHtml(machineryCategories, "Not applicable / Select Machinery Category");
    const supplierOptions = optionHtml(suppliers, "No Supplier / Select Supplier", function (row) {
      return row.name;
    }, function (row) {
      return row.label;
    });
    const departmentMap = {};
