          '<div class="la-inline-field la-machinery-request-span-2"><label>Asset Name *</label><input type="text" maxlength="140" placeholder="Enter the name shown on the Asset" required data-new-asset-field="asset_name"></div>',
          '<div class="la-inline-field"><label>Asset Category *</label><select required data-new-asset-field="asset_category">', categoryOptions, '</select></div>',
          '<div class="la-inline-field"><label>Machinery Category <span data-new-asset-machinery-required hidden>*</span></label><select data-new-asset-field="custom_machinery_assets_category">', machineryOptions, '</select></div>',
          '<div class="la-inline-field"><label>Company *</label><select required data-new-asset-field="company">', companyOptions, '</select></div>',
