          '<div class="la-inline-field"><label>Employee</label><select data-new-asset-field="custodian">', employeeOptions, '</select></div>',
          '<div class="la-inline-field"><label>Purchase Date *</label><input type="date" max="', escapeAttribute(today), '" value="', escapeAttribute(today), '" required data-new-asset-field="purchase_date"></div>',
