      if (!selected || !alternative || !selected.value) return;
      alternative.value = "";
      alternative.dispatchEvent(new Event("change", { bubbles: true }));
    };
    if (receiptSelect) receiptSelect.addEventListener("change", function () {
      clearAlternativePurchaseSource(receiptSelect, invoiceSelect);
    });
    if (invoiceSelect) invoiceSelect.addEventListener("change", function () {
      clearAlternativePurchaseSource(invoiceSelect, receiptSelect);
    });
    const assetCategorySelect = form && form.querySelector('[data-new-asset-field="asset_category"]');
    const machineryCategorySelect = form && form.querySelector('[data-new-asset-field="custom_machinery_assets_category"]');
    const machineryRequiredMark = form && form.querySelector("[data-new-asset-machinery-required]");
    const syncMachineryCategoryRequirement = function () {
      if (!assetCategorySelect || !machineryCategorySelect) return;
      const isMachinery = normalize(assetCategorySelect.value) === "machinery";
      machineryCategorySelect.required = isMachinery;
      machineryCategorySelect.disabled = !isMachinery;
      if (!isMachinery) machineryCategorySelect.value = "";
      if (machineryRequiredMark) machineryRequiredMark.hidden = !isMachinery;
      machineryCategorySelect.dispatchEvent(new Event("change", { bubbles: true }));
    };
    if (assetCategorySelect) {
      assetCategorySelect.addEventListener("change", syncMachineryCategoryRequirement);
      syncMachineryCategoryRequirement();
    }
    const employeeSelect = form && form.querySelector('[data-new-asset-field="custodian"]');
    const departmentSelect = form && form.querySelector('[data-new-asset-field="department"]');
    if (employeeSelect && departmentSelect) {
      employeeSelect.addEventListener("change", function () {
        const employee = employees.find(function (row) {
          return String(row.name || "") === String(employeeSelect.value || "");
        });
        if (!employee || !employee.department) return;
        const hasDepartment = Array.from(departmentSelect.options).some(function (option) {
          return option.value === employee.department;
        });
        if (!hasDepartment) {
          const option = document.createElement("option");
          option.value = employee.department;
          option.textContent = employee.department;
          departmentSelect.appendChild(option);
        }
        departmentSelect.value = employee.department;
        departmentSelect.dispatchEvent(new Event("change", { bubbles: true }));
      });
    }
