  async function saveInlineNewAsset(button) {
    const form = STATE.root.querySelector("[data-new-asset-form]");
    if (!form || !button || button.disabled) return;
    const field = function (name) { return form.querySelector('[data-new-asset-field="' + name + '"]'); };
    const value = function (name) { const element = field(name); return element ? String(element.value || "").trim() : ""; };
    const message = form.querySelector("[data-new-asset-message]");
    const required = ["item_code", "item_name", "item_group", "stock_uom", "asset_name", "asset_category", "company", "location", "purchase_date", "available_for_use_date", "asset_quantity", "gross_purchase_amount"];
    const missing = required.filter(function (name) { return !value(name); });
    if (missing.length) {
      if (message) message.textContent = "Complete every required field before submitting the Asset.";
      showToast("Complete every required Asset field.", true);
      return;
    }
    if (normalize(value("asset_category")) === "machinery" && !value("custom_machinery_assets_category")) {
      if (message) message.textContent = "Select Skin or Slimming as the Machinery Category.";
      showToast("Machinery Category is required for Machinery Assets.", true);
      const machineryField = field("custom_machinery_assets_category");
      if (machineryField) machineryField.focus();
      return;
    }

    const grossPurchaseAmount = toNumber(value("gross_purchase_amount"));
    if (!Number.isFinite(grossPurchaseAmount) || grossPurchaseAmount <= 0) {
      if (message) message.textContent = "Gross Purchase Amount must be greater than zero.";
      showToast("Enter a Gross Purchase Amount greater than zero.", true);
      const amountField = field("gross_purchase_amount");
      if (amountField) amountField.focus();
      return;
    }

    const purchaseDate = parseDate(value("purchase_date"));
    const availableDate = parseDate(value("available_for_use_date"));
    if (purchaseDate && availableDate && availableDate < purchaseDate) {
      if (message) message.textContent = "Available For Use Date cannot be before Purchase Date.";
      showToast("Available For Use Date cannot be before Purchase Date.", true);
      return;
    }

    const itemData = {
      doctype: "Item",
      item_code: value("item_code"),
      item_name: value("item_name"),
      item_group: value("item_group"),
      stock_uom: value("stock_uom"),
      is_stock_item: 0,
      is_fixed_asset: 1,
      auto_create_assets: 0,
      asset_category: value("asset_category"),
      disabled: 0
    };

    const purchaseReceipt = value("purchase_receipt");
    const purchaseInvoice = value("purchase_invoice");
    const documentData = {
      doctype: "Asset",
      // A Purchase Receipt/Invoice represents a newly purchased Asset.
      // ERPNext rejects Purchase Invoice when is_existing_asset is enabled.
      is_existing_asset: purchaseReceipt || purchaseInvoice ? 0 : 1,
      item_code: value("item_code"),
      asset_name: value("asset_name"),
      asset_category: value("asset_category"),
      company: value("company"),
      location: value("location"),
      purchase_date: value("purchase_date"),
      available_for_use_date: value("available_for_use_date"),
      asset_quantity: Math.max(1, parseInt(value("asset_quantity"), 10) || 1),
      gross_purchase_amount: grossPurchaseAmount,
      purchase_amount: grossPurchaseAmount,
      // The quick-create form intentionally does not create an incomplete
      // depreciation schedule. ERPNext rejects calculate_depreciation = 1
      // unless the mandatory Finance Books rows are also supplied.
      calculate_depreciation: 0
    };
    if (value("custom_machinery_assets_category")) documentData.custom_machinery_assets_category = value("custom_machinery_assets_category");
    if (value("department")) documentData.department = value("department");
    if (value("custodian")) documentData.custodian = value("custodian");
    if (value("supplier")) documentData.supplier = value("supplier");
    if (purchaseReceipt) documentData.purchase_receipt = purchaseReceipt;
    if (purchaseInvoice) documentData.purchase_invoice = purchaseInvoice;

    button.disabled = true;
    button.textContent = "Creating Item…";
    if (message) message.textContent = "Creating the Fixed Asset Item in ERPNext…";

    let createdItemName = "";
    try {
      let item = null;
      try {
        const existingItemResult = await frappeCall("frappe.client.get_value", {
          doctype: "Item",
          filters: { name: itemData.item_code },
          fieldname: ["name", "is_fixed_asset", "asset_category", "disabled"]
        });
        const existingItem = existingItemResult && (existingItemResult.message || existingItemResult);
        if (existingItem && existingItem.name) {
          if (!Number(existingItem.is_fixed_asset || 0) || Number(existingItem.disabled || 0)) {
            throw new Error("Item " + existingItem.name + " already exists but is not an active Fixed Asset Item. Use a different Item Code.");
          }
          if (existingItem.asset_category && existingItem.asset_category !== itemData.asset_category) {
            throw new Error("Item " + existingItem.name + " already uses Asset Category " + existingItem.asset_category + ". Use a different Item Code.");
          }
          item = existingItem;
        }
      } catch (lookupError) {
        if (/already exists but|already uses Asset Category/.test(String(lookupError && lookupError.message || ""))) throw lookupError;
      }
      if (!item) {
        item = await frappeCall("frappe.client.insert", { doc: itemData });
        createdItemName = item && item.name ? item.name : "";
      }
      if (!item || !item.name) throw new Error("ERPNext did not return the created Item.");
      documentData.item_code = item.name;
      button.textContent = "Creating Asset…";
      if (message) message.textContent = "Item " + item.name + " created. Creating and submitting its Asset…";
      const inserted = await frappeCall("frappe.client.insert", { doc: documentData });
      let saved = inserted;
      if (inserted && inserted.name && Number(inserted.docstatus || 0) === 0) {
        saved = await frappeCall("frappe.client.submit", { doc: inserted });
      }
      closeModal();
      showToast("Item " + item.name + " and Asset " + ((saved && saved.name) || (inserted && inserted.name) || "") + " created successfully.");
      await loadAllData();
      STATE.currentPage = "register";
      renderPage();
    } catch (error) {
      let errorText = error && error.message ? error.message : "Asset could not be created.";
      if (createdItemName) {
        errorText = "Item " + createdItemName + " was created, but the Asset could not be completed: " + errorText + " You can correct the Asset details and submit again; the same Fixed Asset Item will be reused.";
      }
      if (message) message.textContent = errorText;
      showToast(errorText, true);
      button.disabled = false;
      button.textContent = "Create Item & Asset";
    }
  }

