  function technicianVisitField(form, fieldname) {
    const field = form ? form.querySelector('[data-tv-field="' + fieldname + '"]') : null;
    if (!field) return "";
    return String(field.value == null ? "" : field.value).trim();
  }

  function frappeDatetimeValue(value) {
    return value ? String(value).replace("T", " ") + (String(value).length === 16 ? ":00" : "") : "";
  }

  function currentFrappeDatetime() {
    if (window.frappe && frappe.datetime && typeof frappe.datetime.now_datetime === "function") {
      return frappe.datetime.now_datetime();
    }
    const now = new Date();
    return toIsoDate(now) + " " + String(now.getHours()).padStart(2, "0") + ":" + String(now.getMinutes()).padStart(2, "0") + ":" + String(now.getSeconds()).padStart(2, "0");
  }

  async function saveInlineTechnicianVisit(button) {
    const form = STATE.root.querySelector("[data-technician-visit-form]");
    if (!form || (button && button.disabled)) return;

    const required = [
      ["asset", "Select an Asset."],
      ["branch__location", "Select the Branch / Location."],
      ["visit_type", "Select the Visit Type."],
      ["task", "Enter the technician task."],
      ["technician_name", "Enter the Technician Name."],
      ["scheduled_date", "Select the Scheduled Date."]
    ];
    for (let index = 0; index < required.length; index += 1) {
      if (!technicianVisitField(form, required[index][0])) {
        showToast(required[index][1], true);
        const missingField = form.querySelector('[data-tv-field="' + required[index][0] + '"]');
        if (missingField) missingField.focus();
        return;
      }
    }

    const mobile = technicianVisitField(form, "technician_mobile").replace(/\D/g, "");
    if (mobile && !/^[6-9]\d{9}$/.test(mobile)) {
      showToast("Enter a valid 10-digit technician mobile number.", true);
      return;
    }
    const partsRequired = technicianVisitField(form, "parts_required") === "1";
    if (partsRequired && !technicianVisitField(form, "parts_details")) {
      showToast("Enter Parts Details when Parts Required is Yes.", true);
      return;
    }
    const status = technicianVisitField(form, "status") || "Scheduled";
    if (status === "Completed") {
