  async function saveInlineAssetComplaint(button) {
    const form = STATE.root.querySelector("[data-inline-complaint-form]");
    if (!form || (button && button.disabled)) return;
    const branch = inlineOperationField(form, "branch");
    const category = inlineOperationField(form, "category");
    const subject = inlineOperationField(form, "specific_issue");
    const priority = inlineOperationField(form, "priority") || "Medium";
    const details = inlineOperationField(form, "details");
    const assetName = inlineOperationField(form, "asset");
    const resolver = inlineOperationField(form, "resolver");
    const ccToUsers = Array.from(form.querySelectorAll('[data-complaint-cc-user].is-selected')).map(function (field) {
      return String(field.dataset.complaintCcUser || "").trim();
    }).filter(Boolean);
    const ccTo = ccToUsers.join(", ");
    const attachmentField = form.querySelector('[data-operation-field="attachments"]');
    const attachments = attachmentField ? Array.from(attachmentField.files || []) : [];
    if (!branch || !category || !subject || !assetName || !resolver || !details) {
      showToast("Branch, issue category, specific issue, asset, resolver and issue details are required.", true);
      return;
    }
    const asset = getProductionAssets().find(function (row) { return row.name === assetName; });
    const meta = {
      branch: branch,
      category: category,
      issue: subject,
      asset: assetName || "",
      resolver: resolver,
      cc_to: ccTo
    };
    const readable = [
      "Branch: " + branch,
      "Category: " + category,
      "Issue: " + subject,
      asset ? "Asset: " + asset.name + " - " + (asset.asset_name || asset.item_name || "") : "",
      "Tag To: " + resolver,
      ccTo ? "CC To: " + ccTo : "",
      "Details: " + details
    ].filter(Boolean).join("\n");
    const doc = {
      doctype: "Issue",
      naming_series: "ISS-.YYYY.-",
      subject: subject,
      raised_by: getCurrentUserId(),
      status: "Open",
      priority: priority,
      email_cc: ccTo,
      description: "<!--LIFE_TICKET_META:" + JSON.stringify(meta) + "-->\n" + readable
    };

    if (button) { button.disabled = true; button.textContent = "Saving…"; }
    try {
      let saved;
      try {
        const complaintResult = await frappeCall("life_asset_complaint", {
          action: "create",
          branch: branch,
          category: category,
          specific_issue: subject,
          priority: priority,
          details: details,
          asset: assetName,
          resolver: resolver,
          cc_to: ccTo
        });
        if (!complaintResult || complaintResult.ok === false) throw new Error((complaintResult && complaintResult.message) || "Could not save complaint.");
        saved = complaintResult.doc || complaintResult;
      } catch (apiError) {
        if (!String(apiError && apiError.message || "").includes("life_asset_complaint")) throw apiError;
        saved = await frappeCall("frappe.client.insert", { doc: doc });
        try {
          await frappeCall("frappe.desk.form.assign_to.add", {
            doctype: "Issue",
            name: saved.name,
            assign_to: [resolver],
            description: subject
          });
        } catch (assignmentError) {
          void 0;
        }
      }
      for (let index = 0; index < attachments.length; index += 1) {
        await uploadComplaintAttachment(saved.name, attachments[index]);
      }
      closeModal();
      showToast("Complaint " + ((saved && saved.name) || "") + " saved successfully.");
      await loadAllData();
      openPage("repairs");
    } catch (error) {
      showToast(error && error.message ? error.message : "Could not save complaint.", true);
      if (button) { button.disabled = false; button.textContent = "Save Complaint"; }
    }
  }

  async function uploadComplaintAttachment(issueName, file) {
    if (!issueName || !file) return;
    const data = new FormData();
    data.append("file", file, file.name);
    data.append("doctype", "Issue");
    data.append("docname", issueName);
    data.append("is_private", "1");
    const headers = {};
    if (window.frappe && frappe.csrf_token) headers["X-Frappe-CSRF-Token"] = frappe.csrf_token;
    const response = await fetch("/api/method/upload_file", {
      method: "POST",
      credentials: "same-origin",
      headers: headers,
      body: data
    });
    if (!response.ok) throw new Error("Complaint was saved, but attachment " + file.name + " could not be uploaded.");
  }

