  async function ensureRequestWarehouseOptions() {
    if (STATE.sourceWarehouseApiLoaded && (STATE.transferWarehouses || []).length) return;
    let rows = await safeDirectList(
      "Warehouse",
      ["name", "warehouse_name", "is_group", "disabled"],
      [["is_group", "=", 0], ["disabled", "=", 0]],
      "warehouse_name asc",
      1000
    );
    if (!rows.length) {
      try {
        const links = await frappeCall("frappe.desk.search.search_link", {
          doctype: "Warehouse",
          txt: "",
          query: "",
          filters: { is_group: 0, disabled: 0 },
          page_length: 1000,
          reference_doctype: "Machinery Request"
        });
        rows = (Array.isArray(links) ? links : []).map(function (row) {
          const name = row && !Array.isArray(row) ? (row.value || row.name || "") : (Array.isArray(row) ? row[0] : "");
          const label = row && !Array.isArray(row) ? (row.description || row.label || "") : (Array.isArray(row) ? (row[1] || "") : "");
          return { name: name, warehouse_name: stripHtml(label || name), is_group: 0, disabled: 0 };
        }).filter(function (row) { return row.name; });
      } catch (error) {
        rows = [];
      }
    }
    let apiRows = [];
    try {
      const result = await frappeCall("life_get_source_warehouses", {});
      apiRows = Array.isArray(result) ? result : [];
      STATE.sourceWarehouseApiLoaded = true;
    } catch (error) {
      apiRows = [];
    }
    const warehouseMap = new Map();
    (STATE.transferWarehouses || []).concat(rows || []).concat(apiRows).forEach(function (row) {
      if (row && row.name) warehouseMap.set(row.name, row);
    });
    STATE.transferWarehouses = Array.from(warehouseMap.values()).filter(function (row) {
      return normalizeText((row.name || "") + " " + (row.warehouse_name || "")).indexOf("testing") === -1;
    });
  }

  async function ensureSourceMachineryAssets() {
    if (STATE.sourceMachineryAssetsLoaded) return;
    try {
      let result;
      try {
        result = await frappeCall("life_get_machinery_availability", {});
      } catch (availabilityError) {
        void 0;
        result = await frappeCall("life_get_source_machinery_assets", {});
      }
      STATE.sourceMachineryAssets = Array.isArray(result) ? result : [];
      STATE.sourceMachineryAssetsLoaded = true;
    } catch (error) {
      STATE.sourceMachineryAssets = [];
      throw new Error("Machinery availability could not be loaded. Enable the life_get_machinery_availability API Server Script.");
    }
  }

  function requestMachineryAssetOptions(sourceBranch, selectedAsset) {
    const sourceKey = normalizeBranchText(canonicalBranchDisplayName(sourceBranch || ""));
    const assets = (STATE.sourceMachineryAssets || []).filter(function (asset) {
      const branch = canonicalBranchDisplayName(asset.location || "");
      const category = normalize(asset.asset_category || "");
      const status = normalize(asset.status || "");
      return sourceKey && normalizeBranchText(branch) === sourceKey && category === "machinery" && status !== "scrapped" && status !== "sold";
    });
    return ['<option value="">' + (assets.length ? "Select Machinery Asset" : "No Machinery assets found for this warehouse branch") + '</option>'].concat(
      assets.map(function (asset) {
        const label = (asset.asset_name || asset.item_name || asset.name) + " · " + asset.name;
        return '<option value="' + escapeAttribute(asset.name) + '"' + (asset.name === selectedAsset ? ' selected' : '') + ' data-item-code="' + escapeAttribute(asset.item_code || "") + '" data-machinery-category="' + escapeAttribute(asset.custom_machinery_assets_category || "") + '">' + escapeHtml(label) + '</option>';
      })
    ).join("");
  }

  function buildWarehouseOptions(branchValue, selectedWarehouse, sideLabel, autoSelectFirst) {
    const branchKey = normalizeBranchText(canonicalBranchDisplayName(branchValue || ""));
    const matching = (STATE.transferWarehouses || []).filter(function (warehouse) {
      if (!branchKey) return true;
      const warehouseBranch = canonicalBranchDisplayName((warehouse.warehouse_name || "") + " " + (warehouse.name || ""));
      return normalizeBranchText(warehouseBranch) === branchKey;
    });
    const effectiveSelected = selectedWarehouse || (autoSelectFirst && matching.length === 1 ? matching[0].name : "");
    return matching.length
      ? ['<option value="">Select ' + escapeHtml(sideLabel || "Warehouse") + '</option>'].concat(matching.map(function (warehouse) {
          const label = warehouse.warehouse_name || warehouse.name;
          return '<option value="' + escapeAttribute(warehouse.name) + '"' + (warehouse.name === effectiveSelected ? ' selected' : '') + '>' + escapeHtml(warehouseDisplayName(label)) + '</option>';
        })).join("")
      : '<option value="">No permitted ' + escapeHtml(sideLabel || "warehouse") + ' found for this branch</option>';
  }

