  async function applyMachineryRequestAction(requestName, action, button) {
    if (!requestName || !action || (button && button.disabled)) return;
    let values = {};
    if (action === "approve") {
      if (!isMachineryRequestApprover()) return showToast("Only a Sales Manager, Stock Manager or System Manager can approve this request.", true);
      const currentRequest = await getMachineryRequestDocument(requestName);
      const warehouseSourceBranch = canonicalBranchDisplayName(currentRequest.source_warehouse || "");
      const approvedSourceBranch = warehouseSourceBranch && normalizeBranchText(warehouseSourceBranch) !== normalizeBranchText(currentRequest.requesting_branch || "")
        ? warehouseSourceBranch
        : (currentRequest.preferred_source_branch || currentRequest.allocated_source_branch || "");
      values = {
        request_status: "Approved",
        allocated_source_branch: approvedSourceBranch,
        approved_by: getCurrentUserId(),
        approved_on: currentFrappeDatetime()
      };
    } else if (action === "reject") {
      if (!isMachineryRequestApprover()) return showToast("Only a Sales Manager, Stock Manager or System Manager can reject this request.", true);
      const reason = window.prompt("Enter the rejection reason:", "");
      if (reason == null) return;
      if (!String(reason).trim()) return showToast("Rejection reason is required.", true);
      values = {
        request_status: "Rejected",
        rejection_reason: String(reason).trim(),
        rejected_by: getCurrentUserId(),
        rejected_on: currentFrappeDatetime()
      };
    } else {
      return;
    }
    if (button) { button.disabled = true; button.textContent = "Saving…"; }
    try {
      await frappeCall("life_get_machinery_requests", {
        action: action,
        request_name: requestName,
        rejection_reason: action === "reject" ? (values.rejection_reason || "") : ""
      });
      closeModal();
      showToast(requestName + (action === "approve" ? " approved successfully." : " rejected."));
      await loadAllData();
      openPage("approvals");
    } catch (error) {
      showToast(error && error.message ? error.message : "Request action could not be completed.", true);
      if (button) { button.disabled = false; button.textContent = action === "reject" ? "Reject" : "Approve"; }
    }
  }

  async function openTransferFromMachineryRequest(requestName, button) {
    if (!requestName || (button && button.disabled)) return;
    if (button) { button.disabled = true; button.textContent = "Loading…"; }
    try {
      await ensureRequestWarehouseOptions();
      const doc = await getMachineryRequestDocument(requestName);
      if (["Approved", "Asset Allocated"].indexOf(String(doc.request_status || "")) === -1) {
        throw new Error("Stock Manager approval must be completed before creating the Machinery Transfer.");
      }
      const approvedSourceBranch = doc.allocated_source_branch || doc.preferred_source_branch || "";
      if (!approvedSourceBranch || (!isBranchAllowedForUser(approvedSourceBranch) && !currentUserHasAnyRole(["System Manager"]))) {
        throw new Error("Only the approved source branch can allocate the machinery.");
      }
      const branchOptions = '<option value="' + escapeAttribute(approvedSourceBranch) + '" selected>' + escapeHtml(canonicalBranchDisplayName(approvedSourceBranch)) + '</option>';
      const html = '<div class="la-inline-check" data-request-allocation-form data-request-name="' + escapeAttribute(doc.name) + '">' +
        noticeHtml("Source Branch Allocation", "The Stock Manager approved this request for your branch. Confirm the exact Machinery Asset and warehouses, then save the allocation to continue the transfer process.", "info") +
        detailGridHtml([["Request", doc.name], ["Required Item", doc.requested_item || "—"], ["Quantity", doc.quantity || 1], ["Target Branch", doc.requesting_branch || "—"]]) +
        '<div class="la-inline-check-info" style="margin-top:12px">' +
          '<div class="la-inline-field"><label>Allocated Source Branch *</label><select data-operation-field="allocation_source_branch" disabled>' + branchOptions + '</select></div>' +
          '<div class="la-inline-field"><label>Exact Asset *</label><select data-operation-field="allocation_asset" disabled><option value="">Select source branch first</option></select></div>' +
          '<div class="la-inline-field"><label>Source Warehouse *</label><select data-operation-field="allocation_source_warehouse">' + buildWarehouseOptions(doc.preferred_source_branch || "", doc.source_warehouse || "", "Source Warehouse", false) + '</select></div>' +
          '<div class="la-inline-field"><label>Target Warehouse *</label><select data-operation-field="allocation_target_warehouse">' + buildWarehouseOptions(doc.requesting_branch || "", doc.target_warehouse || "", "Target Warehouse", true) + '</select></div>' +
        '</div></div>';
      openModal("Allocate Machinery Request · " + doc.name, html, '<button type="button" class="la-button" data-action="close-modal">Cancel</button><button type="button" class="la-button la-button-primary" data-action="confirm-create-transfer-from-request" data-request-name="' + escapeAttribute(doc.name) + '">Save Source Allocation</button>');
      const form = STATE.root.querySelector("[data-request-allocation-form]");
      const source = form.querySelector('[data-operation-field="allocation_source_branch"]');
      const asset = form.querySelector('[data-operation-field="allocation_asset"]');
      const sourceWarehouse = form.querySelector('[data-operation-field="allocation_source_warehouse"]');
      const refreshSourceAllocation = async function () {
        const usingPreferredSource = normalizeBranchText(source.value || "") === normalizeBranchText(doc.preferred_source_branch || "");
        asset.disabled = true;
        asset.innerHTML = '<option value="">Loading assets…</option>';
        try {
          await ensureSourceMachineryAssets();
          asset.innerHTML = requestMachineryAssetOptions(source.value || "", usingPreferredSource ? (doc.allocated_asset || "") : "");
        } catch (error) {
          asset.innerHTML = '<option value="">Could not load Machinery assets</option>';
          showToast(error && error.message ? error.message : "Could not load Machinery assets.", true);
          return;
        }
        asset.disabled = !source.value;
        searchableSelectSnapshot(asset);
        sourceWarehouse.innerHTML = buildWarehouseOptions(source.value || "", usingPreferredSource ? (doc.source_warehouse || "") : "", "Source Warehouse", false);
        searchableSelectSnapshot(sourceWarehouse);
      };
      if (source.value) await refreshSourceAllocation();
    } catch (error) {
      showToast(error && error.message ? error.message : "Could not open stock allocation.", true);
      if (button) { button.disabled = false; button.textContent = "Approve & Allocate"; }
    }
  }

  async function confirmCreateTransferFromMachineryRequest(requestName, button) {
    const form = STATE.root.querySelector("[data-request-allocation-form]");
    if (!form || !requestName || (button && button.disabled)) return;
    const sourceBranch = inlineOperationField(form, "allocation_source_branch");
    const assetName = inlineOperationField(form, "allocation_asset");
    const sourceWarehouse = inlineOperationField(form, "allocation_source_warehouse");
    const targetWarehouse = inlineOperationField(form, "allocation_target_warehouse");
    if (!sourceBranch || !assetName || !sourceWarehouse || !targetWarehouse) return showToast("Source Branch, exact Asset, Source Warehouse and Target Warehouse are required.", true);
    if (button) { button.disabled = true; button.textContent = "Saving Allocation…"; }
    try {
      const request = await getMachineryRequestDocument(requestName);
      if (String(request.request_status || "") !== "Approved" && String(request.request_status || "") !== "Asset Allocated") throw new Error("This request must be Approved before creating a Machinery Transfer.");
      await frappeCall("life_get_machinery_requests", {
        action: "save_source_allocation",
        request_name: requestName,
        allocated_source_branch: sourceBranch,
        allocated_asset: assetName,
        source_warehouse: sourceWarehouse,
        target_warehouse: targetWarehouse
      });
      closeModal();
      showToast(requestName + " was allocated to " + canonicalBranchDisplayName(sourceBranch) + ". That source branch can now transfer the machinery.");
      await loadAllData();
      openPage("movements");
    } catch (error) {
      showToast(error && error.message ? error.message : "Transfer could not be created.", true);
      if (button) { button.disabled = false; button.textContent = "Approve & Create Transfer"; }
    }
  }

  async function openAllocatedMachineryTransfer(requestName, button, showChecklist) {
    if (!requestName || (button && button.disabled)) return;
    if (button) { button.disabled = true; button.textContent = "Loading…"; }
    try {
      const request = await getMachineryRequestDocument(requestName);
      if (["Approved", "Asset Allocated"].indexOf(String(request.request_status || "")) === -1) {
        throw new Error("This request is not ready for source-branch transfer.");
      }
      if (!isBranchAllowedForUser(request.allocated_source_branch || "") && !currentUserHasAnyRole(["System Manager"])) {
        throw new Error("Only the allocated source branch can transfer this machinery.");
      }
      if (!request.allocated_asset || !request.source_warehouse) {
        throw new Error("Machinery Asset and Source Warehouse must be present on the approved request.");
      }
      if (!showChecklist) {
        await ensureRequestWarehouseOptions();
        const sourceEmployee = await resolveCurrentTransferEmployee();
        const requestedByValue = sourceEmployee && sourceEmployee.name ? sourceEmployee.name : "";
