          '<div class="la-inline-check-info"><label><input type="checkbox" data-checklist-field="bubble_wrap_verified"> Verified Secure</label><label><input type="checkbox" data-checklist-field="bubble_wrap_na"> N/A</label><div class="la-inline-field" style="grid-column:span 2"><label>Total Wrap Layers Applied</label><input type="number" min="0" step="1" data-checklist-value="total_wrap_layers"></div></div>',
          '<div class="la-inline-field"><label>2. Protective Shipping Boxes</label><div>Is the equipment safely nested inside its original flight case or a heavy-duty industrial corrugated box with foam inserts?</div></div>',
          '<div class="la-inline-check-info"><label><input type="checkbox" data-checklist-field="shipping_box_verified"> Verified Secure</label><label><input type="checkbox" data-checklist-field="shipping_box_na"> N/A</label><div class="la-inline-field" style="grid-column:span 2"><label>Box / Serial No</label><input data-checklist-value="box_serial_no"></div></div>',
          '<div class="la-inline-field"><label>3. Probes, Handpieces &amp; Accessories</label><div>List all optical lenses, power cables, keys, foot switches and fiber cables separately.</div></div>',
          '<div class="la-inline-check-info"><label><input type="checkbox" data-checklist-field="all_items_accounted"> All Items Accounted</label><label><input type="checkbox" data-checklist-field="items_missing"> Missing / Indented List</label><div class="la-inline-field" style="grid-column:span 2"><label>Items &amp; Qty Packed</label><textarea rows="3" data-checklist-value="items_qty_packed" placeholder="Example: 1. Power Cable - Qty: 1"></textarea></div></div>',
          transferPhotoUploadHtml(),
          '<label style="display:flex;gap:8px;align-items:flex-start;font-weight:700"><input type="checkbox" data-checklist-field="final_confirmation"> I confirm that the pre-shipping and packaging checklist has been verified.</label>',
        '</div>'
      ].join("");
      openModal("Transfer Approved Machinery · " + request.name, checklistHtml,
        '<button type="button" class="la-button" data-action="close-modal">Cancel</button><button type="button" class="la-button la-button-primary" data-action="confirm-inline-transfer">Complete Protocol &amp; Ready for Dispatch</button>');
      wireTransferPhotoPicker(STATE.root.querySelector("[data-transfer-checklist]"));
    } catch (error) {
      showToast(error && error.message ? error.message : "Could not open the approved transfer.", true);
      if (button) { button.disabled = false; button.textContent = "Transfer Machinery"; }
    }
