  async function openInlineMachineryRequest(prefillAssetName) {
    await ensureRequestWarehouseOptions();
    const lockedRequestBranch = lockedBranchValue();
    const branchRows = LIFE_TRANSFER_BRANCH_IDS.map(function (name) {
      return { name: name, branch: canonicalBranchDisplayName(name) };
    });
    const branchOptions = ['<option value="">Select Requesting Branch</option>'].concat(
      branchRows.map(function (row) {
        return '<option value="' + escapeAttribute(row.name) + '"' +
          (normalizeBranchText(row.name) === normalizeBranchText(lockedRequestBranch || "") ? ' selected' : '') +
          '>' + escapeHtml(row.branch || row.name) + '</option>';
      })
    ).join("");
    const requestBranchField = lockedRequestBranch
      ? '<input value="' + escapeAttribute(canonicalBranchDisplayName(lockedRequestBranch)) + '" readonly>' +
        '<input type="hidden" data-operation-field="request_target_branch" value="' + escapeAttribute(lockedRequestBranch) + '">'
      : '<select data-operation-field="request_target_branch">' + branchOptions + '</select>';
    const requestTargetKey = normalizeBranchText(canonicalBranchDisplayName(lockedRequestBranch || ""));
    const requestSourceWarehouseOptions = ['<option value="">Select Source Warehouse</option>'].concat(
      (STATE.transferWarehouses || []).map(function (warehouse) {
        const sourceBranch = canonicalBranchDisplayName((warehouse.warehouse_name || "") + " " + (warehouse.name || ""));
        if (!sourceBranch || isTestingBranchName(sourceBranch) || normalizeBranchText(sourceBranch) === requestTargetKey) return "";
        const sourceBranchRow = branchRows.find(function (row) {
          return normalizeBranchText(canonicalBranchDisplayName(row.branch || row.name || "")) === normalizeBranchText(sourceBranch);
        });
        if (!sourceBranchRow) return "";
        const sourceBranchId = sourceBranchRow.name;
        const warehouseLabel = warehouse.warehouse_name || warehouse.name;
        return '<option value="' + escapeAttribute(warehouse.name) + '" data-source-branch="' + escapeAttribute(sourceBranchId) + '">' +
          escapeHtml(warehouseLabel) + '</option>';
      }).filter(Boolean)
    ).join("");

    const employeeBranch = canonicalBranchDisplayName(lockedRequestBranch || "");
    let employeeRows = await safeDirectList(
      "Employee",
      ["name", "employee_name", "branch", "status", "user_id"],
      [["status", "=", "Active"]],
      "employee_name asc",
      1000
    );
    employeeRows = (employeeRows || []).filter(function (row) {
      return employeeBranch &&
        normalizeBranchText(canonicalBranchDisplayName(row.branch || "")) ===
        normalizeBranchText(canonicalBranchDisplayName(employeeBranch));
    });
    if (!employeeRows.length && employeeBranch) {
      try {
        const employeeLinks = await frappeCall("frappe.desk.search.search_link", {
          doctype: "Employee",
          txt: "",
          query: "",
          filters: { status: "Active", branch: employeeBranch },
          page_length: 500,
          reference_doctype: "Machinery Request"
        });
        employeeRows = (Array.isArray(employeeLinks) ? employeeLinks : []).map(function (row) {
          return {
            name: row && !Array.isArray(row) ? (row.value || row.name || "") : (Array.isArray(row) ? row[0] : ""),
            employee_name: row && !Array.isArray(row) ? stripHtml(row.description || row.label || "") : (Array.isArray(row) ? stripHtml(row[1] || "") : ""),
            branch: employeeBranch
          };
        }).filter(function (row) { return row.name; });
      } catch (error) {
        employeeRows = [];
      }
    }
    // Branch users may not have general Employee list permission. Their own
    // active Employee record is still the correct Requested By value, so use
    // the already permission-safe current-user resolver as the final fallback.
    if (!employeeRows.length && employeeBranch) {
      const currentEmployee = await resolveCurrentTransferEmployee();
      if (
        currentEmployee &&
        currentEmployee.name &&
        normalizeBranchText(canonicalBranchDisplayName(currentEmployee.branch || employeeBranch)) ===
          normalizeBranchText(canonicalBranchDisplayName(employeeBranch))
      ) {
        employeeRows = [currentEmployee];
      }
    }
    const currentUserLabel = (window.frappe && frappe.user && frappe.user.full_name)
      ? frappe.user.full_name
      : getCurrentUserId();
    const employeeOptions = employeeRows.map(function (row) {
        return row.name ? '<option value="' + escapeAttribute(row.name) + '">' + escapeHtml(row.employee_name || row.name) + '</option>' : '';
      }).join("");
    const employeeField = '<select data-operation-field="request_requested_by"><option value="">Select ' + escapeHtml(employeeBranch || "Branch") + ' Employee</option>' +
      (employeeOptions || '<option value="__CURRENT_USER__" selected>' + escapeHtml(currentUserLabel) + '</option>') + '</select>';

    const earliestRequiredBy = toIsoDate(new Date());
    const html = [
      '<div class="la-inline-check" data-inline-machinery-request>',
        noticeHtml("Machinery Requirement", "Select the source warehouse for this request. HO / Store will verify the supplying branch and allocate the exact Asset after approval.", "info"),
        '<div class="la-machinery-request-grid">',
          '<div class="la-inline-field"><label>Requesting / Target Branch *</label>', requestBranchField, '</div>',
          '<div class="la-inline-field"><label>Requested By *</label>', employeeField, '</div>',
          '<div class="la-inline-field"><label>Required By *</label><div class="la-formatted-date-picker"><input type="text" value="', escapeAttribute(formatDate(earliestRequiredBy)), '" readonly data-formatted-required-by><span aria-hidden="true">▦</span><input type="date" min="', escapeAttribute(earliestRequiredBy), '" value="', escapeAttribute(earliestRequiredBy), '" required data-operation-field="request_required_by"></div><small class="la-cell-sub">Select today or a future date</small></div>',
          '<div class="la-inline-field"><label>Priority *</label><select data-operation-field="request_priority"><option value="">Select Priority</option><option>Low</option><option selected>Medium</option><option>High</option><option>Urgent</option></select></div>',
          '<div class="la-inline-field la-machinery-request-span-2"><label>Source Warehouse *</label><select data-operation-field="request_source_warehouse">', requestSourceWarehouseOptions, '</select></div>',
          '<div class="la-inline-field la-machinery-request-span-2"><label>Machinery Asset *</label><select data-operation-field="request_asset" disabled><option value="">Select Source Warehouse first</option></select></div>',
          '<div class="la-inline-field"><label>Asset Category *</label><input value="Machinery" readonly><input type="hidden" data-operation-field="request_asset_category" value="Machinery"></div>',
          '<div class="la-inline-field"><label>Machinery Category</label><input data-operation-field="request_machinery_category" readonly placeholder="Filled from selected Asset"></div>',
          '<div class="la-inline-field"><label>Quantity *</label><input type="number" min="1" step="1" value="1" data-operation-field="request_quantity"></div>',
          '<div class="la-inline-field"></div>',
          '<div class="la-inline-field la-machinery-request-span-2"><label>Requirement Reason *</label><textarea rows="3" data-operation-field="request_reason" placeholder="Why is this machinery required and how will it be used?"></textarea></div>',
          '<div class="la-inline-field la-machinery-request-span-2"><label>Additional Remarks</label><textarea rows="3" data-operation-field="request_remarks" placeholder="Optional notes for the approving or supplying team"></textarea></div>',
        '</div>',
      '</div>'
    ].join("");
    openModal(
      "Request Machinery",
      html,
      '<button type="button" class="la-button" data-action="close-modal">Cancel</button>' +
      '<button type="button" class="la-button la-button-primary" data-action="save-inline-machinery-request">Submit Machinery Request</button>'
    );
    const requestForm = STATE.root.querySelector("[data-inline-machinery-request]");
    const warehouseSelect = requestForm ? requestForm.querySelector('[data-operation-field="request_source_warehouse"]') : null;
    const assetSelect = requestForm ? requestForm.querySelector('[data-operation-field="request_asset"]') : null;
    const machineryCategoryField = requestForm ? requestForm.querySelector('[data-operation-field="request_machinery_category"]') : null;
    const requiredByPicker = requestForm ? requestForm.querySelector('[data-operation-field="request_required_by"]') : null;
    const requiredByDisplay = requestForm ? requestForm.querySelector('[data-formatted-required-by]') : null;
    if (requiredByPicker && requiredByDisplay) requiredByPicker.addEventListener("change", function () {
      requiredByDisplay.value = formatDate(requiredByPicker.value);
    });
    if (warehouseSelect && assetSelect) {
      warehouseSelect.addEventListener("change", async function () {
        const option = warehouseSelect.selectedIndex >= 0 ? warehouseSelect.options[warehouseSelect.selectedIndex] : null;
        const sourceBranch = option ? String(option.dataset.sourceBranch || "").trim() : "";
        assetSelect.disabled = true;
        assetSelect.innerHTML = '<option value="">Loading Machinery assets…</option>';
        if (machineryCategoryField) machineryCategoryField.value = "";
        if (!sourceBranch) {
          assetSelect.innerHTML = '<option value="">Select Source Warehouse first</option>';
          return;
        }
        try {
          await ensureSourceMachineryAssets();
          assetSelect.innerHTML = requestMachineryAssetOptions(sourceBranch);
          assetSelect.disabled = false;
          searchableSelectSnapshot(assetSelect);
          if (prefillAssetName && Array.from(assetSelect.options).some(function (assetOption) { return assetOption.value === prefillAssetName; })) {
            assetSelect.value = prefillAssetName;
            assetSelect.dispatchEvent(new Event("change", { bubbles: true }));
            prefillAssetName = "";
          }
        } catch (error) {
          assetSelect.innerHTML = '<option value="">Could not load Machinery assets</option>';
          showToast(error && error.message ? error.message : "Could not load Machinery assets.", true);
        }
      });
      assetSelect.addEventListener("change", function () {
        const option = assetSelect.selectedIndex >= 0 ? assetSelect.options[assetSelect.selectedIndex] : null;
        if (machineryCategoryField) machineryCategoryField.value = option ? String(option.dataset.machineryCategory || "") : "";
      });
      if (prefillAssetName) {
        const trackedAsset = (STATE.sourceMachineryAssets || []).find(function (asset) { return asset.name === prefillAssetName; });
        const trackedBranchKey = normalizeBranchText(canonicalBranchDisplayName(trackedAsset ? trackedAsset.location : ""));
        const matchingWarehouse = Array.from(warehouseSelect.options).find(function (option) {
          return option.value && normalizeBranchText(canonicalBranchDisplayName(option.dataset.sourceBranch || "")) === trackedBranchKey;
        });
        if (matchingWarehouse) {
          warehouseSelect.value = matchingWarehouse.value;
          warehouseSelect.dispatchEvent(new Event("change", { bubbles: true }));
        }
      }
    }
  }

  async function saveInlineMachineryRequest(button) {
    const form = STATE.root.querySelector("[data-inline-machinery-request]");
    if (!form || (button && button.disabled)) return;
    const targetBranch = inlineOperationField(form, "request_target_branch");
    const sourceWarehouse = inlineOperationField(form, "request_source_warehouse");
    const sourceWarehouseField = form.querySelector('[data-operation-field="request_source_warehouse"]');
    const selectedWarehouseOption = sourceWarehouseField && sourceWarehouseField.selectedIndex >= 0
      ? sourceWarehouseField.options[sourceWarehouseField.selectedIndex]
      : null;
    const sourceBranch = selectedWarehouseOption ? String(selectedWarehouseOption.dataset.sourceBranch || "").trim() : "";
    const requestedBy = inlineOperationField(form, "request_requested_by");
    const requestedByField = form.querySelector('[data-operation-field="request_requested_by"]');
    const selectedEmployeeOption = requestedByField && requestedByField.selectedIndex >= 0
      ? requestedByField.options[requestedByField.selectedIndex]
      : null;
    const requestedByName = selectedEmployeeOption
      ? String(selectedEmployeeOption.textContent || "").trim()
      : requestedBy;
    const requiredByText = inlineOperationField(form, "request_required_by");
    const requiredByDate = parseDate(requiredByText);
    const requiredBy = requiredByDate ? toIsoDate(requiredByDate) : "";
    const priority = inlineOperationField(form, "request_priority");
    const assetName = inlineOperationField(form, "request_asset");
    const assetField = form.querySelector('[data-operation-field="request_asset"]');
    const selectedAssetOption = assetField && assetField.selectedIndex >= 0 ? assetField.options[assetField.selectedIndex] : null;
    const item = selectedAssetOption ? String(selectedAssetOption.dataset.itemCode || "").trim() : "";
    const assetCategory = inlineOperationField(form, "request_asset_category");
    const machineryCategory = inlineOperationField(form, "request_machinery_category");
    const quantity = Math.max(1, Math.floor(toNumber(inlineOperationField(form, "request_quantity")) || 1));
    const reason = inlineOperationField(form, "request_reason");

    if (requiredByText && !requiredByDate) {
      showToast("Enter Required By in this format: 12-Aug-26.", true);
      const invalidRequiredByField = form.querySelector('[data-operation-field="request_required_by"]');
      if (invalidRequiredByField) invalidRequiredByField.focus();
      return;
    }
    if (requiredBy && requiredBy < toIsoDate(new Date())) {
      showToast("Required By cannot be a past date. Select today or a future date.", true);
      const requiredByField = form.querySelector('[data-operation-field="request_required_by"]');
      if (requiredByField) {
        requiredByField.value = toIsoDate(new Date());
        requiredByField.focus();
      }
      return;
    }
    const remarks = inlineOperationField(form, "request_remarks");
    if (!targetBranch || !sourceBranch || !sourceWarehouse || !requestedBy || !requiredBy || !priority || !assetName || !item || !assetCategory || !reason) {
      showToast("Target branch, source warehouse, Machinery Asset, requested by, required date, priority, asset category and reason are required.", true);
      return;
    }
    if (normalizeBranchText(sourceBranch) === normalizeBranchText(targetBranch)) {
      showToast("Source Branch and Target Branch must be different.", true);
      return;
    }
    const doc = {
      doctype: "Machinery Request",
      naming_series: "MREQ-.YYYY.-.#####",
      requesting_branch: targetBranch,
      preferred_source_branch: sourceBranch,
      source_warehouse: sourceWarehouse,
      allocated_asset: assetName,
      request_date: toIsoDate(new Date()),
      required_by: requiredBy,
      requested_by: requestedBy,
      custom_requested_by_name: requestedByName,
      priority: priority,
      requested_item: item,
      asset_category: assetCategory,
      machinery_category: machineryCategory,
      quantity: quantity,
      requirement_reason: reason,
      additional_remarks: remarks,
      request_status: "Pending Approval"
    };
    if (button) {
      button.disabled = true;
      button.textContent = "Submitting…";
    }
    try {
      const result = await frappeCall("life_create_machinery_request", {
        requesting_branch: doc.requesting_branch,
        preferred_source_branch: doc.preferred_source_branch,
        source_warehouse: doc.source_warehouse,
        allocated_asset: doc.allocated_asset,
        request_date: doc.request_date,
        required_by: doc.required_by,
        requested_by: doc.requested_by,
        requested_by_name: doc.custom_requested_by_name,
        priority: doc.priority,
        requested_item: doc.requested_item,
        asset_category: doc.asset_category,
        machinery_category: doc.machinery_category,
        quantity: doc.quantity,
        requirement_reason: doc.requirement_reason,
        additional_remarks: doc.additional_remarks
      });
      if (!result || result.ok === false) {
        throw new Error((result && result.message) || "Machinery Request could not be created.");
      }
      const created = result.doc || result;
      closeModal();
      showToast("Machinery request " + ((created && created.name) || "") + " sent to the Sales Manager for approval.");
      await loadAllData();
      openPage("movements");
    } catch (error) {
      showToast(error && error.message ? error.message : "Machinery request could not be submitted.", true);
      if (button) {
        button.disabled = false;
        button.textContent = "Submit Machinery Request";
      }
    }
  }

  async function openInlineMachineryTransfer() {
    // A branch user may initiate a transfer from their own permitted branch to
    // any real production branch. STATE.data.branches is permission-scoped, so
    // load the Branch master again for the Target Branch selector.
    const allBranchRecords = await safeDirectList(
      "Branch",
      ["name", "branch"],
      [],
      "branch asc",
      1000
    );
    const branchRecordMap = new Map();
    (allBranchRecords || []).concat(STATE.data.branches || []).forEach(function (row) {
      if (row && row.name) branchRecordMap.set(normalizeBranchText(row.name), row);
    });
    LIFE_TRANSFER_BRANCH_IDS.forEach(function (name) {
      const key = normalizeBranchText(name);
      if (!branchRecordMap.has(key)) branchRecordMap.set(key, { name: name, branch: name });
    });
    const productionBranchRecords = Array.from(branchRecordMap.values()).filter(function (row) {
      const display = canonicalBranchDisplayName(row.branch || row.name || "");
      return row.name && display && !isTestingBranchName(display);
    });
    const transferBranchRecords = productionBranchRecords.filter(function (row) {
      const display = canonicalBranchDisplayName(row.branch || row.name || "");
      return row.name && display && !isTestingBranchName(display) && isBranchAllowedForUser(display);
    });
    const makeBranchOptions = function (records, placeholder, selectedValue, excludedValue) {
      const excludedKey = normalizeBranchText(canonicalBranchDisplayName(excludedValue || ""));
      return ['<option value="">' + escapeHtml(placeholder) + '</option>'].concat(
        records.filter(function (row) {
          if (!excludedKey) return true;
          return normalizeBranchText(canonicalBranchDisplayName(row.branch || row.name || "")) !== excludedKey;
        }).map(function (row) {
          const display = canonicalBranchDisplayName(row.branch || row.name || "");
          const label = display && display !== row.name ? display + " · " + row.name : row.name;
          return '<option value="' + escapeAttribute(row.name) + '"' +
            (normalizeBranchText(row.name) === normalizeBranchText(selectedValue || "") ? ' selected' : '') +
            '>' + escapeHtml(label) + '</option>';
        })
      ).join("");
    };
    const branchValueToDisplay = function (value) {
      const match = productionBranchRecords.find(function (row) { return row.name === value; });
      return match ? canonicalBranchDisplayName(match.branch || match.name || "") : canonicalBranchDisplayName(value || "");
    };
    const lockedSourceBranch = lockedBranchValue();
    const sourceBranchOptions = makeBranchOptions(
      productionBranchRecords,
      "Select Source Branch",
      lockedSourceBranch,
      ""
    );
    const sourceBranchFieldHtml = lockedSourceBranch
      ? [
          '<input value="', escapeAttribute(branchValueToDisplay(lockedSourceBranch)), '" readonly aria-readonly="true">',
          '<input type="hidden" data-operation-field="source_branch" value="', escapeAttribute(lockedSourceBranch), '">'
        ].join("")
      : '<select data-operation-field="source_branch">' + sourceBranchOptions + '</select>';
    const targetBranchOptions = makeBranchOptions(
      productionBranchRecords,
      "Select Target Branch",
      "",
      lockedSourceBranch
    );
    const targetBranchFieldHtml = '<select data-operation-field="target_branch">' + targetBranchOptions + '</select>';
    const requestedByEmployee = await resolveCurrentTransferEmployee();
    const requestedByValue = requestedByEmployee && requestedByEmployee.name ? requestedByEmployee.name : "";
    const requestedByLabel = requestedByValue
      ? (requestedByEmployee.employee_name || "")
      : "No active Employee is linked to " + getCurrentUserId();
    let requestedByFieldHtml = '';
    if (requestedByValue) {
      requestedByFieldHtml = [
        '<input value="', escapeAttribute(requestedByLabel), '" readonly>',
        '<input type="hidden" data-operation-field="requested_by" value="', escapeAttribute(requestedByValue), '">'
      ].join("");
    } else {
      let employeeLinkRows = [];
      try {
        const employeeFilters = { status: "Active" };
        const employeeBranch = branchValueToDisplay(lockedSourceBranch || "");
        if (employeeBranch) employeeFilters.branch = employeeBranch;
        const employeeResults = await frappeCall("frappe.desk.search.search_link", {
          doctype: "Employee",
          txt: "",
          query: "",
          filters: employeeFilters,
          page_length: 500,
          reference_doctype: "Machinery Transfer",
          ignore_user_permissions: 1
        });
        employeeLinkRows = Array.isArray(employeeResults) ? employeeResults : [];
      } catch (error) {
        employeeLinkRows = [];
      }
      const employeeOptions = ['<option value="">Select Transferred By Employee</option>'].concat(
        employeeLinkRows.map(function (row) {
          const value = row && !Array.isArray(row)
            ? (row.value || row.name || "")
            : (Array.isArray(row) ? row[0] : "");
          const description = row && !Array.isArray(row)
            ? (row.description || row.label || "")
            : (Array.isArray(row) ? (row[1] || "") : "");
          if (!value) return "";
          const label = description ? stripHtml(description) : "Employee name unavailable";
          return '<option value="' + escapeAttribute(value) + '">' + escapeHtml(label) + '</option>';
        }).filter(Boolean)
      ).join("");
      requestedByFieldHtml = employeeLinkRows.length
        ? '<select data-operation-field="requested_by">' + employeeOptions + '</select>'
        : [
            '<input value="', escapeAttribute(requestedByLabel), '" readonly>',
            '<input type="hidden" data-operation-field="requested_by" value="">'
          ].join("");
    }
    const transferAssets = getProductionAssets().filter(function (asset) {
      return asset.name && normalize(asset.asset_category || "") === "machinery" &&
        isBranchAllowedForUser(getLifeBranchName(asset.location) || asset.location || "");
    });
    const buildTransferAssetOptions = function (sourceBranch, selectedAsset) {
      const normalizedSource = normalizeBranchText(branchValueToDisplay(sourceBranch || ""));
      const availableAssets = transferAssets.filter(function (asset) {
        if (!normalizedSource) return true;
        return normalizeBranchText(getLifeBranchName(asset.location) || asset.location || "") === normalizedSource;
      });
      return ['<option value="">' + (normalizedSource ? "Select Machinery / Asset" : "Select Source Branch first") + '</option>'].concat(
        availableAssets.map(function (asset) {
          const category = asset.custom_machinery_assets_category || asset.asset_category || "";
          const label = asset.name + " · " + (asset.asset_name || asset.item_name || "Unnamed Asset") +
            (category ? " · " + category : "");
          return '<option value="' + escapeAttribute(asset.name) + '"' +
            (asset.name === selectedAsset ? ' selected' : '') + '>' + escapeHtml(label) + '</option>';
        })
      ).join("");
    };
    const loadTransferAssetOptions = async function (sourceBranch, selectedAsset) {
      const sourceDisplay = branchValueToDisplay(sourceBranch || "");
      if (!sourceBranch || !sourceDisplay) return buildTransferAssetOptions("", selectedAsset);

      const optionMap = new Map();
      transferAssets.forEach(function (asset) {
        if (normalizeBranchText(getLifeBranchName(asset.location) || asset.location || "") !== normalizeBranchText(sourceDisplay)) return;
        optionMap.set(asset.name, {
          value: asset.name,
          label: asset.name + " · " + (asset.asset_name || asset.item_name || "Unnamed Asset") +
            ((asset.custom_machinery_assets_category || asset.asset_category)
              ? " · " + (asset.custom_machinery_assets_category || asset.asset_category)
              : "")
        });
      });

      try {
        const linkResults = await frappeCall("frappe.desk.search.search_link", {
          doctype: "Asset",
          txt: "",
          query: "",
          filters: { location: sourceDisplay, asset_category: "Machinery", docstatus: ["!=", 2] },
          page_length: 1000,
          reference_doctype: "Machinery Transfer",
          ignore_user_permissions: 1
        });
        (Array.isArray(linkResults) ? linkResults : []).forEach(function (row) {
          const value = row && !Array.isArray(row)
            ? (row.value || row.name || "")
            : (Array.isArray(row) ? row[0] : "");
          const description = row && !Array.isArray(row)
            ? (row.description || row.label || "")
            : (Array.isArray(row) ? (row[1] || "") : "");
          if (value) optionMap.set(value, { value: value, label: description ? value + " · " + stripHtml(description) : value });
        });
      } catch (error) {
        // Keep any already-permitted Asset options loaded with the dashboard.
      }

      const options = Array.from(optionMap.values());
      return ['<option value="">' +
        (options.length ? "Select Machinery / Asset" : "No selectable assets found for " + escapeHtml(sourceDisplay)) +
        '</option>'].concat(options.map(function (option) {
          return '<option value="' + escapeAttribute(option.value) + '"' +
            (option.value === selectedAsset ? ' selected' : '') +
            '>' + escapeHtml(option.label) + '</option>';
        })).join("");
    };
    const warehouses = await safeDirectList(
      "Warehouse",
      ["name", "warehouse_name", "is_group", "disabled"],
      [["is_group", "=", 0], ["disabled", "=", 0]],
      "warehouse_name asc",
      1000
    );
    // Link search works with Warehouse Select permission even when normal
    // get_list Read permission is unavailable. Merge both sources and keep the
    // exact Warehouse document ID as the option value.
    let warehouseLinkRows = [];
    try {
      const linkResults = await frappeCall("frappe.desk.search.search_link", {
        doctype: "Warehouse",
        txt: "",
        query: "",
        filters: { is_group: 0, disabled: 0 },
        page_length: 1000,
        reference_doctype: "Machinery Transfer",
        ignore_user_permissions: 1
      });
