          ? (row.value || row.name || "")
          : (Array.isArray(row) ? row[0] : "");
        const description = row && !Array.isArray(row)
          ? (row.description || row.label || "")
          : (Array.isArray(row) ? (row[1] || "") : "");
        return {
          name: value,
          warehouse_name: description || value,
          is_group: 0,
          disabled: 0
        };
      }).filter(function (row) { return Boolean(row.name); });
    } catch (error) {
      warehouseLinkRows = [];
    }
    const warehouseMap = new Map();
    warehouses.concat(warehouseLinkRows).forEach(function (warehouse) {
      if (warehouse && warehouse.name) warehouseMap.set(warehouse.name, warehouse);
    });
    const productionWarehouses = Array.from(warehouseMap.values()).filter(function (warehouse) {
      const value = normalizeText((warehouse.name || "") + " " + (warehouse.warehouse_name || ""));
      return value.indexOf("testing") === -1;
    });
    const buildWarehouseOptions = function (branchValue, selectedWarehouse, sideLabel, autoSelectFirst) {
      const branchKey = normalizeBranchText(branchValueToDisplay(branchValue || ""));
      const matchingWarehouses = productionWarehouses.filter(function (warehouse) {
        if (!branchKey) return true;
        const warehouseBranch = canonicalBranchDisplayName(
          (warehouse.warehouse_name || "") + " " + (warehouse.name || "")
        );
        return normalizeBranchText(warehouseBranch) === branchKey;
      });
      const effectiveSelected = selectedWarehouse ||
        (autoSelectFirst && matchingWarehouses.length === 1 ? matchingWarehouses[0].name : "");
      return matchingWarehouses.length
      ? ['<option value="">Select ' + escapeHtml(sideLabel || "Warehouse") + '</option>'].concat(matchingWarehouses.map(function (warehouse) {
          const label = warehouse.warehouse_name || warehouse.name;
          return '<option value="' + escapeAttribute(warehouse.name) + '"' +
            (warehouse.name === effectiveSelected ? ' selected' : '') +
            '>' + escapeHtml(warehouseDisplayName(label)) + '</option>';
        })).join("")
      : '<option value="">No permitted ' + escapeHtml(sideLabel || "warehouse") + ' found for this branch</option>';
    };
    const now = new Date();
    const localNow = toIsoDate(now) + "T" + currentTimeValue().slice(0, 5);
    const html = [
      '<div class="la-inline-check" data-inline-transfer-form>',
        '<div class="la-inline-check-info">',
          '<div class="la-inline-field"><label>Source Branch *</label>', sourceBranchFieldHtml, '</div>',
          '<div class="la-inline-field"><label>Target Branch *</label>', targetBranchFieldHtml, '</div>',
          '<div class="la-inline-field"><label>Request Date & Time *</label><input type="datetime-local" data-operation-field="request_date_and_time" value="', escapeAttribute(localNow), '"></div>',
          '<div class="la-inline-field"><label>Required By</label><input type="date" data-operation-field="required_by"></div>',
        '</div>',
        '<div class="la-inline-check-info">',
          '<div class="la-inline-field" style="grid-column:span 2"><label>Machinery / Asset *</label><select data-operation-field="asset" disabled>', buildTransferAssetOptions("", ""), '</select></div>',
          '<div class="la-inline-field"><label>Quantity *</label><input type="number" min="1" step="1" value="1" data-operation-field="quantity"></div>',
          '<div class="la-inline-field"><label>Condition Before Transfer *</label><select data-operation-field="condition_before_transfer"><option value="">Select Condition</option><option>Working</option><option>Partially Working</option><option>Not Working</option></select></div>',
        '</div>',
        '<div class="la-inline-check-info">',
          '<div class="la-inline-field"><label>Source Warehouse</label><select data-operation-field="source_warehouse">', buildWarehouseOptions(lockedSourceBranch, "", "Source Warehouse", true), '</select></div>',
          '<div class="la-inline-field"><label>Target Warehouse</label><select data-operation-field="target_warehouse">', buildWarehouseOptions("", "", "Target Warehouse", false), '</select></div>',
          '<div class="la-inline-field" style="grid-column:span 2"><label>Transferred By *</label>', requestedByFieldHtml, '</div>',
        '</div>',
        '<div class="la-inline-field"><label>Transfer Reason *</label><select data-operation-field="transfer_reason"><option value="">Select Transfer Reason</option><option>Branch Requirement</option><option>Replacement</option><option>Repair / Service</option><option>Temporary Transfer</option><option>Other</option></select></div>',
        '<div class="la-inline-field"><label>Remarks</label><textarea rows="2" data-operation-field="remarks"></textarea></div>',
      '</div>'
    ].join("");

    openModal(
      "New Transfer & Shifting Request",
      html,
      '<button type="button" class="la-button" data-action="close-modal">Cancel</button>' +
      '<button type="button" class="la-button la-button-primary" data-action="save-inline-transfer">Save Transfer Request</button>'
    );

    const form = STATE.root.querySelector("[data-inline-transfer-form]");
    const sourceBranchSelect = form ? form.querySelector('[data-operation-field="source_branch"]') : null;
    const targetBranchSelect = form ? form.querySelector('[data-operation-field="target_branch"]') : null;
    const assetSelect = form ? form.querySelector('[data-operation-field="asset"]') : null;
    const sourceWarehouseSelect = form ? form.querySelector('[data-operation-field="source_warehouse"]') : null;
    const targetWarehouseSelect = form ? form.querySelector('[data-operation-field="target_warehouse"]') : null;
    if (sourceBranchSelect && assetSelect) {
      let sourceRefreshSequence = 0;
      const refreshSourceOptions = async function () {
        const refreshId = ++sourceRefreshSequence;
        const selectedAsset = assetSelect.value || "";
        assetSelect.disabled = true;
        assetSelect.innerHTML = '<option value="">Loading source-branch assets…</option>';
        searchableSelectSnapshot(assetSelect);
        const assetOptions = await loadTransferAssetOptions(sourceBranchSelect.value || "", selectedAsset);
        if (refreshId !== sourceRefreshSequence) return;
        assetSelect.innerHTML = assetOptions;
        assetSelect.disabled = !sourceBranchSelect.value;
        searchableSelectSnapshot(assetSelect);
        if (selectedAsset && !Array.from(assetSelect.options).some(function (option) { return option.value === selectedAsset; })) {
          assetSelect.value = "";
        }
        if (sourceWarehouseSelect) {
          const selectedSourceWarehouse = sourceWarehouseSelect.value || "";
          sourceWarehouseSelect.innerHTML = buildWarehouseOptions(
            sourceBranchSelect.value || "",
            selectedSourceWarehouse,
            "Source Warehouse",
            false
