          searchableSelectSnapshot(sourceWarehouseSelect);
        }
      };
      sourceBranchSelect.addEventListener("change", refreshSourceOptions);
      refreshSourceOptions();
    }
    if (targetBranchSelect && targetWarehouseSelect) {
      const refreshTargetWarehouse = function () {
        const selectedTargetWarehouse = targetWarehouseSelect.value || "";
        targetWarehouseSelect.innerHTML = buildWarehouseOptions(
          targetBranchSelect.value || "",
          selectedTargetWarehouse,
          "Target Warehouse",
          true
        );
        searchableSelectSnapshot(targetWarehouseSelect);
