  function wireTransferPhotoPicker(form) {
    if (!form) return;
    const input = form.querySelector("[data-transfer-photo]");
    const preview = form.querySelector("[data-transfer-photo-preview]");
    if (!input || !preview) return;
    form._transferPhotoFiles = Array.isArray(form._transferPhotoFiles) ? form._transferPhotoFiles : [];
    input.addEventListener("change", function () {
      const selectedFiles = Array.from(input.files || []);
      const invalid = selectedFiles.find(function (file) { return !isValidCheckMediaFile(file, "photo"); });
      if (invalid) {
        input.value = "";
        showToast("Please select image files only: JPG, JPEG, PNG, GIF, WEBP, BMP or SVG.", true);
        return;
      }
      const existingKeys = new Set(form._transferPhotoFiles.map(function (file) {
        return [file.name, file.size, file.lastModified].join("::");
      }));
      selectedFiles.forEach(function (file) {
        const key = [file.name, file.size, file.lastModified].join("::");
        if (!existingKeys.has(key)) {
          form._transferPhotoFiles.push(file);
          existingKeys.add(key);
        }
      });
      const files = form._transferPhotoFiles;
      preview.style.display = files.length ? "grid" : "none";
      preview.innerHTML = files.map(function (file) {
        const url = URL.createObjectURL(file);
        return '<div style="border:1px solid #d9e2dc;border-radius:9px;padding:6px;background:#fff;overflow:hidden"><img src="' + escapeAttribute(url) + '" alt="Selected transfer photo" style="width:100%;height:95px;object-fit:cover;border-radius:6px"><small title="' + escapeAttribute(file.name) + '" style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:5px">' + escapeHtml(file.name) + '</small></div>';
      }).join("");
      input.value = "";
    });
  }

  async function uploadMachineryTransferAttachment(transferName, file) {
    if (!transferName || !file) return;
    const data = new FormData();
    data.append("file", file, file.name);
    data.append("doctype", "Machinery Transfer");
    data.append("docname", transferName);
    data.append("is_private", "1");
    const headers = {};
    if (window.frappe && frappe.csrf_token) headers["X-Frappe-CSRF-Token"] = frappe.csrf_token;
    const response = await fetch("/api/method/upload_file", {
      method: "POST",
      credentials: "same-origin",
      headers: headers,
      body: data
    });
    if (!response.ok) throw new Error("Machinery Transfer was saved, but photo " + file.name + " could not be uploaded.");
    let payload = {};
    try {
      payload = await response.json();
    } catch (parseError) {
      payload = {};
    }
    return payload && payload.message ? payload.message : payload;
  }

