  function saveInlineMachineryTransfer(button) {
    const form = STATE.root.querySelector("[data-inline-transfer-form]");
    if (!form || (button && button.disabled)) return;
    const source = inlineOperationField(form, "source_branch");
    const target = inlineOperationField(form, "target_branch");
    const assetName = inlineOperationField(form, "asset");
    const selectedAsset = getProductionAssets().find(function (asset) { return asset.name === assetName; });
    const quantity = Math.max(1, Math.floor(toNumber(inlineOperationField(form, "quantity")) || 1));
    const conditionBefore = inlineOperationField(form, "condition_before_transfer");
    const reason = inlineOperationField(form, "transfer_reason");
    const requestDate = inlineOperationField(form, "request_date_and_time");
    const requestedBy = inlineOperationField(form, "requested_by");
    if (!source || !target || !assetName || !conditionBefore || !requestedBy || !reason || !requestDate) {
      showToast("Source branch, target branch, machinery / asset, condition, requested by, request date and transfer reason are required. Confirm that your User is linked to an active Employee.", true);
      return;
    }
    if (normalizeBranchText(source) === normalizeBranchText(target)) {
      showToast("Source Branch and Target Branch must be different.", true);
      return;
    }
    const doc = {
      doctype: "Machinery Transfer",
      naming_series: "MAT-TRF-.YYYY.-.#####",
      source_branch: source,
      target_branch: target,
      request_date_and_time: frappeDatetimeValue(requestDate),
      required_by: inlineOperationField(form, "required_by"),
      transfer_reason: reason,
      requested_by: requestedBy,
      source_warehouse: inlineOperationField(form, "source_warehouse"),
      target_warehouse: inlineOperationField(form, "target_warehouse"),
      remarks: inlineOperationField(form, "remarks"),
      machinery: [{
        asset: assetName,
        asset_name: selectedAsset ? (selectedAsset.asset_name || selectedAsset.item_name || "") : "",
        quantity: quantity,
        condition_before_transfer: conditionBefore
      }]
    };

    STATE.pendingTransferRequestName = "";
    STATE.pendingTransferDraft = doc;
    const checklistHtml = [
      '<div class="la-inline-check" data-transfer-checklist>',
        '<div class="la-check-note"><b>PRE-SHIPPING &amp; PACKAGING PROTOCOL</b><br>Please complete this checklist before saving the Machinery Transfer.</div>',
        '<div class="la-inline-field"><label>1. Bubble Wrap Protection</label><div>Is the main body, chassis and digital control screen securely wrapped in multi-layered high-density bubble wrap?</div></div>',
        '<div class="la-inline-check-info">',
          '<label><input type="checkbox" data-checklist-field="bubble_wrap_verified"> Verified Secure</label>',
          '<label><input type="checkbox" data-checklist-field="bubble_wrap_na"> N/A</label>',
          '<div class="la-inline-field" style="grid-column:span 2"><label>Total Wrap Layers Applied</label><input type="number" min="0" step="1" data-checklist-value="total_wrap_layers"></div>',
        '</div>',
        '<div class="la-inline-field"><label>2. Protective Shipping Boxes</label><div>Is the equipment safely nested inside its original flight case or a heavy-duty industrial corrugated box with foam inserts?</div></div>',
        '<div class="la-inline-check-info">',
          '<label><input type="checkbox" data-checklist-field="shipping_box_verified"> Verified Secure</label>',
          '<label><input type="checkbox" data-checklist-field="shipping_box_na"> N/A</label>',
          '<div class="la-inline-field" style="grid-column:span 2"><label>Box / Serial No</label><input data-checklist-value="box_serial_no"></div>',
        '</div>',
        '<div class="la-inline-field"><label>3. Probes, Handpieces &amp; Accessories</label><div>List all optical lenses, power cables, keys, foot switches and fiber cables separately.</div></div>',
        '<div class="la-inline-check-info">',
          '<label><input type="checkbox" data-checklist-field="all_items_accounted"> All Items Accounted</label>',
          '<label><input type="checkbox" data-checklist-field="items_missing"> Missing / Indented List</label>',
