  async function confirmInlineMachineryTransfer(button) {
    const form = STATE.root.querySelector("[data-transfer-checklist]");
    const doc = STATE.pendingTransferDraft;
    if (!form || !doc || (button && button.disabled)) return;
    const photoInput = form.querySelector("[data-transfer-photo]");
    const transferPhotos = Array.isArray(form._transferPhotoFiles)
      ? form._transferPhotoFiles.slice()
      : Array.from(photoInput && photoInput.files ? photoInput.files : []);
    const checked = function (name) {
      const field = form.querySelector('[data-checklist-field="' + name + '"]');
      return field && field.checked ? 1 : 0;
    };
    const value = function (name) {
      const field = form.querySelector('[data-checklist-value="' + name + '"]');
      return field ? String(field.value || "").trim() : "";
    };
    const checklist = {
      bubble_wrap_verified: checked("bubble_wrap_verified"),
      bubble_wrap_na: checked("bubble_wrap_na"),
      total_wrap_layers: toNumber(value("total_wrap_layers")),
      shipping_box_verified: checked("shipping_box_verified"),
      shipping_box_na: checked("shipping_box_na"),
      box_serial_no: value("box_serial_no"),
      all_items_accounted: checked("all_items_accounted"),
      items_missing: checked("items_missing"),
      items_qty_packed: value("items_qty_packed"),
      final_confirmation: checked("final_confirmation")
    };
    if ((!checklist.bubble_wrap_verified && !checklist.bubble_wrap_na) ||
        (!checklist.shipping_box_verified && !checklist.shipping_box_na) ||
        (!checklist.all_items_accounted && !checklist.items_missing) ||
        !checklist.final_confirmation) {
      showToast("Complete each checklist section and tick the final confirmation before saving.", true);
      return;
    }
    Object.keys(checklist).forEach(function (key) { doc[key] = checklist[key]; });
    doc.pre_shipping_and_packaging_protocol = [
      "Bubble Wrap: " + (checklist.bubble_wrap_verified ? "Verified Secure" : "N/A") + (checklist.total_wrap_layers ? " · Layers: " + checklist.total_wrap_layers : ""),
      "Shipping Box: " + (checklist.shipping_box_verified ? "Verified Secure" : "N/A") + (checklist.box_serial_no ? " · Box/Serial: " + checklist.box_serial_no : ""),
      "Accessories: " + (checklist.all_items_accounted ? "All Items Accounted" : "Missing / Indented List"),
      checklist.items_qty_packed ? "Items Packed: " + checklist.items_qty_packed : "",
      "Final Confirmation: Yes"
    ].filter(Boolean).join("\n");
    doc.transfer_status = "Ready for Dispatch";

    if (button) { button.disabled = true; button.textContent = "Saving…"; }
    try {
      const linkedRequestName = STATE.pendingTransferRequestName || "";
      let saved;
      if (linkedRequestName) {
        saved = await frappeCall("life_get_machinery_transfers", {
          action: "create_from_request",
          request_name: linkedRequestName,
          requested_by: doc.requested_by,
          request_date_and_time: doc.request_date_and_time,
          transfer_reason: doc.transfer_reason,
          remarks: doc.remarks,
          target_warehouse: doc.target_warehouse,
          condition_before_transfer: doc.machinery && doc.machinery[0] ? doc.machinery[0].condition_before_transfer : "",
          bubble_wrap_verified: doc.bubble_wrap_verified || 0,
          bubble_wrap_na: doc.bubble_wrap_na || 0,
          total_wrap_layers: doc.total_wrap_layers || 0,
          shipping_box_verified: doc.shipping_box_verified || 0,
          shipping_box_na: doc.shipping_box_na || 0,
          box_serial_no: doc.box_serial_no || "",
          all_items_accounted: doc.all_items_accounted || 0,
          items_missing: doc.items_missing || 0,
          items_qty_packed: doc.items_qty_packed || "",
          final_confirmation: doc.final_confirmation || 0,
          pre_shipping_and_packaging_protocol: doc.pre_shipping_and_packaging_protocol || ""
        });
      } else {
        saved = await frappeCall("frappe.client.insert", { doc: doc });
      }
      const savedTransferName = saved && saved.name ? saved.name : "";
      let readyUpdateError = "";
      if (savedTransferName && normalize(saved.transfer_status || saved.workflow_state || "") !== "ready for dispatch") {
        try {
          saved = await frappeCall("life_mark_machinery_transfer_ready", {
            transfer_name: savedTransferName
          });
        } catch (readyError) {
          // Creation and the Ready-for-Dispatch update are separate secured
          // operations. Do not report a successfully created transfer as a
          // total failure or invite a duplicate retry when Write permission is
          // missing. Photos can still be attached to the created document.
          readyUpdateError = readyError && readyError.message
            ? readyError.message
            : "Write permission is required to mark this transfer Ready for Dispatch.";
          void 0;
        }
      }
      const failedPhotos = [];
      if (transferPhotos.length && !savedTransferName) {
        failedPhotos.push.apply(failedPhotos, transferPhotos.map(function (file) { return file.name; }));
      } else {
        for (let index = 0; index < transferPhotos.length; index += 1) {
          if (button) button.textContent = "Uploading Photo " + (index + 1) + " / " + transferPhotos.length + "…";
          try {
            await uploadMachineryTransferAttachment(savedTransferName, transferPhotos[index]);
          } catch (uploadError) {
            failedPhotos.push(transferPhotos[index].name);
            void 0;
          }
        }
      }
      closeModal();
      STATE.pendingTransferDraft = null;
      STATE.pendingTransferRequestName = "";
      showToast(
        "Machinery transfer " + (savedTransferName || "") +
        (readyUpdateError
          ? " was created, but it is not Ready for Dispatch. Grant Write permission on Machinery Transfer to the source-branch role, then use Make Ready for Dispatch. " + readyUpdateError
          : " is ready for dispatch. No transfer approval is required.") +
        (failedPhotos.length ? " Photo upload failed: " + failedPhotos.join(", ") : transferPhotos.length ? " " + transferPhotos.length + " photo(s) attached." : ""),
        !!failedPhotos.length || !!readyUpdateError
      );
      await loadAllData();
      openPage("movements");
    } catch (error) {
      showToast(error && error.message ? error.message : "Could not save transfer request.", true);
      if (button) { button.disabled = false; button.textContent = "Confirm & Save Transfer"; }
    }
  }

  async function openMachineryTransferDetail(transferName) {
    if (!transferName) return;
    openModal(
      "Machinery Transfer · " + transferName,
      '<div class="la-check-empty">Loading transfer details…</div>',
      '<button type="button" class="la-button" data-action="close-modal">Close</button>'
    );
    try {
      const doc = await frappeCall("life_get_machinery_transfers", { transfer_name: transferName });
      let attachments = [];
      try {
        attachments = await getListWithoutPermissionPopup({
          doctype: "File",
          fields: ["name", "file_name", "file_url", "file_type", "is_private", "creation"],
          filters: [
            ["attached_to_doctype", "=", "Machinery Transfer"],
            ["attached_to_name", "=", transferName]
          ],
          orderBy: "creation asc"
        });
      } catch (attachmentError) {
        void 0;
        attachments = [];
      }
      if (doc.transfer_photo && !attachments.some(function (file) { return file.file_url === doc.transfer_photo; })) {
        attachments.push({
          file_name: String(doc.transfer_photo).split("/").pop() || "Transfer Photo",
          file_url: doc.transfer_photo,
          file_type: "Image"
        });
      }
      (Array.isArray(doc.transfer_photos) ? doc.transfer_photos : []).forEach(function (row, index) {
        const url = row.photo || row.attachment || row.file_url || "";
        if (!url || attachments.some(function (file) { return file.file_url === url; })) return;
        attachments.push({
          file_name: row.caption || (String(url).split("/").pop() || "Transfer Photo " + (index + 1)),
          file_url: url,
          file_type: "Image"
        });
      });
      const machinery = Array.isArray(doc.machinery) ? doc.machinery : [];
      const machineryHtml = machinery.length ? [
        '<div class="la-inline-check-table" style="margin-top:12px">',
          '<div class="la-inline-check-row is-head" style="grid-template-columns:48px 1.2fr 1.4fr 100px 1fr"><span>No.</span><span>Asset</span><span>Asset Name</span><span>Quantity</span><span>Condition Before Transfer</span></div>',
          machinery.map(function (row, index) {
            return '<div class="la-inline-check-row" style="grid-template-columns:48px 1.2fr 1.4fr 100px 1fr"><span>' + (index + 1) + '</span><b>' + escapeHtml(row.asset || "—") + '</b><span>' + escapeHtml(row.asset_name || "—") + '</span><span>' + escapeHtml(row.quantity == null ? "—" : row.quantity) + '</span><span>' + escapeHtml(row.condition_before_transfer || "—") + '</span></div>';
          }).join(""),
        '</div>'
      ].join("") : emptyStateHtml("No machinery rows", "No machinery child-table rows are available in this transfer.");
      const protocol = doc.pre_shipping_and_packaging_protocol || [
        doc.bubble_wrap_verified ? "Bubble Wrap: Verified Secure" : (doc.bubble_wrap_na ? "Bubble Wrap: N/A" : ""),
        doc.shipping_box_verified ? "Shipping Box: Verified Secure" : (doc.shipping_box_na ? "Shipping Box: N/A" : ""),
        doc.all_items_accounted ? "Accessories: All Items Accounted" : (doc.items_missing ? "Accessories: Missing / Indented List" : ""),
        doc.items_qty_packed ? "Items Packed: " + doc.items_qty_packed : ""
      ].filter(Boolean).join("\n");
      const html = [
        '<div class="la-inline-check">',
          detailGridHtml([
            ["Transfer ID", doc.name || transferName],
            ["Transfer Status", doc.transfer_status || doc.workflow_state || docstatusLabel(doc.docstatus)],
            ["Source Branch", doc.source_branch || "—"],
            ["Target Branch", doc.target_branch || "—"],
            ["Source Warehouse", warehouseDisplayName(doc.source_warehouse) || "—"],
            ["Target Warehouse", warehouseDisplayName(doc.target_warehouse) || "—"],
            ["Transferred By", doc.requested_by_name || STATE.machineryRequestEmployeeNames[doc.requested_by] || "—"],
            ["Request Date & Time", formatDateTime(doc.request_date_and_time)],
            ["Ready for Dispatch On", formatDateTime(doc.ready_for_dispatch_on || doc.protocol_completed_on || (["ready for dispatch", "approved", "in transit", "received", "completed"].indexOf(normalize(doc.transfer_status || doc.workflow_state || "")) !== -1 ? doc.modified : ""))],
            ["Required By", formatDate(doc.required_by)],
            ["Transfer Reason", doc.transfer_reason || "—"],
            ["Created By", doc.owner || "—"],
            ["Last Updated", formatDateTime(doc.modified)]
          ]),
          '<h3 style="margin:14px 0 7px;color:#173f25">Machinery</h3>',
          machineryHtml,
          '<h3 style="margin:14px 0 7px;color:#173f25">Pre-Shipping &amp; Packaging Protocol</h3>',
          '<div class="la-check-note" style="white-space:pre-wrap">', escapeHtml(protocol || "No protocol details recorded."), '</div>',
          '<h3 style="margin:14px 0 7px;color:#173f25">Transfer Photos</h3>',
          machineryTransferPhotoGalleryHtml(attachments),
          '<h3 style="margin:14px 0 7px;color:#173f25">Remarks</h3>',
          '<div class="la-check-note">', escapeHtml(doc.remarks || "No remarks"), '</div>',
        '</div>'
      ].join("");
      const state = String(doc.transfer_status || doc.workflow_state || "Draft");
      let actions = '<button type="button" class="la-button" data-action="close-modal">Close</button>';
      if (["Draft", "Pending Approval", "Pending Stock Manager Approval"].indexOf(state) !== -1 && (isBranchAllowedForUser(doc.source_branch || "") || currentUserHasAnyRole(["Stock Manager", "System Manager"]))) {
        actions += '<button type="button" class="la-button la-button-primary" data-action="mark-transfer-ready" data-transfer-name="' + escapeAttribute(doc.name) + '">Make Ready for Dispatch</button>';
      } else if (["Ready for Dispatch", "Approved"].indexOf(state) !== -1 && (isBranchAllowedForUser(doc.source_branch || "") || currentUserHasAnyRole(["System Manager"]))) {
        actions += '<button type="button" class="la-button la-button-primary" data-action="apply-transfer-workflow" data-transfer-name="' + escapeAttribute(doc.name) + '" data-workflow-action="Dispatch Transfer">Transfer Machinery</button>';
      } else if (state === "In Transit" && (isBranchAllowedForUser(doc.target_branch || "") || currentUserHasAnyRole(["System Manager"]))) {
        actions += '<button type="button" class="la-button la-button-primary" data-action="apply-transfer-workflow" data-transfer-name="' + escapeAttribute(doc.name) + '" data-workflow-action="Confirm Received">Machinery Received</button>' +
          '<button type="button" class="la-button" data-action="apply-transfer-workflow" data-transfer-name="' + escapeAttribute(doc.name) + '" data-workflow-action="Not Received">Not Received</button>';
      }
      openModal("Machinery Transfer · " + (doc.name || transferName), html, actions);
    } catch (error) {
      openModal(
        "Machinery Transfer · " + transferName,
        noticeHtml("Could not load transfer", error && error.message ? error.message : "The transfer details could not be read.", "bad"),
        '<button type="button" class="la-button" data-action="close-modal">Close</button>'
      );
    }
  }

  async function applyMachineryTransferWorkflow(transferName, workflowAction, button) {
    if (!transferName || !workflowAction || (button && button.disabled)) return;
    let receiptReason = "";
    if (workflowAction === "Not Received") {
      const enteredReason = window.prompt("Enter why the machinery was not received:", "");
      if (enteredReason == null) return;
      receiptReason = String(enteredReason || "").trim();
      if (!receiptReason) return showToast("Not Received reason is required.", true);
    }
    if (button) {
      button.disabled = true;
      button.textContent = workflowAction + "…";
    }
    try {
      const updated = await frappeCall("life_get_machinery_transfers", {
        action: "apply_workflow",
        transfer_name: transferName,
        workflow_action: workflowAction,
        receipt_reason: receiptReason,
        approval_by: workflowAction === "Approve" ? getCurrentUserId() : "",
        approval_on: workflowAction === "Approve" ? currentFrappeDatetime() : ""
      });
      showToast(
        transferName + " · " + workflowAction + " completed" +
        (updated && updated.workflow_state ? " · " + updated.workflow_state : "") + "."
      );
      closeModal();
      await loadAllData();
      openPage("approvals");
    } catch (error) {
      showToast(error && error.message ? error.message : "Workflow action could not be completed.", true);
      if (button) {
        button.disabled = false;
        button.textContent = workflowAction;
      }
    }
  }

  async function markMachineryTransferReady(transferName, button) {
    if (!transferName || (button && button.disabled)) return;
    if (button) {
      button.disabled = true;
      button.textContent = "Updating…";
    }
    try {
      await frappeCall("life_mark_machinery_transfer_ready", {
        transfer_name: transferName
      });
      showToast(transferName + " is ready for dispatch. No transfer approval is required.");
      closeModal();
      await loadAllData();
      openPage("movements");
    } catch (error) {
      showToast(error && error.message ? error.message : "Could not move this transfer to Ready for Dispatch.", true);
      if (button) {
        button.disabled = false;
        button.textContent = "Make Ready for Dispatch";
      }
    }
  }

  function routeSlug(value) {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
  }

  function exportCurrentData() {
    const data = STATE.exportData;
    if (!data || !data.columns || !data.rows) {
      showToast("There is no exportable data on this screen.", true);
      return;
    }

    const lines = [data.columns].concat(data.rows).map(function (row) {
      return row.map(csvEscape).join(",");
    });
    const csv = "\ufeff" + lines.join("\r\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = safeFilename(data.title || "asset-report") + "_" + toIsoDate(new Date()) + ".csv";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    showToast("CSV exported.");
  }

  function csvEscape(value) {
    if (value == null) return "";
    const text = String(value).replace(/\r?\n/g, " ");
    return /[",]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
  }

  function safeFilename(value) {
    return String(value || "report")
      .trim()
      .replace(/[^a-z0-9_-]+/gi, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 100) || "report";
  }

  function showToast(message, isError) {
    const toast = STATE.root.querySelector("[data-toast]");
    if (!toast) return;

    clearTimeout(STATE.toastTimer);
    toast.textContent = message || "Done";
    toast.classList.toggle("is-error", Boolean(isError));
    toast.classList.add("is-visible");
    STATE.toastTimer = setTimeout(function () {
      toast.classList.remove("is-visible");
    }, isError ? 5000 : 3000);
  }

  function sourceAvailable(key) {
    return Boolean(STATE.sources[key] && STATE.sources[key].ok);
  }

  function unavailableSourceHtml(doctype, source) {
    const detail = source && source.error ? source.error : "This source could not be read.";
    const title = source && source.skipped ? doctype + " access is not assigned" : doctype + " is unavailable";
    return noticeHtml(
      title,
      "The dashboard did not query this DocType, so no permission popup was triggered. " + escapeHtml(detail) +
        " Ask a System Manager to grant Read permission only when this module should be visible to the current role.",
      "warn"
    );
  }

  function noticeHtml(title, message, tone) {
    const toneClass = tone === "bad" ? " is-bad" : tone === "warn" ? " is-warn" : "";
    return '<div class="la-notice' + toneClass + '"><b>' + escapeHtml(title) + "</b><br>" + message + "</div>";
  }

  function actionBarHtml(actions, note) {
    return '<div class="la-action-bar">' + actions.map(function (action) {
      const styleClass = action.style === "primary"
        ? " la-button-primary"
        : action.style === "gold"
          ? " la-button-gold"
          : " la-button-light";
      return '<button type="button" class="la-button' + styleClass + '" data-action="' + escapeAttribute(action.action) + '">' + escapeHtml(action.label) + "</button>";
    }).join("") + '<div class="la-action-bar-spacer"></div><div class="la-record-note">' + escapeHtml(note || "") + "</div></div>";
  }

  function cardHtml(title, note, body) {
    return '<div class="la-card"><div class="la-card-head"><h3>' + escapeHtml(title) + '</h3><div class="la-card-head-note">' + escapeHtml(note || "") + '</div></div><div class="la-card-body">' + body + "</div></div>";
  }

  function kpiHtml(label, value, subtitle, icon, tone) {
    return '<div class="la-kpi ' + toneClass(tone) + '"><div class="la-kpi-label">' + escapeHtml(label) + '</div><div class="la-kpi-value">' + escapeHtml(value == null ? "0" : String(value)) + '</div><div class="la-kpi-subtitle">' + escapeHtml(subtitle || "") + '</div><div class="la-kpi-icon">' + escapeHtml(icon || "") + "</div></div>";
  }

  function clickableKpiHtml(label, value, subtitle, icon, tone, targetPage) {
    return '<button type="button" class="la-kpi ' + toneClass(tone) + '" data-action="filter-attention" data-target-page="' + escapeAttribute(targetPage) + '"><div class="la-kpi-label">' + escapeHtml(label) + '</div><div class="la-kpi-value">' + escapeHtml(value == null ? "0" : String(value)) + '</div><div class="la-kpi-subtitle">' + escapeHtml(subtitle || "") + '</div><div class="la-kpi-icon">' + escapeHtml(icon || "") + "</div></button>";
  }

  function toneClass(tone) {
    return tone ? "is-" + tone : "";
  }

  function donutHtml(total, operational, maintenance, outOfOrder, retired) {
    const safeTotal = total || 1;
    const p1 = percentageRaw(operational, safeTotal);
    const p2 = p1 + percentageRaw(maintenance, safeTotal);
    const p3 = p2 + percentageRaw(outOfOrder, safeTotal);
    const style = "--la-p1:" + p1 + "%;--la-p2:" + p2 + "%;--la-p3:" + p3 + "%";

    return '<div class="la-donut-wrap"><div class="la-donut" style="' + style + '"><div class="la-donut-centre"><div class="la-donut-number">' + formatNumber(total) + '</div><div class="la-donut-label">Assets</div></div></div><div class="la-legend">' +
      legendRow("Operational", operational, "var(--la-ok)") +
      legendRow("In Maintenance", maintenance, "var(--la-warn)") +
      legendRow("Out of Order", outOfOrder, "var(--la-bad)") +
      legendRow("Retired / Other", retired, "var(--la-grey)") +
      "</div></div>";
  }

  function legendRow(label, value, color) {
    return '<div class="la-legend-row"><span class="la-legend-dot" style="background:' + color + '"></span><span>' + escapeHtml(label) + "</span><b>" + formatNumber(value) + "</b></div>";
  }

  function barChartHtml(rows) {
    if (!rows.length) return emptyStateHtml("No category data", "No assets match the current filter.");
    const max = Math.max.apply(null, rows.map(function (row) { return toNumber(row.value); }).concat([1]));
    return '<div class="la-bar-list">' + rows.map(function (row) {
      const width = Math.max(2, Math.round(toNumber(row.value) / max * 100));
      return '<div class="la-bar-row"><div class="la-bar-label" title="' + escapeAttribute(row.label) + '">' + escapeHtml(row.label) + '</div><div class="la-bar-track"><span class="la-bar-fill" style="width:' + width + '%"></span></div><div class="la-bar-value">' + formatNumber(row.value) + "</div></div>";
    }).join("") + "</div>";
  }

  function detailGridHtml(items) {
    return '<div class="la-detail-grid">' + items.map(function (item) {
      return '<div class="la-detail-item"><div class="la-detail-label">' + escapeHtml(item[0]) + '</div><div class="la-detail-value">' + escapeHtml(item[1] == null || item[1] === "" ? "—" : String(item[1])) + "</div></div>";
    }).join("") + "</div>";
  }

  function timelineHtml(items) {
    if (!items.length) return emptyStateHtml("No timeline events", "No linked history was found for this asset.");
    return '<ol class="la-timeline">' + items.map(function (item) {
      const tone = item.tone ? " is-" + item.tone : "";
      let reference = item.reference ? " · " + escapeHtml(item.reference) : "";
      if (item.doctype && item.reference) {
        const name = escapeAttribute(item.reference);
        let attrs = 'data-doctype="' + escapeAttribute(item.doctype) + '" data-docname="' + name + '"';
        if (item.doctype === "Asset") attrs = 'data-action="show-asset" data-asset-name="' + name + '"';
        if (item.doctype === "Asset Repair") attrs = 'data-action="open-asset-repair-detail" data-repair-name="' + name + '"';
        if (item.doctype === "LIFE Asset Check") attrs = 'data-action="open-check-detail" data-check-name="' + name + '"';
        if (item.doctype === "Technicians And Visits") attrs = 'data-action="open-technician-visit-detail" data-visit-name="' + name + '"';
        if (item.doctype === "Issue") attrs = 'data-action="open-complaint-detail" data-complaint-name="' + name + '"';
        if (item.doctype === "Asset Movement") attrs = 'data-action="open-asset-movement-detail" data-movement-name="' + name + '"';
        if (item.doctype === "Asset Depreciation Schedule") attrs = 'data-action="open-depreciation-detail" data-schedule-name="' + name + '"';
        if (item.doctype === "Asset Activity") attrs = 'data-action="open-asset-activity-detail" data-activity-name="' + name + '"';
        reference = ' · <button type="button" class="la-button la-button-small" ' + attrs + '>Open</button>';
      }
      return '<li class="la-timeline-item' + tone + '"><div class="la-timeline-title">' + escapeHtml(item.title || item.type || "Event") + '</div><div class="la-timeline-meta">' + formatDateTime(item.date) + " · " + escapeHtml(item.type || "Activity") + reference + '</div><div class="la-timeline-body">' + escapeHtml(item.body || "") + "</div></li>";
    }).join("") + "</ol>";
  }

  function emptyStateHtml(title, note) {
    return '<div class="la-empty-state"><div><div class="la-empty-icon">∅</div><div class="la-empty-title">' + escapeHtml(title) + '</div><div class="la-empty-note">' + escapeHtml(note || "") + "</div></div></div>";
  }

  function formatCellValue(value, type) {
    if (value == null || value === "") return "—";
    if (type === "number") return formatNumber(value);
    if (type === "amount") return formatAmount(value);
    return escapeHtml(String(value));
  }

  function dualCell(primaryKey, secondaryKey) {
    return function (row) {
      return '<span class="la-cell-main">' + escapeHtml(row[primaryKey] || "—") + '</span><span class="la-cell-sub">' + escapeHtml(row[secondaryKey] || "") + "</span>";
    };
  }

  function clampCell(key) {
    return function (row) {
      return '<span class="la-cell-clamp" title="' + escapeAttribute(row[key] || "") + '">' + escapeHtml(row[key] || "—") + "</span>";
    };
  }

  function documentButton(doctype, name, label) {
    if (!name) return "—";
    return '<button type="button" class="la-button la-button-small" data-doctype="' + escapeAttribute(doctype) + '" data-docname="' + escapeAttribute(name) + '">' + escapeHtml(label || name) + "</button>";
  }

  function assetButton(name, secondary) {
    if (!name) return "—";
    return '<button type="button" class="la-button la-button-small" data-action="show-asset" data-asset-name="' + escapeAttribute(name) + '">' + escapeHtml(name) + "</button>" + (secondary ? '<span class="la-cell-sub">' + escapeHtml(secondary) + "</span>" : "");
  }

  function badgeHtml(label, tone) {
    return '<span class="la-badge la-badge-' + escapeAttribute(tone || "grey") + '">' + escapeHtml(label == null ? "" : String(label)) + "</span>";
  }

  function statusBadge(status) {
    return badgeHtml(status || "Not Set", statusTone(status));
  }

  function statusTone(status) {
    const value = String(status || "").toLowerCase();
    if (["submitted", "partially depreciated", "fully depreciated", "capitalized", "issue", "receipt"].indexOf(value) !== -1) return "ok";
    if (["in maintenance", "work in progress", "draft"].indexOf(value) !== -1) return "warn";
    if (["out of order", "cancelled", "scrapped"].indexOf(value) !== -1) return "bad";
    if (["sold"].indexOf(value) !== -1) return "gold";
    return "grey";
  }

  function repairStatusBadge(status) {
    const tone = status === "Completed" ? "ok" : status === "Pending" ? "bad" : status === "Cancelled" ? "grey" : "warn";
    return badgeHtml(status || "Not Set", tone);
  }

  function maintenanceStatusBadge(status) {
    const tone = status === "Completed" ? "ok" : status === "Overdue" ? "bad" : status === "Planned" ? "info" : status === "Cancelled" ? "grey" : "warn";
    return badgeHtml(status || "Not Set", tone);
  }

  function movementPurposeBadge(purpose) {
    const tone = purpose === "Transfer" ? "info" : purpose === "Issue" ? "warn" : purpose === "Receipt" ? "ok" : purpose === "Transfer and Issue" ? "gold" : "grey";
    return badgeHtml(purpose || "Not Set", tone);
  }

  function docstatusBadge(docstatus) {
    const value = Number(docstatus);
    if (value === 1) return badgeHtml("Submitted", "ok");
    if (value === 2) return badgeHtml("Cancelled", "bad");
    return badgeHtml("Draft", "warn");
  }

  function docstatusLabel(docstatus) {
    const value = Number(docstatus);
    return value === 1 ? "Submitted" : value === 2 ? "Cancelled" : "Draft";
  }

  function dateAlertHtml(value, forceAlert) {
    if (!value) return "—";
    const alert = forceAlert || isDatePastOrToday(value);
    return alert ? badgeHtml(formatDate(value), "warn") : formatDate(value);
  }

  function isOperationalAsset(asset) {
    return ["Submitted", "Partially Depreciated", "Fully Depreciated", "Capitalized", "Issue", "Receipt"].indexOf(asset.status) !== -1;
  }

  function isRetiredAsset(asset) {
    return ["Sold", "Scrapped", "Cancelled"].indexOf(asset.status) !== -1;
  }

  function getAssetCost(asset) {
    const total = toNumber(asset.total_asset_cost);
    if (total) return total;
    const gross = toNumber(asset.gross_purchase_amount || asset.purchase_amount);
    return gross + toNumber(asset.additional_asset_cost);
  }

  function getAssetBookValue(asset) {
    const rawValue = asset.value_after_depreciation;
    if (rawValue !== null && rawValue !== undefined && rawValue !== "") {
      return Math.max(0, toNumber(rawValue));
    }
    return Math.max(0, getAssetCost(asset) - toNumber(asset.opening_accumulated_depreciation));
  }

  function getRepairCost(row) {
    return toNumber(row.total_repair_cost) || toNumber(row.repair_cost);
  }

  function derivedMaintenanceStatus(row) {
    const status = row.status || row.maintenance_status || "";
    if (status === "Completed" || status === "Cancelled" || status === "Overdue") return status;
    if ((status === "Planned" || status === "Scheduled" || status === "Assigned") && isDatePast(row.scheduled_date || row.due_date)) return "Overdue";
    return status || "Scheduled";
  }

  function isMaintenanceAttention(row) {
    return derivedMaintenanceStatus(row) === "Overdue";
  }

  function getInsuranceAlerts(assets, days) {
    const today = startOfDay(new Date());
    const limit = addDays(today, days || 30);
    return assets.filter(function (asset) {
      const end = parseDate(asset.insurance_end_date);
      return end && end <= limit;
    }).sort(function (a, b) { return compareValues(a.insurance_end_date, b.insurance_end_date); });
  }

  function getDepreciationDueAssets() {
    const today = endOfDay(new Date());
    return STATE.filtered.assets.filter(function (asset) {
      if (!Number(asset.calculate_depreciation)) return false;
      const next = parseDate(asset.next_depreciation_date);
      return next && next <= today && ["Sold", "Scrapped", "Cancelled"].indexOf(asset.status) === -1;
    }).sort(function (a, b) { return compareValues(a.next_depreciation_date, b.next_depreciation_date); });
  }

  function groupBy(rows, keyFunction) {
    return rows.reduce(function (groups, row) {
      const key = keyFunction(row);
      if (!groups[key]) groups[key] = [];
      groups[key].push(row);
      return groups;
    }, {});
  }

  function groupCount(rows, keyFunction) {
    return rows.reduce(function (result, row) {
      const key = keyFunction(row);
      result[key] = (result[key] || 0) + 1;
      return result;
    }, {});
  }

  function indexBy(rows, key) {
    return rows.reduce(function (result, row) {
      result[row[key]] = row;
      return result;
    }, {});
  }

  function sum(rows, getter) {
    return rows.reduce(function (total, row) { return total + toNumber(getter(row)); }, 0);
  }

  function toNumber(value) {
    const number = Number(value);
    return Number.isFinite(number) ? number : 0;
  }

  function formatNumber(value) {
    return new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(toNumber(value));
  }

  function formatAmount(value) {
    const number = toNumber(value);

    if (STATE.amountUnit === "lakh") {
      return "₹ " + new Intl.NumberFormat("en-IN", { maximumFractionDigits: 2 }).format(number / 100000) + " L";
    }

    if (STATE.amountUnit === "crore") {
      return "₹ " + new Intl.NumberFormat("en-IN", { maximumFractionDigits: 2 }).format(number / 10000000) + " Cr";
    }

    return new Intl.NumberFormat("en-IN", {
      style: "currency",
      currency: "INR",
      maximumFractionDigits: 0
    }).format(number);
  }

  function percentage(numerator, denominator) {
    if (!toNumber(denominator)) return 0;
    return Math.round(toNumber(numerator) / toNumber(denominator) * 100);
  }

  function percentageRaw(numerator, denominator) {
    if (!toNumber(denominator)) return 0;
    return Math.max(0, Math.min(100, toNumber(numerator) / toNumber(denominator) * 100));
  }

  function parseDate(value) {
    if (!value) return null;
    if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : new Date(value.getTime());

    const text = String(value).trim();
    if (!text) return null;

    const normalized = text.indexOf(" ") !== -1 && text.indexOf("T") === -1
      ? text.replace(" ", "T")
      : text;
    const date = new Date(normalized);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  function formatDate(value) {
    const date = parseDate(value);
    if (!date) return "—";
    const parts = new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "2-digit" }).formatToParts(date);
    const map = {};
    parts.forEach(function (part) { map[part.type] = part.value; });
    return [map.day, map.month, map.year].join("-");
  }

  function formatDateTime(value) {
    const date = parseDate(value);
    if (!date) return "—";
    const datePart = formatDate(date);
    const timePart = new Intl.DateTimeFormat("en-IN", { hour: "2-digit", minute: "2-digit", hour12: true }).format(date).toLowerCase();
    return datePart + " · " + timePart;
  }

  function approvalDurationText(raisedOn, approvedOn, pending) {
    const raised = parseDate(raisedOn);
    const ended = parseDate(approvedOn) || (pending ? new Date() : null);
    if (!raised || !ended || ended < raised) return approvedOn ? "—" : (pending ? "Waiting" : "Not recorded");
    let totalMinutes = Math.max(0, Math.floor((ended.getTime() - raised.getTime()) / 60000));
    const days = Math.floor(totalMinutes / 1440);
    totalMinutes -= days * 1440;
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes - hours * 60;
    const parts = [];
    if (days) parts.push(days + "d");
    if (hours || days) parts.push(hours + "h");
    parts.push(minutes + "m");
    return (pending ? "Waiting · " : "") + parts.join(" ");
  }

  function approvalTimelineHtml(raisedOn, approvedOn, status) {
    const normalizedStatus = normalize(status || "");
    const pending = !approvedOn && normalizedStatus.indexOf("pending") !== -1;
    return '<span class="la-approval-timeline">' +
      '<small>Raised On</small><b>' + escapeHtml(formatDateTime(raisedOn)) + '</b>' +
      '<small>Approved On</small><b>' + escapeHtml(approvedOn ? formatDateTime(approvedOn) : (pending ? "Pending" : "Not recorded")) + '</b>' +
      '<span class="la-duration">' + escapeHtml(approvalDurationText(raisedOn, approvedOn, pending)) + '</span>' +
      '</span>';
  }

  function toIsoDate(value) {
    const date = parseDate(value);
    if (!date) return "";
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return year + "-" + month + "-" + day;
  }

  function startOfDay(value) {
    const date = parseDate(value) || new Date();
    date.setHours(0, 0, 0, 0);
    return date;
  }

  function endOfDay(value) {
    const date = parseDate(value) || new Date();
    date.setHours(23, 59, 59, 999);
    return date;
  }

  function addDays(value, days) {
    const date = parseDate(value) || new Date();
    date.setDate(date.getDate() + Number(days || 0));
    return date;
  }

  function isDatePast(value) {
    const date = parseDate(value);
    return Boolean(date && endOfDay(date) < startOfDay(new Date()));
  }

  function isDatePastOrToday(value) {
    const date = parseDate(value);
    return Boolean(date && startOfDay(date) <= startOfDay(new Date()));
  }

  function dateDiffDays(fromValue, toValue) {
    const from = startOfDay(fromValue);
    const to = startOfDay(toValue);
    return Math.round((to.getTime() - from.getTime()) / 86400000);
  }

  function ageInMonths(value) {
    const date = parseDate(value);
    if (!date) return null;
    const today = new Date();
    let months = (today.getFullYear() - date.getFullYear()) * 12 + (today.getMonth() - date.getMonth());
    if (today.getDate() < date.getDate()) months -= 1;
    return Math.max(0, months);
  }

  function formatAge(months) {
    if (months == null) return "—";
    const years = Math.floor(months / 12);
    const remaining = months % 12;
    if (!years) return remaining + " mo";
    if (!remaining) return years + " yr" + (years === 1 ? "" : "s");
    return years + " yr " + remaining + " mo";
  }

  function calculatedDowntime(failureDate, completionDate) {
    const failure = parseDate(failureDate);
    if (!failure) return "";
    const completion = parseDate(completionDate) || new Date();
    const hours = Math.max(0, Math.round((completion.getTime() - failure.getTime()) / 3600000));
    if (hours < 24) return hours + " hour(s)";
    return Math.round(hours / 24) + " day(s)";
  }

  function normalizeText(value) {
    const text = String(value == null ? "" : value)
      .trim()
      .toLowerCase();

    // Keep matching stable for names that contain accented characters while
    // remaining compatible with older browsers used by ERPNext deployments.
    if (typeof text.normalize === "function") {
      return text.normalize("NFKD").replace(/[\u0300-\u036f]/g, "");
    }

    return text;
  }

  function normalize(value) {
    return normalizeText(value);
  }

  function yesNo(value) {
    return Number(value) ? "Yes" : "No";
  }

  function joinReference(doctype, name) {
    return [doctype, name].filter(Boolean).join(" · ");
  }

  function escapeHtml(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function escapeAttribute(value) {
    return escapeHtml(value).replace(/`/g, "&#096;");
  }

  function initAmountToggle() {
    STATE.root.querySelectorAll("[data-amount-unit]").forEach(function (button) {
      button.addEventListener("click", function () {
        STATE.amountUnit = button.dataset.amountUnit || "full";
        STATE.root.querySelectorAll("[data-amount-unit]").forEach(function (other) {
          other.classList.toggle("is-active", other === button);
        });
        renderCurrentPage();
      });
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () { setTimeout(start, 0); }, { once: true });
  } else {
    setTimeout(start, 0);
  }

  window.LIFE_ASSET_DASHBOARD = {
    refresh: loadAllData,
    openPage: openPage,
    getState: function () { return STATE; }
  };
})();
